/* #region SECTION 15: Toast Notifications */
@media all {
    
    #toast-box {
        position: fixed;
        top: 30px;
        /* Distance from the top of the screen */
        left: 50%;
        /* Move horizontal starting point to center */
        transform: translateX(-50%);
        /* Shift left by 50% of its own width for perfect center */
        z-index: 10000;
        /* Keep above all other UI elements */
        display: flex;
        flex-direction: column;
        gap: 10px;
        pointer-events: none;
        /* Allow background clicks through the invisible container */
    }
    
    .toast {
        background: var(--bg-card);
        color: var(--text-main);
        padding: 15px 20px;
        border-radius: 8px;
        border-left: 5px solid var(--brand-primary);
        box-shadow: 0 5px 20px rgba(0, 0, 0, 0.5);
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
        display: flex;
        align-items: center;
        gap: 12px;
        font-size: 14px;
        font-weight: 600;
        min-width: 280px;
        pointer-events: auto;
        /* Make the actual toast box interactable */
        
        /* Starting position for slide-down animation */
        transform: translateY(-100%);
        opacity: 0;
        animation: toastSlideDown 0.4s ease forwards;
    }
    
    .toast i {
        font-size: 18px;
    }
    
    /* Success status modifier */
    .toast.success {
        border-left-color: var(--status-success);
    }
    
    .toast.success i {
        color: var(--status-text-success);
    }
    
    /* Error status modifier */
    .toast.error {
        border-left-color: var(--brand-primary);
    }
    
    .toast.error i {
        color: var(--brand-primary);
    }
    
    /* Mobile responsive adjustments */
    @media (max-width: 480px) {
        #toast-box {
            width: 90%;
            /* Prevent edge-to-edge stretching on small screens */
            top: 20px;
            /* Slightly closer to the top on mobile */
        }
        
        .toast {
            min-width: unset;
            width: 100%;
            /* Fill the container width */
        }
    }
    
    /* Custom animation for top-center drop */
    @keyframes toastSlideDown {
        to {
            transform: translateY(0);
            opacity: 1;
        }
    }
    
}

