/* #region SECTION 19: GST/VAT Master — Tool-Specific Components (gst-) */
@media all {
    
    /* ────────────────────────────────────────────────────────────
   19-A: TAX MODE TOGGLE SWITCH
   A custom CSS toggle (pill + sliding knob) that replaces the
   native <input type="checkbox"> appearance. The underlying
   checkbox is hidden; the .gst-slider provides the visual.

   HTML structure:
     <div class="gst-toggle-wrapper">
       <span class="gst-toggle-txt active" id="lblExc">...</span>
       <label class="gst-switch">
         <input type="checkbox" id="taxToggle">
         <span class="gst-slider"></span>
       </label>
       <span class="gst-toggle-txt" id="lblInc">...</span>
     </div>
──────────────────────────────────────────────────────────── */
    
    /* Outer flex row: labels + switch aligned horizontally */
    .gst-toggle-wrapper {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 14px;
        margin-top: 22px;
        margin-bottom: 4px;
        padding: 14px 18px;
        background: var(--bg-container);
        border-radius: var(--radius-md);
        border: 1px solid var(--border-main);
    }
    
    /* Mode label text (Exclusive / Inclusive) */
    .gst-toggle-txt {
        font-size: 13px;
        font-weight: 600;
        color: var(--text-muted);
        transition: var(--transition-base);
        user-select: none;
        letter-spacing: 0.3px;
    }
    
    /* Active label highlighted in brand primary */
    .gst-toggle-txt.active {
        color: var(--brand-primary);
    }
    
    /* The <label> wrapper that contains the hidden checkbox + slider */
    .gst-switch {
        position: relative;
        display: inline-block;
        width: 52px;
        height: 28px;
        flex-shrink: 0;
        cursor: pointer;
    }
    
    /* Hide the native checkbox input — visual is done via .gst-slider */
    .gst-switch input[type="checkbox"] {
        opacity: 0;
        width: 0;
        height: 0;
        position: absolute;
    }
    
    /* The pill track background */
    .gst-slider {
        position: absolute;
        inset: 0;
        background: var(--border-main);
        border-radius: 28px;
        transition: background 0.3s ease;
    }
    
    /* The sliding knob (white circle) */
    .gst-slider::before {
        content: '';
        position: absolute;
        width: 20px;
        height: 20px;
        left: 4px;
        top: 50%;
        transform: translateY(-50%);
        background: #ffffff;
        border-radius: 50%;
        transition: transform 0.3s ease, background 0.3s ease;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
    }
    
    /* When checked: highlight track with brand gradient */
    .gst-switch input:checked+.gst-slider {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
    }
    
    /* When checked: slide the knob to the right */
    .gst-switch input:checked+.gst-slider::before {
        transform: translate(24px, -50%);
    }
    
    /* Focus ring for keyboard accessibility */
    .gst-switch input:focus-visible+.gst-slider {
        outline: 2px solid var(--brand-primary);
        outline-offset: 3px;
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-B: GST RESULT SUMMARY CARD
   Displays the Net Amount, Tax Amount, and Gross Total rows.
   Revealed by script.js on successful calculation.

   HTML structure:
     <div class="gst-result-card">
       <div class="gst-summary-row">
         <span>Label</span>
         <span class="gst-summary-val" id="resNet">...</span>
       </div>
       ...
       <div class="gst-total-row">
         <div class="flex-between">
           <span class="gst-total-label">GROSS TOTAL</span>
           <span class="gst-summary-val gst-total-val" id="resTotal">...</span>
         </div>
       </div>
     </div>
──────────────────────────────────────────────────────────── */
    
    /* Card container — sits inside #resultBox */
    .gst-result-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-top: 20px;
        animation: fadeInUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
    }
    
    /* Individual data row: label on left, value on right */
    .gst-summary-row {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 16px 22px;
        border-bottom: 1px solid var(--border-subtle);
        font-size: 15px;
        color: var(--text-muted);
        gap: 12px;
    }
    
    /* Numeric value displayed on the right side */
    .gst-summary-val {
        font-weight: 700;
        color: var(--text-inverse);
        font-size: 16px;
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
    }
    
    body.light-mode .gst-summary-val {
        color: var(--text-main);
    }
    
    /* Tax amount highlighted in brand accent cyan */
    .gst-val-highlight {
        color: var(--accent-cyan) !important;
    }
    
    /* Gross Total row — visually heavier with brand background tint */
    .gst-total-row {
        padding: 18px 22px;
        background: linear-gradient(135deg, rgba(255, 0, 85, 0.06), rgba(209, 36, 255, 0.06));
        border-top: 2px solid rgba(255, 0, 85, 0.2);
    }
    
    /* "GROSS TOTAL" text label */
    .gst-total-label {
        font-weight: 800;
        color: var(--text-main);
        letter-spacing: 1.5px;
        font-size: 13px;
        text-transform: uppercase;
    }
    
    /* Gross total numeric value — large and gradient-accented */
    .gst-total-val {
        font-size: 22px !important;
        font-weight: 800 !important;
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-C: SKELETON LOADER
   Displayed during the 600ms calculation delay to create a
   premium "loading" feel. The shimmer is a CSS animated
   gradient that sweeps across the box.

   HTML structure:
     <div id="skeletonLoader" class="gst-skeleton-box" aria-hidden="true">
       <div class="gst-skeleton-shimmer"></div>
     </div>

   Visibility controlled by script.js (display:block/none).
──────────────────────────────────────────────────────────── */
    
    /* Hidden by default; script.js sets display:block during calc */
    .gst-skeleton-box {
        display: none;
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        height: 140px;
        margin-top: 20px;
        position: relative;
        overflow: hidden;
    }
    
    /* Sweeping shimmer gradient — animated via @keyframes gstShimmer */
    .gst-skeleton-shimmer {
        position: absolute;
        inset: 0;
        background: linear-gradient(90deg,
                transparent 0%,
                rgba(255, 255, 255, 0.05) 40%,
                rgba(255, 255, 255, 0.1) 50%,
                rgba(255, 255, 255, 0.05) 60%,
                transparent 100%);
        background-size: 200% 100%;
        animation: gstShimmer 1.4s infinite ease-in-out;
    }
    
    body.light-mode .gst-skeleton-shimmer {
        background: linear-gradient(90deg,
                transparent 0%,
                rgba(0, 0, 0, 0.04) 40%,
                rgba(0, 0, 0, 0.07) 50%,
                rgba(0, 0, 0, 0.04) 60%,
                transparent 100%);
        background-size: 200% 100%;
    }
    
    /* Shimmer sweep keyframe */
    @keyframes gstShimmer {
        0% {
            background-position: -200% 0;
        }
        
        100% {
            background-position: 200% 0;
        }
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-D: INPUT ERROR STATE
   Applied to #amountInput when validation fails.
   script.js adds/removes .input-error on the input element.
──────────────────────────────────────────────────────────── */
    
    /* Red border + glow for invalid input — uses existing input selectors */
    input.input-error,
    input.input-error:focus {
        border-color: var(--accent-red) !important;
        box-shadow: 0 0 0 3px rgba(255, 71, 87, 0.15) !important;
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-E: INVOICE MODAL INNER COMPONENTS
   Styles for the white invoice paper content inside
   .modal-overlay > .invoice-paper (defined in Section 11).
   All classes prefixed .inv- for clarity.

   Note: The invoice paper itself (.invoice-paper) is already
   styled in Section 11. These classes style its inner content.
──────────────────────────────────────────────────────────── */
    
    /* ── Action Buttons Bar (Close / Print / PDF) ── */
    /* Positioned at the top-right; excluded from PDF via data-html2canvas-ignore */
    .inv-actions {
        display: flex;
        justify-content: flex-end;
        gap: 10px;
        margin-bottom: 20px;
    }
    
    /* Individual action icon button inside the modal */
    .inv-btn {
        width: 38px;
        height: 38px;
        border-radius: 50%;
        border: 1px solid #e0e0e0;
        background: #f5f5f5;
        color: #444444;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 15px;
        cursor: pointer;
        transition: background 0.2s ease, color 0.2s ease, transform 0.2s ease;
    }
    
    .inv-btn:hover {
        background: #333333;
        color: #ffffff;
        transform: scale(1.08);
    }
    
    /* Close button gets a red hover tint */
    .inv-btn-close:hover {
        background: #da3633;
    }
    
    /* ── Invoice Header (Logo + Meta) ── */
    /* Two-column layout: logo/title on left, ID/date on right */
    .inv-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: 28px;
        padding-bottom: 20px;
        border-bottom: 2px solid #e8e8e8;
        gap: 16px;
    }
    
    /* Left column: logo image + "INVOICE" heading */
    .inv-logo {
        display: flex;
        flex-direction: column;
    }
    
    .inv-logo img {
        max-width: 150px;
        margin-bottom: 10px;
        display: block;
    }
    
    .inv-logo h2 {
        font-size: 28px;
        font-weight: 900;
        color: #111111;
        margin-bottom: 4px;
        letter-spacing: 2px;
    }
    
    .inv-logo p {
        font-size: 13px;
        color: #777777;
    }
    
    /* Right column: Invoice ID + date */
    .inv-meta {
        text-align: right;
        display: flex;
        flex-direction: column;
        gap: 6px;
    }
    
    .inv-meta strong {
        font-size: 18px;
        color: #111111;
        letter-spacing: 1px;
    }
    
    .inv-meta span {
        font-size: 13px;
        color: #666666;
    }
    
    /* ── Invoice Line Items Table ── */
    .inv-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 20px;
        font-size: 14px;
    }
    
    .inv-table thead tr {
        background: #f0f0f0;
    }
    
    .inv-table th {
        padding: 12px 14px;
        text-align: left;
        font-weight: 700;
        color: #333333;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        border-bottom: 2px solid #e0e0e0;
    }
    
    .inv-table td {
        padding: 14px;
        border-bottom: 1px solid #eeeeee;
        color: #444444;
        vertical-align: middle;
    }
    
    .inv-table tbody tr:last-child td {
        border-bottom: none;
    }
    
    .inv-table .text-right {
        text-align: right;
    }
    
    /* ── Grand Total Section ── */
    .inv-total-section {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-top: 16px;
        padding: 16px 20px;
        background: linear-gradient(135deg, #ff0055, #d124ff);
        border-radius: 10px;
        gap: 12px;
    }
    
    /* "Total Payable" label text */
    .inv-grand-label {
        font-size: 14px;
        font-weight: 700;
        color: rgba(255, 255, 255, 0.85);
        text-transform: uppercase;
        letter-spacing: 1px;
    }
    
    /* Grand total numeric value */
    .inv-grand {
        font-size: 24px;
        font-weight: 900;
        color: #ffffff;
        font-variant-numeric: tabular-nums;
    }
    
    /* ── Invoice Footer Note ── */
    .inv-footer-note {
        margin-top: 24px;
        text-align: center;
        font-size: 12px;
        color: #999999;
        line-height: 1.6;
        padding-top: 16px;
        border-top: 1px solid #eeeeee;
    }
    
    /* ── Disclaimer info-card variant (yellow left border) ── */
    /* Replaces the inline style="border-left: 4px solid var(--accent-yellow)" */
    .gst-disclaimer {
        border-left: 4px solid var(--accent-yellow) !important;
    }
    
    /* Disclaimer h2 — removes the standard left border + padding from .info-card h2 */
    .gst-disclaimer-title {
        border-left: none !important;
        padding-left: 0 !important;
        color: var(--accent-yellow) !important;
    }
    
    .gst-disclaimer-title i {
        color: var(--accent-yellow);
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-F: RESPONSIVE — TABLET (max-width: 600px)
──────────────────────────────────────────────────────────── */
    @media (max-width: 600px) {
        
        /* --- Fix for Transaction Amount Input Width --- */
        .input-wrapper .mt-xl,
        .input-wrapper .mt-xl input {
            width: 100% !important;
            box-sizing: border-box !important;
        }
        
        
        /* Toggle wrapper stacks more compactly */
        .gst-toggle-wrapper {
            padding: 12px 14px;
            gap: 10px;
        }
        
        .gst-toggle-txt {
            font-size: 12px;
        }
        
        /* Result card rows reduce padding */
        .gst-summary-row {
            padding: 13px 16px;
            font-size: 14px;
        }
        
        .gst-summary-val {
            font-size: 15px;
        }
        
        /* Gross total value scales down */
        .gst-total-val {
            font-size: 18px !important;
        }
        
        .gst-total-row {
            padding: 15px 16px;
        }
        
        /* Invoice header stacks vertically on tablet */
        .inv-header {
            flex-direction: column;
            align-items: flex-start;
        }
        
        .inv-meta {
            text-align: left;
        }
        
        /* Skeleton reduced height */
        .gst-skeleton-box {
            height: 110px;
        }
        
        /* Grand total row adjusts font sizes */
        .inv-grand {
            font-size: 20px;
        }
    }
    
    
    /* ────────────────────────────────────────────────────────────
   19-G: RESPONSIVE — MOBILE (max-width: 480px)
──────────────────────────────────────────────────────────── */
    @media (max-width: 480px) {
        
        /* Toggle switch shrinks slightly */
        .gst-switch {
            width: 46px;
            height: 26px;
        }
        
        .gst-switch input:checked+.gst-slider::before {
            transform: translate(20px, -50%);
        }
        
        .gst-toggle-txt {
            font-size: 11px;
        }
        
        /* Result card rows tight padding */
        .gst-summary-row {
            padding: 12px 14px;
            font-size: 13px;
            flex-wrap: wrap;
            gap: 6px;
        }
        
        .gst-summary-val {
            font-size: 14px;
        }
        
        /* Gross total row */
        .gst-total-row {
            padding: 12px 14px;
        }
        
        .gst-total-val {
            font-size: 16px !important;
        }
        
        .gst-total-label {
            font-size: 11px;
            letter-spacing: 1px;
        }
        
        /* Skeleton further reduced */
        .gst-skeleton-box {
            height: 90px;
        }
        
        /* Invoice paper inner adjustments */
        .inv-logo h2 {
            font-size: 22px;
        }
        
        .inv-grand {
            font-size: 18px;
        }
        
        .inv-grand-label {
            font-size: 12px;
        }
        
        .inv-total-section {
            padding: 13px 15px;
        }
        
        .inv-table th,
        .inv-table td {
            padding: 10px 10px;
            font-size: 12px;
        }
        
        /* Invoice action buttons slightly smaller */
        .inv-btn {
            width: 34px;
            height: 34px;
            font-size: 13px;
        }
    }
    
}



/* ============================================================
 *  tools-template.css — APPEND THIS BLOCK TO THE END OF FILE
 *  After existing Section 19 (GST/VAT Master Tool-Specific)
 *
 *  SECTION 20: GST/VAT Master — GOD MODE UPGRADE (gst2-)
 *
 *  Prefix convention : .gst2-
 *  New Features      : Discount Module, Qty Input, Tax Split
 *                      (CGST/SGST), Number-to-Words invoice footer,
 *                      Recent Calculations History Panel.
 * ============================================================ */

/* #region SECTION 20: GST/VAT God Mode — Extended Components (gst2-) */
@media all {

    /* ════════════════════════════════════════════════════════════
       20-A: ADVANCED INPUTS GRID
       Three-column grid for Qty, Unit Price, Discount on one row.
       Collapses to 2-col on tablet, 1-col on mobile.
    ════════════════════════════════════════════════════════════ */

    .gst2-advanced-grid {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 14px;
        margin-top: 14px;
    }

    /* Discount type toggle (% vs Flat) — inline pill selector */
    .gst2-discount-type-wrap {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-top: 6px;
    }

    .gst2-disc-pill {
        font-size: 11px;
        font-weight: 700;
        padding: 4px 12px;
        border-radius: 20px;
        border: 1px solid var(--border-main);
        background: transparent;
        color: var(--text-muted);
        cursor: pointer;
        transition: var(--transition-base);
        letter-spacing: 0.4px;
        user-select: none;
    }

    .gst2-disc-pill.active,
    .gst2-disc-pill:hover {
        background: var(--brand-primary);
        color: #ffffff;
        border-color: var(--brand-primary);
    }

    /* Discount label with dynamic unit suffix */
    .gst2-disc-label-unit {
        font-size: 11px;
        font-weight: 600;
        color: var(--accent-cyan);
        margin-left: 4px;
    }


    /* ════════════════════════════════════════════════════════════
       20-B: ADVANCED RESULT CARD ROWS
       Extra rows appended inside .gst-result-card for:
         Quantity × Unit Price line, Subtotal, Discount, then taxes.
    ════════════════════════════════════════════════════════════ */

    /* Section header separator inside the result card */
    .gst2-row-divider {
        display: flex;
        align-items: center;
        padding: 8px 22px;
        background: rgba(255, 0, 85, 0.04);
        border-bottom: 1px solid var(--border-subtle);
        font-size: 10px;
        font-weight: 700;
        color: var(--text-muted);
        letter-spacing: 1.5px;
        text-transform: uppercase;
    }

    /* Discount row — highlighted in accent-orange */
    .gst2-val-discount {
        color: var(--accent-orange) !important;
    }

    /* CGST value — muted cyan tint */
    .gst2-val-cgst {
        color: var(--accent-cyan) !important;
    }

    /* SGST value — muted purple tint */
    .gst2-val-sgst {
        color: var(--accent-purple) !important;
    }

    /* IGST / single tax fallback */
    .gst2-val-igst {
        color: var(--accent-cyan) !important;
    }

    /* Tax split badge — shows "(CGST + SGST)" inline */
    .gst2-split-badge {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        font-size: 10px;
        font-weight: 700;
        padding: 2px 8px;
        border-radius: 20px;
        background: rgba(0, 229, 255, 0.1);
        color: var(--accent-cyan);
        letter-spacing: 0.4px;
        margin-left: 6px;
        vertical-align: middle;
        border: 1px solid rgba(0, 229, 255, 0.2);
    }

    /* Sub-row for CGST/SGST breakdown — indented */
    .gst2-sub-row {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 10px 22px 10px 36px;
        border-bottom: 1px solid var(--border-subtle);
        font-size: 13px;
        color: var(--text-muted);
        gap: 12px;
        background: rgba(0, 229, 255, 0.02);
    }

    .gst2-sub-row:last-of-type {
        border-bottom: 1px solid var(--border-main);
    }

    .gst2-sub-val {
        font-weight: 600;
        font-size: 13px;
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
    }


    /* ════════════════════════════════════════════════════════════
       20-C: RECENT CALCULATIONS HISTORY PANEL
       Collapsible accordion-style panel below the result card.
       Entries loaded from localStorage, newest first.
    ════════════════════════════════════════════════════════════ */

    .gst2-history-wrap {
        margin-top: 18px;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        animation: fadeInUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    /* Accordion header / toggle button */
    .gst2-history-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 14px 20px;
        background: var(--bg-container);
        cursor: pointer;
        user-select: none;
        border: none;
        width: 100%;
        text-align: left;
        transition: background 0.25s ease;
    }

    .gst2-history-header:hover {
        background: var(--bg-card);
    }

    .gst2-history-header-left {
        display: flex;
        align-items: center;
        gap: 10px;
        font-size: 13px;
        font-weight: 700;
        color: var(--text-main);
        letter-spacing: 0.3px;
    }

    .gst2-history-header-left i {
        color: var(--brand-primary);
        font-size: 14px;
    }

    .gst2-history-count {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 20px;
        height: 20px;
        border-radius: 50%;
        background: var(--brand-primary);
        color: #fff;
        font-size: 10px;
        font-weight: 800;
    }

    .gst2-history-chevron {
        color: var(--text-muted);
        font-size: 12px;
        transition: transform 0.3s ease;
    }

    .gst2-history-wrap.open .gst2-history-chevron {
        transform: rotate(180deg);
    }

    /* History list body */
    .gst2-history-body {
        display: none;
        max-height: 320px;
        overflow-y: auto;
        background: var(--bg-card);
        scrollbar-width: thin;
        scrollbar-color: var(--border-main) transparent;
    }

    .gst2-history-wrap.open .gst2-history-body {
        display: block;
    }

    /* Individual history entry */
    .gst2-hist-entry {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 20px;
        border-bottom: 1px solid var(--border-subtle);
        gap: 12px;
        cursor: pointer;
        transition: background 0.2s ease;
    }

    .gst2-hist-entry:last-child {
        border-bottom: none;
    }

    .gst2-hist-entry:hover {
        background: rgba(255, 0, 85, 0.05);
    }

    .gst2-hist-left {
        display: flex;
        flex-direction: column;
        gap: 3px;
        flex: 1;
        min-width: 0;
    }

    .gst2-hist-jurisdiction {
        font-size: 11px;
        font-weight: 700;
        color: var(--accent-cyan);
        letter-spacing: 0.5px;
        text-transform: uppercase;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .gst2-hist-amounts {
        font-size: 12px;
        color: var(--text-muted);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .gst2-hist-time {
        font-size: 10px;
        color: var(--text-muted);
        opacity: 0.6;
        flex-shrink: 0;
        text-align: right;
    }

    .gst2-hist-total {
        font-size: 14px;
        font-weight: 800;
        color: var(--text-inverse);
        font-variant-numeric: tabular-nums;
        flex-shrink: 0;
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
    }

    body.light-mode .gst2-hist-total {
        color: var(--text-main);
    }

    /* Empty state for history */
    .gst2-hist-empty {
        padding: 28px 20px;
        text-align: center;
        font-size: 13px;
        color: var(--text-muted);
    }

    .gst2-hist-empty i {
        display: block;
        font-size: 24px;
        margin-bottom: 8px;
        opacity: 0.4;
    }

    /* Clear history button */
    .gst2-hist-clear-btn {
        display: block;
        width: 100%;
        padding: 10px;
        background: transparent;
        border: none;
        border-top: 1px solid var(--border-main);
        font-size: 12px;
        font-weight: 600;
        color: var(--accent-red);
        cursor: pointer;
        text-align: center;
        transition: background 0.2s ease;
        letter-spacing: 0.3px;
    }

    .gst2-hist-clear-btn:hover {
        background: rgba(255, 71, 87, 0.08);
    }


    /* ════════════════════════════════════════════════════════════
       20-D: INVOICE NUMBER-TO-WORDS FOOTER
       Displayed in the invoice paper below the grand total.
    ════════════════════════════════════════════════════════════ */

    .inv-words-row {
        margin-top: 14px;
        padding: 12px 16px;
        background: #f7f7f7;
        border-radius: 8px;
        border: 1px solid #e8e8e8;
    }

    .inv-words-label {
        font-size: 10px;
        font-weight: 700;
        color: #888888;
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-bottom: 4px;
    }

    .inv-words-text {
        font-size: 13px;
        font-weight: 600;
        color: #333333;
        line-height: 1.5;
        font-style: italic;
    }

    /* Invoice discount & qty detail rows */
    .inv-detail-row {
        display: flex;
        justify-content: space-between;
        font-size: 12px;
        color: #666666;
        padding: 4px 0;
        border-bottom: 1px dashed #eeeeee;
        gap: 8px;
    }

    .inv-detail-row:last-child {
        border-bottom: none;
    }

    .inv-detail-section {
        margin-bottom: 14px;
        padding: 12px 14px;
        background: #fafafa;
        border-radius: 8px;
        border: 1px solid #f0f0f0;
    }

    .inv-detail-section-title {
        font-size: 10px;
        font-weight: 800;
        color: #999999;
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-bottom: 8px;
    }

    /* CGST/SGST split rows inside invoice */
    .inv-split-row {
        display: flex;
        justify-content: space-between;
        font-size: 12px;
        color: #777777;
