        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        padding: 14px 16px;
        font-size: 14px;
        line-height: 1.6;
        color: var(--text-main);
        border-left: 3px solid var(--border-main);
    }

    .emi-ai-response i {
        font-size: 1.1rem;
        margin-right: 8px;
    }


    /* ────────────────────────────────────────────────────────────
   20-C2: LUMP-SUM SAVINGS SUMMARY BOX  (NEW in v2.0)
   Shown below the lump-sum inputs when a time/interest saving
   is detected. Uses a cyan-tinted success style.
──────────────────────────────────────────────────────────── */

    .emi-savings-box {
        background: rgba(0, 229, 255, 0.06);
        border: 1px solid rgba(0, 229, 255, 0.25);
        border-radius: var(--radius-sm);
        padding: 10px 14px;
        font-size: 13px;
        line-height: 1.6;
        color: var(--accent-cyan);
        display: flex;
        align-items: flex-start;
        gap: 8px;
        animation: fadeInUp 0.3s ease both;
    }

    .emi-savings-box i {
        font-size: 1rem;
        margin-top: 2px;
        flex-shrink: 0;
        color: var(--accent-yellow);
    }

    .emi-savings-box strong {
        color: var(--text-inverse);
    }


    /* ────────────────────────────────────────────────────────────
   20-D: BUTTON UTILITIES
──────────────────────────────────────────────────────────── */

    .emi-btn-full {
        width: 100%;
    }

    .emi-btn-icon-only {
        padding: 12px 16px;
        flex: 0;
    }

    /* CSV export button — green tint to match file-export semantics */
    .emi-btn-csv {
        color: var(--status-text-success) !important;
        border-color: rgba(35, 134, 54, 0.4) !important;
    }

    .emi-btn-csv:hover {
        background: rgba(35, 134, 54, 0.12) !important;
    }

    /* Row containing the amortization toggle + CSV export buttons */
    .emi-table-btn-row {
        display: flex;
        gap: 8px;
        align-items: center;
    }

    /* Make the toggle button fill remaining space when next to the CSV icon */
    .emi-table-btn-row .emi-btn-full {
        flex: 1;
    }


    /* ────────────────────────────────────────────────────────────
   20-E: RESULT PANEL (Right Column)
──────────────────────────────────────────────────────────── */

    .emi-result-panel {
        display: flex;
        flex-direction: column;
        gap: 16px;
    }

    .emi-res-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 20px;
        text-align: center;
    }

    .emi-res-card--highlight {
        background: linear-gradient(135deg,
                rgba(255, 0, 85, 0.08),
                rgba(209, 36, 255, 0.08));
        border-color: rgba(255, 0, 85, 0.3);
        box-shadow: 0 0 20px rgba(255, 0, 85, 0.1);
    }

    .emi-res-card--col {
        flex: 1;
    }

    .emi-res-row {
        display: flex;
        gap: 16px;
    }

    .emi-res-label {
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.8px;
        color: var(--text-muted);
        font-weight: 600;
        margin-bottom: 8px;
    }

    .emi-res-value {
        font-size: 32px;
        font-weight: 900;
        color: var(--text-inverse);
        font-variant-numeric: tabular-nums;
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        line-height: 1.2;
    }

    .emi-res-value--sm {
        font-size: 22px;
    }

    .emi-tax-badge {
        display: none;
        margin-top: 10px;
        font-size: 12px;
        font-weight: 700;
        color: var(--status-text-success);
        background: var(--status-success-bg);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-pill);
        padding: 4px 12px;
    }

    .emi-chart-wrapper {
        position: relative;
        height: 240px;
        width: 100%;
    }


    /* ────────────────────────────────────────────────────────────
   20-F: AMORTIZATION SCHEDULE TABLE
──────────────────────────────────────────────────────────── */

    .emi-amortization-wrapper {
        margin-top: 20px;
        overflow-x: auto;
        border-radius: var(--radius-md);
        border: 1px solid var(--border-main);
    }

    .emi-amortization-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 13px;
        min-width: 400px;
    }

    .emi-amortization-table thead tr {
        background: var(--bg-card);
    }

    .emi-amortization-table th {
        padding: 12px 16px;
        text-align: left;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        color: var(--text-muted);
        border-bottom: 2px solid var(--border-main);
        white-space: nowrap;
    }

    .emi-amortization-table td {
        padding: 11px 16px;
        border-bottom: 1px solid var(--border-subtle);
        color: var(--text-main);
        vertical-align: middle;
    }

    .emi-amortization-table tbody tr:last-child td {
        border-bottom: none;
    }

    .emi-amortization-table tbody tr:hover {
        background: rgba(255, 255, 255, 0.02);
    }

    /* Hidden utility — used by JS to toggle panels and table */
    .hidden {
        display: none !important;
    }


    /* ────────────────────────────────────────────────────────────
   20-G: SEO INFO SECTION — IMAGE UTILITIES
──────────────────────────────────────────────────────────── */

    .emi-info-icon {
        display: block;
        margin: 15px auto;
        width: 100px;
        height: 100px;
        border-radius: 50%;
        border: 2px solid var(--brand-primary);
        padding: 5px;
        background: var(--bg-input);
        object-fit: cover;
    }

    .emi-info-chart {
        display: block;
        margin: 15px auto;
        width: 100%;
        max-width: 350px;
        height: auto;
        border-radius: var(--radius-md);
        border: 1px solid var(--border-main);
    }


    /* ────────────────────────────────────────────────────────────
   20-H: RESPONSIVE — TABLET (max-width: 600px)
──────────────────────────────────────────────────────────── */
    @media (max-width: 600px) {

        .emi-calculator-grid {
            grid-template-columns: 1fr;
            gap: 20px;
        }

        .emi-advanced-panel {
            padding: 16px 14px;
        }

        .emi-res-row {
            gap: 10px;
        }

        .emi-res-value {
            font-size: 26px;
        }

        .emi-res-value--sm {
            font-size: 18px;
        }

        .emi-chart-wrapper {
            height: 210px;
        }

        .emi-amortization-table th,
        .emi-amortization-table td {
            padding: 10px 12px;
        }

        /* Savings box responsive */
        .emi-savings-box {
            font-size: 12px;
        }
    }


    /* ────────────────────────────────────────────────────────────
   20-I: RESPONSIVE — MOBILE (max-width: 480px)
──────────────────────────────────────────────────────────── */
    @media (max-width: 480px) {

        .emi-input-section {
            gap: 12px;
        }

        .emi-highlight-val {
            font-size: 11px;
            padding: 2px 8px;
        }

        .emi-advanced-panel {
            padding: 14px 12px;
            gap: 10px;
        }

        .emi-res-row {
            flex-direction: column;
            gap: 10px;
        }

        .emi-res-value {
            font-size: 22px;
        }

        .emi-res-value--sm {
            font-size: 18px;
        }

        .emi-res-card {
            padding: 15px;
        }

        .emi-chart-wrapper {
            height: 190px;
        }

        .emi-amortization-table {
            font-size: 12px;
        }

        .emi-amortization-table th,
        .emi-amortization-table td {
            padding: 9px 10px;
        }

        .emi-ai-response {
            font-size: 13px;
            padding: 12px 14px;
        }

        .emi-section-badge {
            font-size: 9px;
            letter-spacing: 1px;
            padding: 2px 8px;
        }

        /* Table action row stacks on very narrow screens */
        .emi-table-btn-row {
            flex-wrap: wrap;
        }

        /* Savings box tight padding on mobile */
        .emi-savings-box {
            font-size: 12px;
            padding: 9px 12px;
        }
    }


    /* ────────────────────────────────────────────────────────────
   20-J: TOAST POSITION SAFETY OVERRIDE
   Belt-and-suspenders fix: CSS always keeps #toastArea fixed.
   JS also applies these via cssText to handle late CSS loads.
──────────────────────────────────────────────────────────── */

    #toastArea,
    .toast-wrapper {
        position: fixed !important;
        top: 70px;
        left: 50%;
        transform: translateX(-50%);
        z-index: 99999 !important;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 10px;
        pointer-events: none;
        width: max-content;
        max-width: 90vw;
    }

    #toastArea .toast,
    .toast-wrapper .toast {
        pointer-events: auto;
    }

    @media (max-width: 600px) {
        #toastArea,
        .toast-wrapper {
            top: 60px;
            max-width: 92vw;
        }
    }

    @media (max-width: 480px) {
        #toastArea,
        .toast-wrapper {
            top: 56px;
            max-width: 95vw;
        }
    }

}
/* end @media all */
/* #endregion */


/* end @media all */
/* #endregion */













/* ============================================================
 *  tools-template.css — APPEND THIS BLOCK TO THE END OF FILE
 *  After existing Section 20 (Smart EMI Calculator)
 *
 *  SECTION 21: Percentage Master Pro Max — Tool-Specific Components (pct-)
 *  Version  : 3.0.0
 *  Prefix   : .pct-
 *  NOTE     : abc.css (global) is NEVER modified here.
 *             All rules use .pct- prefix or are scoped to
 *             .pct-calculator-grid / .calc-card to prevent
 *             any collision with global styles.
 * ============================================================ */

/* #region SECTION 21: Percentage Master Pro Max (pct-) */
@media all {

    /* ────────────────────────────────────────────────────────────
       21-A: CALCULATOR GRID LAYOUT
    ──────────────────────────────────────────────────────────── */
    .pct-calculator-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
        gap: 22px;
        width: 100%;
        max-width: 1200px;
        margin: 0 auto 30px auto;
        padding: 0 20px;
        box-sizing: border-box;
    }

    /* ────────────────────────────────────────────────────────────
       21-B: CARD HEADER — ICON & TITLE
    ──────────────────────────────────────────────────────────── */
    .pct-card-icon {
        width: 38px;
        height: 38px;
        background: linear-gradient(135deg, rgba(255,0,85,.15), rgba(209,36,255,.15));
        border: 1px solid rgba(255,0,85,.25);
        border-radius: var(--radius-sm);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 16px;
        color: var(--brand-primary);
        flex-shrink: 0;
        transition: var(--transition-base);
    }

    .calc-card:hover .pct-card-icon {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        color: #fff;
        box-shadow: 0 0 12px rgba(255,0,85,.4);
    }

    .pct-card-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-inverse);
        line-height: 1.3;
        flex: 1;            /* push reset button to far right */
    }

    body.light-mode .pct-card-title { color: var(--text-main); }

    /* ────────────────────────────────────────────────────────────
       21-B2: RESET BUTTON (top-right of each card header)
    ──────────────────────────────────────────────────────────── */
    .pct-reset-btn {
        width: 30px;
        height: 30px;
        border-radius: 50%;
        border: 1px solid var(--border-main);
        background: transparent;
        color: var(--text-muted);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        transition: var(--transition-base);
        flex-shrink: 0;
        padding: 0;
    }

    .pct-reset-btn:hover {
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
        transform: rotate(-45deg) scale(1.1);
    }

    /* ────────────────────────────────────────────────────────────
       21-B3: TOOL DESCRIPTION (small subtitle under header)
    ──────────────────────────────────────────────────────────── */
    .pct-tool-desc {
        font-size: 12px;
        color: var(--text-muted);
        margin: -10px 0 12px 0;
        line-height: 1.4;
    }

    /* ────────────────────────────────────────────────────────────
       21-C: INPUT GROUP
    ──────────────────────────────────────────────────────────── */
    .pct-input-group {
        display: flex;
        flex-direction: column;
        gap: 6px;
        margin-bottom: 14px;
    }

    .pct-input-group:last-of-type { margin-bottom: 0; }

    /* ────────────────────────────────────────────────────────────
       21-D: INPUT WRAPPER WITH SUFFIX
    ──────────────────────────────────────────────────────────── */
    .pct-input-wrapper {
        position: relative;
        display: flex;
        width: 100%;
    }

    .pct-suffix {
        position: absolute;
        right: 14px;
        top: 50%;
        transform: translateY(-50%);
        color: var(--text-muted);
        font-size: 13px;
        font-weight: 700;
        pointer-events: none;
        user-select: none;
        z-index: 1;
    }

    .pct-input-wrapper input[type="number"],
    .pct-input-wrapper select {
        width: 100%;
    }

    .pct-input-wrapper:has(.pct-suffix) input { padding-right: 36px; }

    /* ────────────────────────────────────────────────────────────
       21-E: DUAL-INPUT ROW
    ──────────────────────────────────────────────────────────── */
    .pct-dual-row {
        display: flex;
        gap: 12px;
        margin-bottom: 14px;
    }

    .pct-dual-row > .pct-input-wrapper { flex: 1; }

    /* ────────────────────────────────────────────────────────────
       21-F: FRACTION INPUT ROW
    ──────────────────────────────────────────────────────────── */
    .pct-fraction-row {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 14px;
    }

    .pct-fraction-row > .pct-input-wrapper { flex: 1; }

    .pct-fraction-slash {
        font-size: 28px;
        font-weight: 900;
        color: var(--brand-primary);
        flex-shrink: 0;
        line-height: 1;
        margin-top: 2px;
        user-select: none;
    }

    /* ────────────────────────────────────────────────────────────
       21-G: RESULT BOX
    ──────────────────────────────────────────────────────────── */
    .pct-result-box {
        display: none;
        margin-top: 16px;
        border-top: 3px solid transparent;
        border-image: linear-gradient(90deg, var(--brand-primary), var(--accent-purple)) 1;
    }

    .pct-result-box.show {
        display: block;
        animation: fadeInUp 0.4s cubic-bezier(.16,1,.3,1) both;
    }

    .pct-result-label {
        font-size: 12px;
        font-weight: 600;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: .6px;
        margin-bottom: 8px;
    }

    .pct-result-value {
        font-size: 28px;
        font-weight: 900;
        cursor: pointer;
        font-variant-numeric: tabular-nums;
        background: var(--gradient-text-hero);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        line-height: 1.2;
        word-break: break-all;
        transition: opacity .2s ease;
        outline: none;
    }

    .pct-result-value:hover,
    .pct-result-value:focus { opacity: .8; }

    /* When JS sets a color (profit/loss), override the gradient */
    .pct-result-value[style*="color"] {
        -webkit-text-fill-color: unset;
        background: none;
    }

    .pct-copy-hint {
        font-size: 11px;
        color: var(--text-muted);
        margin-top: 6px;
        opacity: .7;
    }

    /* ────────────────────────────────────────────────────────────
       21-H: CALCULATE BUTTON — FULL WIDTH INSIDE CARD
    ──────────────────────────────────────────────────────────── */
    .btn-area .pct-btn-calc { flex: 1; }

    /* ────────────────────────────────────────────────────────────
       21-I: FEATURE IMAGE (SEO banner between hero & info cards)
    ──────────────────────────────────────────────────────────── */
    .pct-feature-img-wrapper {
        display: flex;
        justify-content: center;
        margin-bottom: 40px;
        padding: 0 20px;
    }

    .pct-feature-img {
        max-width: 100%;
        width: 500px;
        height: auto;
        filter: drop-shadow(0 0 30px rgba(0,242,96,.15));
        border-radius: var(--radius-md);
        display: block;
    }

    /* ────────────────────────────────────────────────────────────
       21-J: INFO CARD — STEP DIVIDERS & LISTS
    ──────────────────────────────────────────────────────────── */
    .pct-info-divider {
        margin-bottom: 24px;
        padding-bottom: 22px;
        border-bottom: 1px solid var(--border-subtle);
    }

    .pct-info-divider:last-of-type {
        border-bottom: none;
        margin-bottom: 0;
        padding-bottom: 0;
    }

    .pct-info-list {
        padding-left: 20px;
        color: var(--text-muted);
        font-size: .9rem;
        line-height: 1.7;
        margin-top: 8px;
    }

    .pct-info-list li { margin-bottom: 6px; }

    .pct-list-icon {
        color: var(--accent-cyan);
        margin-right: 8px;
    }

    .pct-faq-q {
        color: var(--text-inverse);
        font-size: 15px;
        display: block;
        margin-bottom: 6px;
        font-weight: 700;
    }

    body.light-mode .pct-faq-q { color: var(--text-main); }

    /* ────────────────────────────────────────────────────────────
       21-K: INPUT ERROR STATE
    ──────────────────────────────────────────────────────────── */
    .pct-input-wrapper input.input-error,
    .pct-input-wrapper input.input-error:focus,
    .pct-fraction-row .pct-input-wrapper input.input-error {
        border-color: var(--accent-red) !important;
        box-shadow: 0 0 0 3px rgba(255,71,87,.15) !important;
    }

    .pct-input-wrapper.focused input,
    .pct-input-wrapper.focused select,
    .pct-dual-row .pct-input-wrapper.focused input,
    .pct-fraction-row .pct-input-wrapper.focused input {
        border-color: var(--brand-primary);
        box-shadow: 0 0 0 3px rgba(255,0,85,.1);
    }

    /* ────────────────────────────────────────────────────────────
       21-L: RESPONSIVE — TABLET (≤ 600px)
    ──────────────────────────────────────────────────────────── */
    @media (max-width: 600px) {
        .pct-calculator-grid {
            grid-template-columns: repeat(2, 1fr);
            gap: 15px;
            padding: 0 12px;
        }
        .pct-feature-img { width: 100%; }
        .pct-result-value { font-size: 24px; }
        .pct-card-icon { width: 34px; height: 34px; font-size: 14px; }
        .pct-card-title { font-size: 14px; }
        .pct-dual-row { gap: 8px; }
        .pct-fraction-slash { font-size: 22px; }
        .pct-feature-img-wrapper { margin-bottom: 25px; }
        .pct-info-divider { margin-bottom: 18px; padding-bottom: 16px; }
    }

    /* ────────────────────────────────────────────────────────────
       21-M: RESPONSIVE — MOBILE (≤ 480px)
    ──────────────────────────────────────────────────────────── */
    @media (max-width: 480px) {
        .pct-calculator-grid {
            grid-template-columns: 1fr;
            gap: 14px;
            padding: 0 4px;
        }
        .pct-result-value { font-size: 22px; }
        .pct-result-label { font-size: 11px; }
        .pct-copy-hint { font-size: 10px; }
        .pct-result-box { margin-top: 12px; }
        .pct-input-group { margin-bottom: 10px; }
        .pct-dual-row { flex-direction: column; gap: 10px; }
        .pct-fraction-row { gap: 8px; }
        .pct-fraction-slash { font-size: 20px; }
        .pct-faq-q { font-size: 14px; }
        .pct-feature-img-wrapper { padding: 0; margin-bottom: 20px; }
        .pct-card-icon { width: 30px; height: 30px; font-size: 13px; }
        .pct-card-title { font-size: 13px; }
    }

    /* ────────────────────────────────────────────────────────────
       21-N: LIGHT MODE OVERRIDES
    ──────────────────────────────────────────────────────────── */
    body.light-mode .pct-result-value {
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
    }

    /* Keep JS color overrides working in light mode too */
    body.light-mode .pct-result-value[style*="color"] {
        -webkit-text-fill-color: unset;
        background: none;
    }

    body.light-mode .pct-result-label { color: var(--text-muted); }

    body.light-mode .pct-feature-img {
        filter: drop-shadow(0 0 20px rgba(0,0,0,.08));
    }

}
/* end @media all */
/* #endregion */


/* #region SECTION 21-O: History Panel & Floating Button */
@media all {

    /* Floating history button — fixed bottom-left */
    .history-btn {
        position: fixed;
        bottom: 30px;
        left: 30px;
        width: 52px;
        height: 52px;
        border-radius: 50%;
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        color: #fff;
        border: none;
        font-size: 20px;
        cursor: pointer;
        z-index: 8000;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 4px 20px rgba(255,0,85,.4);
        transition: var(--transition-base);
    }

    .history-btn:hover {
        transform: scale(1.1);
        box-shadow: 0 6px 28px rgba(255,0,85,.6);
    }

    /* History side panel — slides in from the left */
    .history-panel {
        position: fixed;
        top: 0;
        left: -360px;
        width: 340px;
        height: 100vh;
        background: var(--bg-container);
        border-right: 1px solid var(--border-main);
        z-index: 9500;
        display: flex;
        flex-direction: column;
        padding: 20px;
        box-shadow: 4px 0 30px rgba(0,0,0,.5);
        transition: left .35s cubic-bezier(.16,1,.3,1);
        overflow: hidden;
    }

    .history-panel.active { left: 0; }

    .history-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 20px;
        padding-bottom: 15px;
        border-bottom: 1px solid var(--border-main);
    }

    .history-title {
        font-size: 18px;
        font-weight: 700;
        color: var(--text-inverse);
    }

    body.light-mode .history-title { color: var(--text-main); }

    /* Close button (now a proper button element for accessibility) */
    .history-close-btn {
        width: 32px;
        height: 32px;
        border-radius: 50%;
        border: 1px solid var(--border-main);
        background: transparent;
        color: var(--text-muted);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 16px;
        transition: var(--transition-base);
    }

    .history-close-btn:hover {
        color: var(--brand-primary);
