    }
    
    /* ────────────────────────────────────────────────────────────
   23-H: SCIENTIFIC CALCULATOR KEYPAD
──────────────────────────────────────────────────────────── */
    
    .ocu-calc-panel {
        display: none;
        grid-template-columns: repeat(4, 1fr);
        gap: 8px;
        margin-bottom: 16px;
        padding: 14px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
    }
    
    .ocu-calc-btn {
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 14px 8px;
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        color: var(--text-main);
        font-size: 16px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
        user-select: none;
    }
    
    .ocu-calc-btn:hover {
        background: var(--bg-card);
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
    }
    
    .ocu-calc-btn:active {
        transform: scale(0.94);
    }
    
    .ocu-calc-op {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        border: none;
        color: #ffffff;
    }
    
    .ocu-calc-op:hover {
        color: #ffffff;
        border: none;
        box-shadow: 0 0 12px rgba(255, 0, 85, 0.4);
        border-color: transparent;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-I: CURRENCY TREND CHART
──────────────────────────────────────────────────────────── */
    
    .ocu-chart-container {
        display: none;
        height: 180px;
        margin-bottom: 16px;
        border-radius: var(--radius-md);
        overflow: hidden;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        padding: 12px;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-J: BOTTOM TOOL ACTION BUTTONS ROW
──────────────────────────────────────────────────────────── */
    
    .ocu-controls {
        display: flex;
        gap: 8px;
        justify-content: center;
        flex-wrap: wrap;
    }
    
    .ocu-tool-btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        padding: 10px 18px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-pill);
        color: var(--text-main);
        font-size: 13px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
        white-space: nowrap;
        font-family: inherit;
    }
    
    .ocu-tool-btn:hover {
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
        background: var(--bg-card);
    }
    
    .ocu-tool-btn:active {
        transform: scale(0.96);
    }
    
    .ocu-tool-btn.active {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        border-color: transparent;
        color: #ffffff;
        box-shadow: 0 0 12px rgba(255, 0, 85, 0.3);
    }
    
    /* ────────────────────────────────────────────────────────────
   23-K: INLINE HISTORY PANEL
──────────────────────────────────────────────────────────── */
    
    .ocu-history-panel {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 20px;
        margin-bottom: 20px;
        border-left: 3px solid var(--brand-primary);
    }
    
    .ocu-history-head {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 14px;
    }
    
    .ocu-history-title {
        font-size: 14px;
        font-weight: 700;
        color: var(--brand-primary);
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    .ocu-history-clear-icon {
        cursor: pointer;
        color: var(--text-muted);
        font-size: 14px;
        transition: var(--transition-base);
    }
    
    .ocu-history-clear-icon:hover {
        color: var(--accent-red);
    }
    
    .ocu-history-list {
        display: flex;
        flex-direction: column;
        gap: 8px;
        font-size: 13px;
        color: var(--text-muted);
    }
    
    .ocu-hist-item {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 8px 0;
        border-bottom: 1px solid var(--border-subtle);
        gap: 12px;
    }
    
    .ocu-hist-item:last-child {
        border-bottom: none;
    }
    
    .ocu-hist-text {
        color: var(--text-main);
        font-weight: 500;
        word-break: break-word;
    }
    
    .ocu-hist-time {
        font-size: 11px;
        color: var(--text-muted);
        white-space: nowrap;
        flex-shrink: 0;
        font-variant-numeric: tabular-nums;
    }
    
    .ocu-hist-empty {
        text-align: center;
        opacity: 0.5;
        padding: 14px 0;
        font-size: 13px;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-L: UNIT SELECTION MODAL BOX
──────────────────────────────────────────────────────────── */
    
    .ocu-modal-box {
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 24px;
        width: 90%;
        max-width: 440px;
        max-height: 80vh;
        overflow-y: auto;
        display: flex;
        flex-direction: column;
        gap: 14px;
        box-shadow: var(--shadow-card);
    }
    
    .ocu-modal-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
    }
    
    .ocu-modal-title {
        font-size: 16px;
        font-weight: 700;
        color: var(--text-main);
        margin: 0;
    }
    
    .ocu-modal-close-btn {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: 50%;
        width: 32px;
        height: 32px;
        cursor: pointer;
        color: var(--text-main);
        display: flex;
        align-items: center;
        justify-content: center;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .ocu-modal-close-btn:hover {
        background: var(--brand-primary);
        border-color: var(--brand-primary);
        color: #ffffff;
    }
    
    .ocu-modal-search {
        border-radius: var(--radius-md) !important;
        margin: 0;
    }
    
    .ocu-unit-list {
        display: flex;
        flex-direction: column;
        gap: 4px;
        max-height: 340px;
        overflow-y: auto;
        scrollbar-width: thin;
        scrollbar-color: var(--border-main) transparent;
    }
    
    .ocu-unit-list::-webkit-scrollbar {
        width: 5px;
    }
    
    .ocu-unit-list::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 10px;
    }
    
    .ocu-unit-opt {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 11px 14px;
        border-radius: var(--radius-sm);
        cursor: pointer;
        font-size: 14px;
        font-weight: 500;
        color: var(--text-main);
        border: 1px solid transparent;
        transition: var(--transition-base);
    }
    
    .ocu-unit-opt:hover {
        background: var(--bg-input);
        border-color: var(--border-main);
    }
    
    .ocu-unit-opt.selected {
        background: var(--status-success-bg);
        border-color: var(--status-success-border);
        color: var(--status-text-success);
        font-weight: 700;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-M: SEO SECTION COMPONENTS
──────────────────────────────────────────────────────────── */
    
    .ocu-section-title {
        font-size: clamp(18px, 4vw, 24px);
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 10px;
        line-height: 1.3;
    }
    
    .ocu-use-case-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 16px;
        margin: 24px 0;
    }
    
    .ocu-use-case-card {
        text-align: center;
        padding: 20px 16px;
    }
    
    .ocu-use-case-card h3 {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 8px;
    }
    
    .ocu-use-case-card p {
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.6;
    }
    
    .ocu-icon-box {
        width: 48px;
        height: 48px;
        border-radius: 50%;
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 12px;
        font-size: 18px;
        color: #ffffff;
        box-shadow: 0 4px 14px rgba(255, 0, 85, 0.25);
    }
    
    .ocu-details-wrapper {
        display: grid;
        grid-template-columns: 1fr 2fr;
        gap: 20px;
        margin-top: 20px;
        align-items: start;
    }
    
    .ocu-tech-specs {
        padding: 20px;
    }
    
    .ocu-spec-list {
        list-style: none;
        padding: 0;
        margin: 0;
        display: flex;
        flex-direction: column;
        gap: 10px;
    }
    
    .ocu-spec-list li {
        display: flex;
        align-items: flex-start;
        gap: 8px;
        font-size: 13px;
        line-height: 1.5;
        color: var(--text-main);
    }
    
    .ocu-spec-list li i {
        margin-top: 2px;
        flex-shrink: 0;
    }
    
    .ocu-hub-title {
        font-size: 16px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 14px;
    }
    
    .ocu-article-grid {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }
    
    .ocu-kb-article {
        padding: 16px;
        text-align: left;
    }
    
    .ocu-kb-article h4 {
        font-size: 13px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 6px;
        display: flex;
        align-items: center;
        gap: 6px;
        flex-wrap: wrap;
    }
    
    .ocu-kb-article p {
        font-size: 12px;
        color: var(--text-muted);
        line-height: 1.6;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-N: FAQ SECTION
──────────────────────────────────────────────────────────── */
    
    .ocu-faq-grid {
        display: flex;
        flex-direction: column;
        gap: 10px;
    }
    
    .ocu-faq-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        transition: var(--transition-base);
    }
    
    .ocu-faq-card[open] {
        border-color: var(--accent-cyan);
    }
    
    .ocu-faq-summary {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 16px 18px;
        cursor: pointer;
        font-size: 14px;
        font-weight: 600;
        color: var(--text-main);
        list-style: none;
        user-select: none;
        gap: 12px;
    }
    
    .ocu-faq-summary::-webkit-details-marker {
        display: none;
    }
    
    .ocu-faq-summary:hover {
        color: var(--accent-cyan);
    }
    
    .ocu-faq-arrow {
        flex-shrink: 0;
        font-size: 12px;
        color: var(--text-muted);
        transition: transform 0.3s ease;
    }
    
    .ocu-faq-card[open] .ocu-faq-arrow {
        transform: rotate(180deg);
    }
    
    .ocu-faq-body {
        padding: 0 18px 16px;
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.7;
    }
    
    /* ────────────────────────────────────────────────────────────
   23-O: LIGHT MODE OVERRIDES
──────────────────────────────────────────────────────────── */
    
    body.light-mode .ocu-main-card {
        background: #ffffff;
        border-color: var(--border-main);
    }
    
    body.light-mode .ocu-io-box {
        background: var(--bg-input);
    }
    
    body.light-mode .ocu-unit-select-btn {
        background: #ffffff;
    }
    
    body.light-mode .ocu-calc-panel {
        background: var(--bg-input);
    }
    
    body.light-mode .ocu-calc-btn {
        background: #ffffff;
        color: var(--text-main);
    }
    
    body.light-mode .ocu-tool-btn {
        background: var(--bg-input);
        color: var(--text-main);
    }
    
    body.light-mode .ocu-faq-card {
        background: #ffffff;
    }
    
    body.light-mode .ocu-modal-box {
        background: #ffffff;
    }
    
    body.light-mode .ocu-history-panel {
        background: #ffffff;
    }
    
    body.light-mode .ocu-precision-select {
        background-color: #ffffff;
        color: var(--text-main);
    }
    
    body.light-mode .ocu-toggle-switch {
        background: var(--bg-input);
    }
    
    /* ────────────────────────────────────────────────────────────
   23-P: RESPONSIVE — TABLET (max-width: 600px)
──────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        .ocu-use-case-grid {
            grid-template-columns: 1fr;
            gap: 12px;
        }
        
        .ocu-details-wrapper {
            grid-template-columns: 1fr;
            gap: 16px;
        }
        
        .ocu-article-grid {
            grid-template-columns: 1fr;
        }
        
        .ocu-main-card {
            padding: 18px 14px;
        }
        
        .ocu-chart-container {
            height: 150px;
        }
        
        .ocu-modal-box {
            padding: 18px 16px;
            max-height: 85vh;
        }
        
        .ocu-faq-summary {
            font-size: 13px;
            padding: 14px 16px;
        }
        
        .ocu-calc-btn {
            padding: 12px 6px;
            font-size: 15px;
        }
        
        .ocu-tool-btn {
            padding: 9px 14px;
            font-size: 12px;
        }
        
        .ocu-unit-select-btn {
            padding: 7px 11px;
            font-size: 12px;
        }
        
        .ocu-search-input {
            font-size: 13px;
            padding: 11px 40px 11px 14px;
        }
        
        .ocu-toolbar {
            justify-content: space-between;
        }
    }
    
    /* ────────────────────────────────────────────────────────────
   23-Q: RESPONSIVE — MOBILE (max-width: 480px)
──────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        .ocu-main-card {
            padding: 14px 12px;
            border-radius: var(--radius-md);
        }
        
        .ocu-cat-item {
            padding: 7px 11px;
            font-size: 11px;
        }
        
        .ocu-main-input {
            font-size: clamp(18px, 6vw, 26px);
        }
        
        .ocu-swap-circle {
            width: 34px;
            height: 34px;
        }
        
        .ocu-io-header {
            font-size: 11px;
        }
        
        .ocu-calc-panel {
            gap: 6px;
        }
        
        .ocu-calc-btn {
            padding: 11px 4px;
            font-size: 14px;
        }
        
        .ocu-controls {
            gap: 6px;
        }
        
        .ocu-tool-btn {
            padding: 8px 12px;
            font-size: 11px;
            gap: 4px;
        }
        
        .ocu-chart-container {
            height: 130px;
            padding: 8px;
        }
        
        .ocu-modal-box {
            width: 96%;
            padding: 16px 14px;
            max-height: 90vh;
        }
        
        .ocu-unit-opt {
            padding: 10px 12px;
            font-size: 13px;
        }
        
        .ocu-history-panel {
            padding: 16px 14px;
        }
        
        .ocu-hist-item {
            flex-direction: column;
            align-items: flex-start;
            gap: 3px;
        }
        
        .ocu-faq-summary {
            padding: 13px 14px;
            font-size: 13px;
        }
        
        .ocu-faq-body {
            padding: 0 14px 14px;
            font-size: 12px;
        }
        
        .ocu-section-title {
            font-size: 17px;
        }
        
        .ocu-kb-article {
            padding: 12px;
        }
        
        .ocu-kb-article h4 {
            font-size: 12px;
        }
        
        .ocu-use-case-card {
            padding: 16px 12px;
        }
        
        .ocu-icon-box {
            width: 42px;
            height: 42px;
            font-size: 16px;
        }
        
        .ocu-toolbar {
            gap: 10px;
        }
        
        .ocu-toolbar-label {
            display: none;
        }
        
        .ocu-compound-btn {
            font-size: 10px;
            padding: 3px 7px;
        }
        
        .ocu-compound-input {
            font-size: clamp(16px, 5vw, 22px) !important;
        }
        
        .ocu-toggle-switch {
            width: 68px;
        }
        
        .ocu-toggle-switch.is-decimal .ocu-toggle-knob {
            transform: translateX(40px);
        }
    }
    
}

