/* ============================================================================
   SECTION 27: ADVANCED DEVELOPER TOOLS PANEL
============================================================================ */
@media all {

    /* 27-B: JSON minifier toggle switch (inline in output label) */
    .cck-minify-toggle {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        cursor: pointer;
        user-select: none;
    }

    .cck-toggle-switch {
        position: relative;
        display: inline-flex;
        align-items: center;
        width: 34px;
        height: 18px;
        cursor: pointer;
        flex-shrink: 0;
    }

    .cck-toggle-switch input[type="checkbox"] {
        position: absolute;
        opacity: 0;
        width: 0;
        height: 0;
        pointer-events: none;
    }

    .cck-toggle-slider {
        position: absolute;
        inset: 0;
        background: var(--border-main);
        border-radius: 34px;
        transition: background 0.25s ease;
    }

    .cck-toggle-slider::before {
        content: "";
        position: absolute;
        left: 2px;
        top: 50%;
        transform: translateY(-50%);
        width: 14px;
        height: 14px;
        border-radius: 50%;
        background: var(--text-muted);
        transition: transform 0.25s ease, background 0.25s ease;
    }

    .cck-toggle-switch input[type="checkbox"]:checked + .cck-toggle-slider {
        background: var(--accent-cyan);
    }

    .cck-toggle-switch input[type="checkbox"]:checked + .cck-toggle-slider::before {
        transform: translateY(-50%) translateX(16px);
        background: #ffffff;
    }

    .cck-toggle-switch input[type="checkbox"]:focus-visible + .cck-toggle-slider {
        outline: 2px solid var(--accent-cyan);
        outline-offset: 2px;
    }

    .cck-toggle-label {
        font-size: 11px;
        font-weight: 600;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 0.5px;
        line-height: 1;
    }

    /* 27-C: Accordion container */
    .cck-advanced-panel {
        margin-top: 28px;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        background: var(--bg-card);
    }

    /* 27-D: Accordion toggle button */
    .cck-adv-toggle {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 16px 20px;
        background: transparent;
        border: none;
        cursor: pointer;
        color: var(--text-main);
        font-size: 14px;
        font-weight: 700;
        letter-spacing: 0.3px;
        transition: background 0.2s ease;
        text-align: left;
    }

    .cck-adv-toggle:hover {
        background: var(--bg-hero);
    }

    .cck-adv-toggle-left {
        display: flex;
        align-items: center;
