    .bgr-main-wrapper>#left-panel::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: var(--radius-pill);
    }
    
    /**
 * Right panel — flexible preview area fills remaining space.
 */
    .bgr-main-wrapper>#right-panel {
        flex: 1 1 0;
        min-width: 0;
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════════
   36-B: SECTION LABELS
   Divider-style headings used throughout the left control panel.
══════════════════════════════════════════════════════════════════════════════ */
    
    /**
 * .bgr-section-label
 * Row heading that visually separates control sections.
 * Supports inline toggle switches via margin-left:auto on child elements.
 */
    .bgr-section-label {
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 12px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.8px;
        color: var(--text-muted);
        padding-bottom: 8px;
        margin-bottom: 12px;
        border-bottom: 1px solid var(--border-subtle);
    }
    
    .bgr-section-label i {
        color: var(--brand-primary);
        font-size: 13px;
    }
    
    /**
 * .bgr-control-label
 * Small label above an input row (color pickers, sliders, selects).
 */
    .bgr-control-label {
        display: block;
        font-size: 12px;
        font-weight: 600;
        color: var(--text-muted);
        margin-bottom: 6px;
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════════
   36-C: MAIN DROPZONE
   Dashed upload area. Highlights on hover and drag-over events.
══════════════════════════════════════════════════════════════════════════════ */
    
    /**
 * .bgr-dropzone
 * Full-width dashed border upload area.
 */
    .bgr-dropzone {
        border: 2px dashed var(--border-main);
        border-radius: var(--radius-md);
        background: var(--bg-input);
        cursor: pointer;
        transition: var(--transition-base);
        position: relative;
        overflow: hidden;
        margin-bottom: 16px;
    }
    
    .bgr-dropzone:hover,
    .bgr-dropzone.drag-over {
        border-color: var(--brand-primary);
        background: rgba(255, 0, 85, 0.05);
    }
    
    .bgr-dropzone.drag-over {
        box-shadow: 0 0 0 3px rgba(255, 0, 85, 0.20);
    }
    
    /**
 * .bgr-dropzone-inner
 * Flex column that centres icon, title, subtitle, and badge.
 */
    .bgr-dropzone-inner {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: 28px 20px;
        text-align: center;
    }
    
    /**
 * .bgr-dropzone-icon
 * Large gradient icon — signals the drag & drop interaction.
 */
    .bgr-dropzone-icon {
        font-size: 2.8rem;
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        line-height: 1;
        margin-bottom: 4px;
    }
    
    .bgr-dropzone-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-inverse);
    }
    
    .bgr-dropzone-sub {
        font-size: 12px;
        color: var(--text-muted);
    }
    
    /**
 * .bgr-dropzone-badge
 * "Batch Upload Supported" pill badge shown below the subtitle.
 */
    .bgr-dropzone-badge {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        background: var(--status-success-bg);
        color: var(--status-text-success);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-pill);
        padding: 4px 12px;
        font-size: 11px;
        font-weight: 600;
        margin-top: 4px;
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════════
