    }
    
    /**
 * .ytp-checkbox-label
 * Clickable label wrapping the checkbox input and description text.
 */
    .ytp-checkbox-label {
        cursor: pointer;
        display: flex;
        align-items: center;
        gap: 8px;
        color: var(--text-main);
        font-size: 13px;
        font-weight: 600;
        text-transform: none !important;
        letter-spacing: normal !important;
        user-select: none;
    }
    
    /* Size and accent-color for the checkbox itself */
    .ytp-checkbox-label input[type="checkbox"] {
        width: 18px;
        height: 18px;
        accent-color: var(--brand-primary);
        cursor: pointer;
        flex-shrink: 0;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-K : RESET BUTTON
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .ytp-btn-reset
 * A subtle dashed full-width button to clear all filter adjustments.
 * Uses a hover state that hints at the brand primary colour.
 */
    .ytp-btn-reset {
        width: 100%;
        padding: 10px 16px;
        background: transparent;
        border: 1px dashed var(--border-main);
        color: var(--text-muted);
        border-radius: var(--radius-md);
        cursor: pointer;
        font-size: 13px;
        font-weight: 600;
        transition: var(--transition-base);
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
    }
    
    .ytp-btn-reset:hover {
        color: var(--text-main);
        border-color: var(--brand-primary);
        background: rgba(255, 0, 85, 0.05);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-L : VIDEO METADATA ROWS
   Each row shows an icon + text value + copy icon for channel/video-id info.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .ytp-meta-row
 * A horizontal info row: icon | text (truncated) | copy button.
 */
    .ytp-meta-row {
        display: flex;
        align-items: center;
        gap: 10px;
        background: var(--bg-input);
        padding: 10px 12px;
        border-radius: var(--radius-md);
        margin-bottom: 10px;
        border: 1px solid var(--border-main);
        transition: var(--transition-base);
    }
    
    .ytp-meta-row:hover {
        border-color: var(--accent-cyan);
    }
    
    /* Left icon decorations */
    .ytp-meta-icon-yt {
        color: #ff0000;
        flex-shrink: 0;
        font-size: 15px;
    }
    
    .ytp-meta-icon-id {
        color: var(--text-muted);
        flex-shrink: 0;
        font-size: 15px;
    }
    
    /**
 * .ytp-meta-text
 * Truncated text value for channel name or video ID (monospace for IDs).
 */
    .ytp-meta-text {
        flex: 1;
        font-size: 13px;
        color: var(--text-main);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-family: monospace;
        min-width: 0;
    }
    
    /**
 * .ytp-meta-copy
 * Clickable copy icon on the right of each meta row.
 */
    .ytp-meta-copy {
        color: var(--accent-cyan);
        cursor: pointer;
        padding: 6px;
        border-radius: var(--radius-sm);
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .ytp-meta-copy:hover {
        background: rgba(0, 229, 255, 0.1);
        color: #ffffff;
    }
    
    /**
 * .ytp-vid-title
 * Multi-line video title display, clamped to 3 lines with ellipsis overflow.
 */
    .ytp-vid-title {
        font-size: 14px;
        color: var(--text-main);
        line-height: 1.5;
        display: -webkit-box;
        -webkit-line-clamp: 3;
        -webkit-box-orient: vertical;
        overflow: hidden;
        margin-top: 10px;
        font-weight: 600;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-M : FORMAT LABEL & DOWNLOAD GRID
   Labelled grid of download format buttons (JPG featured, PNG, WebP).
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .ytp-format-label
 * Small uppercase label above the format selection grid.
 */
    .ytp-format-label {
        display: block;
        color: var(--text-muted);
        font-size: 11px;
        text-transform: uppercase;
        font-weight: 700;
        letter-spacing: 0.5px;
        margin-bottom: 12px;
    }
    
    /**
 * .ytp-dl-grid
 * Two-column grid for PNG and WebP buttons; JPG spans both columns.
 */
    .ytp-dl-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px;
    }
    
    /**
 * .ytp-dl-btn
 * Individual format download card with hover lift animation.
 */
    .ytp-dl-btn {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        padding: 16px;
        border-radius: var(--radius-md);
        text-align: center;
        cursor: pointer;
        transition: var(--transition-base);
        position: relative;
        overflow: hidden;
        outline: none;
    }
    
    .ytp-dl-btn:hover {
        border-color: var(--brand-primary);
        background: var(--bg-card);
        transform: translateY(-3px);
        box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
    }
    
    .ytp-dl-btn:focus-visible {
        outline: 2px solid var(--brand-primary);
        outline-offset: 2px;
    }
    
    .ytp-dl-btn strong {
        display: block;
        color: var(--text-main);
        font-size: 15px;
        margin-bottom: 4px;
    }
    
    .ytp-dl-btn span {
        font-size: 11px;
        color: var(--text-muted);
        font-weight: 500;
    }
    
    /**
 * .ytp-dl-featured
 * JPG button that spans both grid columns with a brand-tinted accent.
 */
    .ytp-dl-featured {
        grid-column: span 2;
        background: linear-gradient(135deg, rgba(255, 0, 85, 0.07), transparent);
        border: 1px solid rgba(255, 0, 85, 0.2);
    }
    
    .ytp-dl-featured:hover {
        border-color: var(--brand-primary);
    }
    
    .ytp-dl-featured strong {
        color: var(--brand-primary);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-N : RECENTLY FETCHED HISTORY STRIP
   Horizontally scrollable row of previously loaded thumbnail previews.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .ytp-history-section
 * Wrapper for the history strip; shown only when history exists.
 * A subtle border-top separates it from the workspace above.
 */
    .ytp-history-section {
        margin-top: 30px;
        border-top: 1px solid var(--border-subtle);
        padding-top: 20px;
        text-align: left;
    }
    
    /**
 * .ytp-history-label
 * "RECENTLY FETCHED" label above the scrollable thumbnail strip.
 */
    .ytp-history-label {
        font-size: 11px;
        color: var(--text-muted);
        font-weight: 800;
        letter-spacing: 0.8px;
        text-transform: uppercase;
        display: block;
        margin-bottom: 10px;
    }
    
    /**
 * .ytp-history-scroll
 * Horizontally scrollable flex row for thumbnail history items.
 * Uses smooth scroll and a minimal custom scrollbar.
 */
    .ytp-history-scroll {
        display: flex;
        gap: 12px;
        overflow-x: auto;
        padding-bottom: 10px;
        scroll-behavior: smooth;
        -webkit-overflow-scrolling: touch;
    }
    
    /* Custom scrollbar styling — minimal and on-theme */
    .ytp-history-scroll::-webkit-scrollbar {
        height: 4px;
    }
    
    .ytp-history-scroll::-webkit-scrollbar-track {
        background: transparent;
    }
    
    .ytp-history-scroll::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 2px;
    }
    
    /**
 * .history-thumb
 * Individual history thumbnail image. JS renders these as <img> tags.
 * ID is preserved in the onclick attr generated by JS (do not rename class).
 */
    .history-thumb {
        width: 110px;
        height: 62px;
        border-radius: var(--radius-md);
        object-fit: cover;
        cursor: pointer;
        border: 2px solid transparent;
        opacity: 0.72;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .history-thumb:hover {
        border-color: var(--brand-primary);
        opacity: 1;
        transform: scale(1.05);
        box-shadow: 0 4px 12px rgba(255, 0, 85, 0.25);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-O : RESPONSIVE — TABLET  (max-width: 600px)
   Adjusts workspace layout, input pill, and controls for tablet screens.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* Stack workspace into a single column on tablet */
        .ytp-workspace {
            grid-template-columns: 1fr;
        }
        
        /* Wrap the input pill contents vertically */
        .ytp-input-group {
            flex-direction: column;
            align-items: stretch;
            padding: 14px;
            border-radius: var(--radius-lg);
        }
        
        /* Full-width text field */
        .ytp-url-field {
            width: 100%;
            padding: 6px 0;
        }
        
        /* Action buttons row stays horizontal but fills width */
        .ytp-input-actions {
            width: 100%;
        }
        
        .ytp-input-actions .btn {
            flex: 1;
            padding: 11px 10px;
        }
        
        /* Controls grid collapses to single column on tablet */
        .ytp-controls-grid {
            grid-template-columns: 1fr;
        }
        
        /* JPG featured download spans only 1 column on tablet */
        .ytp-dl-featured {
            grid-column: span 1;
        }
        
        /* History thumbs slightly smaller */
        .history-thumb {
            width: 90px;
            height: 51px;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   44-P : RESPONSIVE — MOBILE  (max-width: 480px)
   Further simplification for small-phone screens (< 480px).
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Compact card boxes on phone */
        .ytp-card-box {
            padding: 14px 12px;
        }
        
        /* Slightly smaller magic button text */
        .ytp-btn-magic {
            font-size: 13px;
            padding: 11px 14px;
        }
        
        /* History thumbs smallest on phone */
        .history-thumb {
            width: 80px;
            height: 45px;
        }
        
        /* Tighten the download grid gap */
        .ytp-dl-grid {
            gap: 8px;
        }
        
        /* Compact download buttons on phone */
        .ytp-dl-btn {
            padding: 12px 8px;
        }
        
        .ytp-dl-btn strong {
            font-size: 13px;
        }
        
        /* Meta rows slightly more compact */
        .ytp-meta-row {
            padding: 8px 10px;
        }
        
        /* Color picker wrapper tighter */
        .ytp-color-picker-wrap {
            padding: 6px 10px;
        }
        
        /* History scroll — even tighter on phone */
        .ytp-history-scroll {
            gap: 8px;
        }
        
    }
    
}

/* end @media all */
/* #endregion */



















/* #region SECTION 45: ULTRA STUDIO PRO MAX — AUDIO EDITOR */
@media all {
    
    /*
 * =============================================================================
 *  SECTION 45 : ULTRA STUDIO PRO MAX — AUDIO EDITOR (aus- prefix)
 *  Tool        : Professional Browser-Based Audio Workstation
 *  Prefix      : aus-
 *  Scope       : Processing overlay, drop zone, waveform editor, DSP control
 *                deck, module cards, cyber buttons, range sliders, export zone.
 *  Responsive  : Fully tested at 600px (tablet) and 480px (mobile phone).
 * =============================================================================
 */
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-A : FULL-SCREEN PROCESSING OVERLAY
   Covers the viewport during heavy async operations (file decode, render,
   MP3/WAV encode). Hidden by default; JS adds .active to show it.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-overlay-loader
 * Fixed full-viewport dark backdrop with a centred loader card.
 * Opacity 0 + pointer-events none when inactive; transitions to visible on .active.
 */
    .aus-overlay-loader {
        position: fixed;
        inset: 0;
        background: var(--bg-overlay-heavy);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 9999;
        opacity: 0;
        pointer-events: none;
        transition: opacity 0.3s ease;
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
    }
    
    /** Active state — revealed when JS calls showLoaderReal() */
    .aus-overlay-loader.active {
        opacity: 1;
        pointer-events: all;
    }
    
    /**
 * .aus-loader-card
 * The centred white/dark card that holds the spinner, text and progress bar.
 */
    .aus-loader-card {
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 36px 40px;
        text-align: center;
        min-width: 300px;
        max-width: 90vw;
        box-shadow: var(--shadow-card);
    }
    
    /**
 * .aus-loader-header
 * Stacks the spinner icon and title label vertically with spacing.
 */
    .aus-loader-header {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        margin-bottom: 16px;
    }
    
    /** Animated microchip spinner icon */
    .aus-loader-icon {
        color: var(--brand-primary);
        font-size: 28px;
    }
    
    /** "SYSTEM PROCESSING" label text above progress */
    .aus-loader-title {
        font-family: 'Orbitron', sans-serif;
        font-size: 13px;
        font-weight: 700;
        letter-spacing: 2px;
        color: var(--text-main);
        text-transform: uppercase;
    }
    
    /** Dynamic status text — updated by JS (e.g. "DECODING BITSTREAM…") */
    .aus-loader-text {
        font-size: 13px;
        color: var(--text-muted);
        margin-bottom: 16px;
        font-family: 'Share Tech Mono', monospace;
    }
    
    /**
 * .aus-progress-container
 * Pill-shaped track for the animated progress bar fill.
 */
    .aus-progress-container {
        background: var(--bg-input);
        border-radius: var(--radius-pill);
        height: 8px;
        overflow: hidden;
        margin-bottom: 10px;
        border: 1px solid var(--border-main);
    }
    
    /**
 * .aus-progress-bar
 * The coloured fill that grows from 0% to 100%. Width set by JS inline style.
 */
    .aus-progress-bar {
        height: 100%;
        width: 0%;
        background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
        border-radius: var(--radius-pill);
        transition: width 0.2s ease;
    }
    
    /** Percentage counter text below progress bar */
    .aus-progress-stats {
        font-family: 'Share Tech Mono', monospace;
        font-size: 13px;
        color: var(--brand-primary);
        font-weight: 700;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-B : FILE UPLOAD DROP ZONE
   The initial landing area shown before any audio is loaded.
   Clickable and drag-and-drop capable; hidden once audio loads.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-drop-zone
 * Dashed-border upload area. JS toggles display:none on successful file load.
 */
    .aus-drop-zone {
        border: 2px dashed var(--border-main);
        border-radius: var(--radius-lg);
        padding: 48px 30px;
        cursor: pointer;
        text-align: center;
        transition: var(--transition-base);
        background: var(--bg-card);
        margin-bottom: 24px;
    }
    
    .aus-drop-zone:hover {
        border-color: var(--brand-primary);
        background: rgba(255, 0, 85, 0.03);
        transform: scale(1.01);
    }
    
    /**
 * .aus-drop-icon
 * Circular icon badge — compact disc icon in the centre of the drop zone.
 */
    .aus-drop-icon {
        width: 72px;
        height: 72px;
        border-radius: 50%;
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 18px;
        font-size: 28px;
        color: #fff;
        box-shadow: 0 8px 24px rgba(255, 0, 85, 0.35);
    }
    
    /** "INITIALIZE AUDIO CORE" heading inside drop zone */
    .aus-drop-title {
        font-family: 'Orbitron', sans-serif;
        font-size: clamp(14px, 3vw, 18px);
        font-weight: 700;
        letter-spacing: 2px;
        color: var(--text-main);
        margin-bottom: 8px;
        text-transform: uppercase;
    }
    
    /** Sub-hint text below the title */
    .aus-drop-hint {
        color: var(--text-muted);
        font-family: 'Rajdhani', sans-serif;
        font-weight: 500;
        font-size: 14px;
        margin-bottom: 24px;
    }
    
    /**
 * .aus-upload-btn-group
 * Side-by-side BROWSE and REC buttons inside the drop zone.
 */
    .aus-upload-btn-group {
        display: flex;
        gap: 12px;
        justify-content: center;
        flex-wrap: wrap;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-C : CYBER BUTTON SYSTEM
   Custom tech-aesthetic buttons used inside the drop zone and DSP module cards.
   These differ from the standard .btn system in that they use a flat/outlined
   dark style suited to the studio control deck context.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-cyber-btn
 * Base cyber button — dark background, monospace font, subtle border.
 */
    .aus-cyber-btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        padding: 10px 18px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        color: var(--text-main);
        font-family: 'Rajdhani', sans-serif;
        font-size: 13px;
        font-weight: 700;
        letter-spacing: 0.8px;
        cursor: pointer;
        transition: var(--transition-base);
        text-transform: uppercase;
        white-space: nowrap;
        outline: none;
    }
    
    .aus-cyber-btn:hover {
        border-color: var(--brand-primary);
        color: var(--brand-primary);
        background: rgba(255, 0, 85, 0.07);
    }
    
    .aus-cyber-btn:active {
        transform: scale(0.97);
    }
    
    /** .aus-cyber-btn--active — highlighted / currently-selected state */
    .aus-cyber-btn--active,
    .aus-cyber-btn.active {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        border-color: var(--brand-primary);
        color: #fff;
        box-shadow: 0 4px 16px rgba(255, 0, 85, 0.4);
    }
    
    /** .aus-cyber-btn--danger — red outline danger state (used on REC button) */
    .aus-cyber-btn--danger,
    .aus-cyber-btn.danger {
        border-color: var(--accent-red);
        color: var(--accent-red);
    }
    
    .aus-cyber-btn--danger:hover,
    .aus-cyber-btn.danger:hover {
        background: rgba(255, 71, 87, 0.1);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-D : EDITOR CONTAINER
   The main workspace revealed after audio is successfully decoded.
   Hidden by default (display:none); JS sets display:block on 'ready' event.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-editor-container
 * Wrapper for the entire editor workspace — visualiser, waveform, deck, export.
 * display:none by default; shown by JS after WaveSurfer 'ready' fires.
 */
    .aus-editor-container {
        display: none;
        margin-top: 10px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-E : SPECTRUM VISUALISER CANVAS
   Animated frequency bar graph drawn on <canvas id="visualizer"> by JS.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-vis-wrapper
 * Container that constrains the canvas height and clips overflow.
 */
    .aus-vis-wrapper {
        width: 100%;
        height: 80px;
        background: #000;
        border-radius: var(--radius-md) var(--radius-md) 0 0;
        overflow: hidden;
        margin-bottom: 0;
    }
    
    /** The canvas itself fills the wrapper */
    .aus-vis-wrapper canvas {
        width: 100% !important;
        height: 100% !important;
        display: block;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-F : WAVESURFER WAVEFORM CONTAINER
   WaveSurfer renders its SVG waveform inside #waveform.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-waveform
 * Hosts the WaveSurfer-generated waveform SVG.
 * Bottom border-radius rounds the visualiser+waveform block together.
 */
    .aus-waveform {
        width: 100%;
        background: var(--bg-card);
        border-radius: 0 0 var(--radius-md) var(--radius-md);
        overflow: hidden;
        margin-bottom: 20px;
        border: 1px solid var(--border-main);
        border-top: none;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-G : DSP CONTROL DECK
   A 2×2 responsive grid of module cards (Transport, Dynamics, EQ, FX).
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-control-deck
 * Two-column grid that collapses to a single column on smaller screens.
 */
    .aus-control-deck {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 16px;
        margin-bottom: 20px;
    }
    
    /**
 * .aus-module-card
 * Individual DSP control panel with a header bar and controls beneath.
 */
    .aus-module-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 18px 16px;
        text-align: left;
        transition: var(--transition-base);
    }
    
    .aus-module-card:hover {
        border-color: rgba(255, 0, 85, 0.3);
    }
    
    /**
 * .aus-module-header
 * Top bar of each module card — title on left, icon on right.
 */
    .aus-module-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 14px;
        padding-bottom: 10px;
        border-bottom: 1px solid var(--border-subtle);
    }
    
    /** Module label text (e.g. "TRANSPORT CORE") */
    .aus-module-title {
        font-family: 'Orbitron', sans-serif;
        font-size: 10px;
        font-weight: 700;
        letter-spacing: 1.5px;
        text-transform: uppercase;
        color: var(--text-muted);
    }
    
    /** Decorative icon on right of module header */
    .aus-module-icon {
        color: var(--brand-secondary);
        font-size: 14px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-H : BUTTON GRID INSIDE MODULE CARDS
   Used for Play/Reset and the three FX preset buttons.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-btn-grid
 * Default: 2-column even grid for module action buttons.
 */
    .aus-btn-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 8px;
    }
    
    /**
 * .aus-btn-grid--3col
 * 3-column override for the DSP Voice FX preset buttons.
 */
    .aus-btn-grid--3col {
        grid-template-columns: 1fr 1fr 1fr;
        margin-top: 10px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-I : SLIDER ROWS
   Label + range input layout used in every module card.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-slider-row
 * Horizontal row pairing a label and a range slider input.
 */
    .aus-slider-row {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 12px;
    }
    
    .aus-slider-row:last-of-type {
        margin-bottom: 0;
    }
    
    /** .mt-20 override for zoom slider spacing inside Transport module */
    .aus-slider-row.mt-20 {
        margin-top: 20px;
    }
    
    /**
 * .aus-slider-label
 * Fixed-width monospace label left of each range slider.
 */
    .aus-slider-label {
        font-family: 'Share Tech Mono', monospace;
        font-size: 11px;
        font-weight: 700;
        color: var(--text-muted);
        min-width: 46px;
        text-align: right;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        flex-shrink: 0;
    }
    
    /**
 * .aus-range-input
 * Styled range slider — custom track & thumb for a dark studio aesthetic.
 */
    .aus-range-input {
        -webkit-appearance: none;
        appearance: none;
        flex: 1;
        height: 4px;
        border-radius: 2px;
        background: var(--border-main);
        outline: none;
        cursor: pointer;
        transition: var(--transition-base);
        color-scheme: var(--input-scheme);
    }
    
    .aus-range-input::-webkit-slider-thumb {
        -webkit-appearance: none;
        appearance: none;
        width: 16px;
        height: 16px;
        border-radius: 50%;
        background: var(--brand-primary);
        cursor: pointer;
        border: 2px solid var(--bg-card);
        box-shadow: 0 2px 8px rgba(255, 0, 85, 0.5);
        transition: var(--transition-base);
    }
    
    .aus-range-input::-webkit-slider-thumb:hover {
        transform: scale(1.2);
    }
    
    .aus-range-input::-moz-range-thumb {
        width: 16px;
        height: 16px;
        border-radius: 50%;
        background: var(--brand-primary);
        cursor: pointer;
        border: 2px solid var(--bg-card);
        box-shadow: 0 2px 8px rgba(255, 0, 85, 0.5);
    }
    
    .aus-range-input:focus {
        background: var(--accent-cyan);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-J : TIME DISPLAY (TRANSPORT MODULE)
   Shows current playhead time and total duration in monospace.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-time-display
 * Centred time readout — "00:00 / 00:00" format.
 * Uses Share Tech Mono for a digital-clock aesthetic.
 */
    .aus-time-display {
        text-align: center;
        font-family: 'Share Tech Mono', monospace;
        font-size: 16px;
        font-weight: 700;
        color: var(--brand-primary);
        margin-top: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
    }
    
    /** Separator slash between current and total time */
    .aus-time-sep {
        color: var(--border-main);
        font-weight: 400;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-K : REVERSE MODE TOGGLE
   Custom checkbox + label row inside the DSP Voice FX module.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-reverse-toggle
 * Wrapper for the Reverse Mode checkbox and its label.
 * Pill-shaped dark container centred beneath the FX buttons.
 */
    .aus-reverse-toggle {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        background: var(--bg-input);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-sm);
        padding: 7px 12px;
        margin-top: 14px;
    }
    
    /**
 * .aus-reverse-check
 * The checkbox input inside Reverse Mode toggle.
 */
    .aus-reverse-check {
        width: auto !important;
        height: 14px;
        cursor: pointer;
        accent-color: var(--brand-primary);
        flex-shrink: 0;
    }
    
    /**
 * .aus-reverse-label
 * "REVERSE MODE" text label next to the checkbox.
 */
    .aus-reverse-label {
        font-size: 11px;
        font-family: 'Rajdhani', sans-serif;
        font-weight: 700;
        letter-spacing: 0.8px;
        color: var(--text-main);
        text-transform: uppercase;
        cursor: pointer;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-L : EXPORT / DOWNLOAD ZONE
   Format selector dropdown and the Render & Download CTA button.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-download-zone
 * Full-width export section at the bottom of the editor workspace.
 * Separates from the control deck with a subtle top border.
 */
    .aus-download-zone {
        border-top: 1px solid var(--border-subtle);
        padding-top: 24px;
        margin-top: 8px;
        text-align: center;
    }
    
    /**
 * .aus-format-select-wrap
 * Centres the format <select> dropdown with comfortable bottom spacing.
 */
    .aus-format-select-wrap {
        margin-bottom: 18px;
    }
    
    /**
 * .aus-format-select
 * Extends the global .input-control style for the format dropdown.
 * Adds a minimum width appropriate to the option text length.
 */
    .aus-format-select {
        min-width: 260px;
        max-width: 100%;
        text-align: center;
        font-family: 'Rajdhani', sans-serif;
        font-weight: 600;
        letter-spacing: 0.3px;
    }
    
    /**
 * .aus-render-btn
 * The main RENDER & DOWNLOAD call-to-action button.
 * Extends .btn.btn-primary with Orbitron font and extra visual weight.
 */
    .aus-render-btn {
        font-family: 'Orbitron', sans-serif;
        font-size: 13px;
        letter-spacing: 1.5px;
        padding: 14px 36px;
        box-shadow: 0 6px 24px rgba(255, 0, 85, 0.4);
    }
    
    .aus-render-btn:hover {
        box-shadow: 0 8px 30px rgba(255, 0, 85, 0.6);
        transform: translateY(-2px);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-M : SEO GUIDE LIST
   The numbered guide list inside the .info-card on the page.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .aus-guide-list
 * Styled list for the Mastering & FX Guide section.
 * Overrides default ul padding; each item has a subtle separator.
 */
    .aus-guide-list {
        list-style: none;
        padding-left: 0;
        margin: 0;
    }
    
    .aus-guide-list li {
        padding: 14px 0;
        border-bottom: 1px solid var(--border-subtle);
        line-height: 1.6;
        font-size: 14px;
        color: var(--text-main);
    }
    
    .aus-guide-list li:last-child {
        border-bottom: none;
        padding-bottom: 0;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-N : RESPONSIVE — TABLET  (max-width: 600px)
   Control deck collapses to single column; upload btn group stacks.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* Single-column control deck on tablet */
        .aus-control-deck {
            grid-template-columns: 1fr;
        }
        
        /* Tighter module card padding */
        .aus-module-card {
            padding: 16px 14px;
        }
        
        /* Stack upload action buttons vertically on small tablet */
        .aus-upload-btn-group {
            flex-direction: column;
            align-items: center;
        }
        
        .aus-upload-btn-group .aus-cyber-btn {
            width: 100%;
            max-width: 260px;
            justify-content: center;
        }
        
        /* Full-width format select on tablet */
        .aus-format-select {
            width: 100%;
            min-width: unset;
        }
        
        /* Shrink render button slightly */
        .aus-render-btn {
            padding: 12px 24px;
            font-size: 12px;
        }
        
        /* Loader card tighter */
        .aus-loader-card {
            padding: 28px 24px;
        }
        
        /* Smaller drop zone padding */
        .aus-drop-zone {
            padding: 36px 20px;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   45-O : RESPONSIVE — MOBILE  (max-width: 480px)
   Further simplification for small-phone screens.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Minimum drop zone padding on phone */
        .aus-drop-zone {
            padding: 28px 14px;
        }
        
        /* Smaller drop icon on phone */
        .aus-drop-icon {
            width: 56px;
            height: 56px;
            font-size: 22px;
        }
        
        /* Reduce drop zone title size */
        .aus-drop-title {
            font-size: 13px;
            letter-spacing: 1px;
        }
        
        /* Tighter module cards on phone */
        .aus-module-card {
            padding: 14px 12px;
        }
        
        /* Smaller module title label */
        .aus-module-title {
            font-size: 9px;
            letter-spacing: 1px;
        }
        
        /* Smaller cyber button text & padding */
        .aus-cyber-btn {
            font-size: 11px;
            padding: 9px 10px;
        }
        
        /* Stack the 3-col FX grid to 2 columns on phone */
        .aus-btn-grid--3col {
            grid-template-columns: 1fr 1fr;
        }
        
        /* Compact slider label */
        .aus-slider-label {
            font-size: 10px;
            min-width: 38px;
        }
        
        /* Slightly smaller time display */
        .aus-time-display {
            font-size: 14px;
        }
        
        /* Smaller render button */
        .aus-render-btn {
            padding: 11px 18px;
            font-size: 11px;
        }
        
        /* Compact visualiser height on phone */
        .aus-vis-wrapper {
            height: 56px;
        }
        
        /* Compact loader card on phone */
        .aus-loader-card {
            padding: 22px 18px;
            min-width: unset;
            width: calc(100vw - 40px);
        }
        
        /* Reduce loader title letter-spacing on phone */
        .aus-loader-title {
            font-size: 11px;
            letter-spacing: 1.2px;
        }
        
        /* Guide list slightly smaller on phone */
        .aus-guide-list li {
            font-size: 13px;
            padding: 10px 0;
        }
        
    }
    
}

/* end @media all */
/* #endregion */



















/* ════════════════════════════════════════════════════════════════════════════
   SECTION 46: SCREEN RECORDER ULTRA PRO — MINIMAL UNIQUE STYLES ONLY
   Prefix  : scr-
   Purpose : Styles every UI element that has no equivalent in Sections 1–45.
             Covers floating overlays (countdown, draw canvas, facecam,
             teleprompter, draw toolbar), the studio settings panel, audio
             visualiser, status bar, video preview wrapper, hero icon area,
             hotkey hint bar, info-article helpers, and FAQ blocks.
   Author  : MD KAWSAR
   Standard: CodeCanyon Premium — mobile-first, CSS-variable-driven
════════════════════════════════════════════════════════════════════════════ */

/* #region SECTION 46: SCREEN RECORDER ULTRA PRO */
@media all {
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-A : FULL-SCREEN COUNTDOWN OVERLAY
   Dark backdrop displayed for 3 s before recording begins.
   The countdown number is written by JS into innerText.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-countdown-overlay
 * Fixed-position full-screen overlay that shows a large centred countdown
 * digit (3 → 2 → 1). Hidden by default; JS sets display:flex to activate.
 */
    .scr-countdown-overlay {
        display: none;
        /* JS switches to flex when active          */
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.95);
        z-index: 10000;
        justify-content: center;
        align-items: center;
        font-size: 15vw;
        color: var(--accent-cyan);
        font-weight: 900;
        pointer-events: none;
        /* Does not block underlying clicks          */
        letter-spacing: -0.02em;
        text-shadow: 0 0 60px rgba(0, 229, 255, 0.8);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-B : FULL-SCREEN DRAWING CANVAS
   Transparent overlay that captures pointer events during draw mode.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-draw-canvas
 * Covers the entire viewport so annotations can be drawn over any content.
 * pointer-events toggled by JS (none when inactive, all when active).
 */
    .scr-draw-canvas {
        position: fixed;
        inset: 0;
        width: 100%;
        height: 100%;
        z-index: 9995;
        pointer-events: none;
        touch-action: none;
        display: none;
        /* JS sets display:block when draw mode on  */
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-C : FLOATING DRAWING TOOLBAR
   Compact pill-shaped toolbar housing pen, eraser, colour-picker, clear,
   and close buttons. Docked near the bottom-left of the screen.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-draw-toolbar
 * Floating horizontal bar rendered above the draw canvas (z-index: 9996).
 * Shown only when draw mode is active.
 */
    .scr-draw-toolbar {
        position: fixed;
        bottom: 80px;
        left: 50%;
        transform: translateX(-50%);
        display: none;
        /* JS sets display:flex when draw mode on   */
        align-items: center;
        gap: 8px;
        background: rgba(13, 17, 23, 0.92);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-pill);
        padding: 8px 16px;
        z-index: 9996;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
        backdrop-filter: blur(8px);
    }
    
    /**
 * .scr-draw-btn
 * Each icon button inside the drawing toolbar.
 * Active state highlighted with brand-primary colour + glow.
 */
    .scr-draw-btn {
        width: 36px;
        height: 36px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        background: transparent;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        color: var(--text-muted);
        font-size: 14px;
        cursor: pointer;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .scr-draw-btn:hover {
        background: var(--bg-input);
        color: var(--text-main);
        border-color: var(--accent-cyan);
    }
    
    .scr-draw-btn.active {
        background: var(--brand-primary);
        color: #fff;
        border-color: var(--brand-primary);
        box-shadow: 0 0 10px rgba(255, 0, 85, 0.5);
    }
    
    /**
 * .scr-color-picker
 * Native <input type="color"> styled as a round swatch inside the toolbar.
 */
    .scr-color-picker {
        width: 30px;
        height: 30px;
        border-radius: 50%;
        padding: 0;
        border: 2px solid #fff;
        cursor: pointer;
        background: none;
        flex-shrink: 0;
        outline: none;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-D : DRAGGABLE FACECAM OVERLAY
   Floating webcam preview box the user can drag anywhere on screen.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-facecam-box
 * Default circular webcam overlay positioned at bottom-right.
 * JS changes borderRadius / height for rectangle ↔ circle shape swap.
 */
    .scr-facecam-box {
        position: fixed;
        bottom: 20px;
        right: 20px;
        width: 160px;
        height: 160px;
        border-radius: 50%;
        aspect-ratio: 1 / 1;
        overflow: hidden;
        border: 3px solid var(--accent-cyan);
        box-shadow: 0 0 24px rgba(0, 229, 255, 0.35);
        z-index: 9990;
        cursor: move;
        display: none;
        /* JS shows when cam is toggled on          */
        background: #000;
    }
    
    /**
 * .scr-facecam-video
 * The actual <video> element inside the facecam box.
 * Mirrored horizontally so it feels natural (like a mirror).
 */
    .scr-facecam-video {
        width: 100%;
        height: 100%;
        object-fit: cover;
        transform: scaleX(-1);
    }
    
    /**
 * .scr-facecam-controls
 * Dark bar at the bottom of the facecam box with shape & filter icons.
 * Fades in on :hover via CSS transition.
 */
    .scr-facecam-controls {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        padding: 8px 0;
        background: rgba(0, 0, 0, 0.7);
        display: flex;
        justify-content: center;
        gap: 15px;
        opacity: 0;
        transition: opacity 0.3s ease;
    }
    
    .scr-facecam-box:hover .scr-facecam-controls {
        opacity: 1;
    }
    
    /**
 * .scr-facecam-icon
 * Individual clickable icons inside the facecam control bar.
 */
    .scr-facecam-icon {
        color: #fff;
        cursor: pointer;
        font-size: 14px;
        transition: var(--transition-base);
    }
    
    .scr-facecam-icon:hover {
        color: var(--accent-cyan);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-E : DRAGGABLE TELEPROMPTER
   Floating dark panel with a drag handle header and a resizable textarea.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-teleprompter-box
 * The draggable notes/script panel — positioned bottom-left by default.
 * Hidden by default; JS toggles display:block.
 */
    .scr-teleprompter-box {
        position: fixed;
        bottom: 20px;
        left: 20px;
        width: 300px;
        background: rgba(13, 17, 23, 0.92);
        border: 1px solid var(--accent-purple);
        border-radius: var(--radius-md);
        padding: 14px;
        z-index: 9988;
        display: none;
        /* JS shows when teleprompter is toggled    */
        backdrop-filter: blur(8px);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
    }
    
    /**
 * .scr-tele-header
 * Drag-handle area at the top of the teleprompter panel.
 * Houses the title label and the close (×) icon.
 */
    .scr-tele-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        color: var(--accent-purple);
        font-size: 13px;
        font-weight: 700;
        margin-bottom: 10px;
        cursor: move;
        user-select: none;
    }
    
    /**
 * .scr-tele-close
 * The × icon that dismisses the teleprompter panel.
 */
    .scr-tele-close {
        cursor: pointer;
        color: var(--text-main);
        transition: var(--transition-base);
    }
    
    .scr-tele-close:hover {
        color: var(--brand-primary);
    }
    
    /**
 * .scr-tele-content
 * The resizable textarea where the presenter pastes their script.
 */
    .scr-tele-content {
        width: 100%;
        height: 200px;
        background: transparent;
        border: none;
        color: #fff;
        resize: vertical;
        font-family: monospace;
        font-size: 14px;
        line-height: 1.6;
        outline: none;
        scrollbar-width: thin;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-F : HERO ICON AREA
   The app icon image with a "verified" green badge overlaid at bottom-right.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-icon-wrap
 * Relative-positioned square container holding the app icon + badge.
 * Centred inside the hero area.
 */
    .scr-icon-wrap {
        position: relative;
        width: 100px;
        height: 100px;
        margin: 0 auto 15px;
    }
    
    /**
 * .scr-app-icon
 * The main tool icon image. Circular crop, cyan glow border.
 */
    .scr-app-icon {
        width: 100%;
        height: 100%;
        object-fit: cover;
        border-radius: 50%;
        border: 3px solid var(--accent-cyan);
        box-shadow: 0 0 40px rgba(0, 229, 255, 0.4);
    }
    
    /**
 * .scr-verified-badge
 * Green circle overlaid at the bottom-right of the app icon.
 * Communicates "trusted / verified" status visually.
 */
    .scr-verified-badge {
        position: absolute;
        bottom: 5px;
        right: 5px;
        background: var(--status-success);
        color: #fff;
        width: 26px;
        height: 26px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        border: 3px solid var(--bg-container);
        z-index: 2;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-G : HOTKEY HINT BAR
   Small single-line bar below the subtitle showing keyboard shortcuts.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-hotkey-hint
 * Subtly styled hint strip. Uses monospace-like <kbd> elements inside.
 */
    .scr-hotkey-hint {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        background: var(--bg-input);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-pill);
        padding: 6px 16px;
        font-size: 12px;
        color: var(--text-muted);
        margin-bottom: 24px;
        flex-wrap: wrap;
        justify-content: center;
    }
    
    .scr-hotkey-hint kbd {
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: 4px;
        padding: 1px 5px;
        font-size: 11px;
        color: var(--accent-cyan);
        font-family: monospace;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-H : STUDIO SETTINGS PANEL
   Grid of setting items (audio, webcam, pro tools, quality) inside the tool.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-settings-panel
 * The containing card for all recording configuration controls.
 * Lays out children in a responsive auto-fit grid.
 */
    .scr-settings-panel {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 20px;
        margin-bottom: 24px;
        text-align: left;
        position: relative;
    }
    
    /**
 * .scr-section-badge
 * Small all-caps label in the top-left of the settings panel.
 * Positions absolutely so it sits on the border of the card.
 */
    .scr-section-badge {
        position: absolute;
        top: -13px;
        left: 20px;
        background: var(--brand-primary);
        color: #fff;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: 2px;
        padding: 3px 10px;
        border-radius: var(--radius-pill);
        text-transform: uppercase;
    }
    
    /**
 * .scr-setting-item
 * An individual setting block (label + controls) inside the settings panel.
 * Items flow in a two-column auto-fit grid inside the panel.
 */
    .scr-settings-panel {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 16px;
        align-items: start;
    }
    
    /* Override: badge sits outside the grid flow */
    .scr-section-badge {
        grid-column: 1 / -1;
        width: fit-content;
    }
    
    /**
 * .scr-setting-item
 * Vertical flex column for label + toggle(s) within each grid cell.
 */
    .scr-setting-item {
        display: flex;
        flex-direction: column;
        gap: 6px;
    }
    
    /**
 * .scr-setting-label
 * Small uppercase label above each setting group.
 */
    .scr-setting-label {
        font-size: 11px;
        font-weight: 700;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-bottom: 2px;
    }
    
    /**
 * .scr-toggle-btn
 * Pill-shaped toggle button for Mic, Cam, Script Reader, Screen Draw.
 * .active state changes background to brand-primary.
 */
    .scr-toggle-btn {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        padding: 10px 14px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        color: var(--text-main);
        font-size: 13px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
        width: 100%;
        text-align: left;
    }
    
    .scr-toggle-btn:hover {
        border-color: var(--accent-cyan);
        box-shadow: 0 0 8px rgba(0, 229, 255, 0.15);
    }
    
    .scr-toggle-btn.active {
        background: rgba(255, 0, 85, 0.1);
        border-color: var(--brand-primary);
        color: var(--brand-primary);
    }
    
    .scr-toggle-btn:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }
    
    /**
 * .scr-gain-row
 * Flex row containing the volume-low icon and the range slider.
 */
    .scr-gain-row {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-top: 6px;
    }
    
    /**
 * .scr-gain-icon
 * Small speaker icon to the left of the gain range slider.
 */
    .scr-gain-icon {
        font-size: 12px;
        color: var(--text-muted);
        flex-shrink: 0;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-I : AUDIO VISUALISER CONTAINER
   The wrapper holding the frequency-bar canvas drawn by the Web Audio API.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-visualizer-container
 * Hidden by default. JS sets display:block when the mic stream starts.
 * Clips the canvas to the container's rounded corners.
 */
    .scr-visualizer-container {
        display: none;
        width: 100%;
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-bottom: 16px;
        background: #000;
        border: 1px solid var(--border-subtle);
    }
    
    .scr-visualizer-container canvas {
        display: block;
        width: 100%;
        height: 60px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-J : RECORDING STATUS BAR
   Horizontal row containing the pulsing REC dot and the HH:MM:SS timer.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-status-bar
 * Centred flex row below the visualiser. Always present in the DOM.
 */
    .scr-status-bar {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 15px;
        margin-bottom: 20px;
    }
    
    /**
 * .scr-rec-dot
 * Pulsing red circle that indicates active recording.
 * JS sets display:block when recording starts.
 */
    .scr-rec-dot {
        width: 12px;
        height: 12px;
        background: var(--brand-primary);
        border-radius: 50%;
        display: none;
        /* JS shows when recording is active        */
        animation: pulse 1s infinite;
        flex-shrink: 0;
    }
    
    /**
 * .scr-timer
 * The HH:MM:SS elapsed-time display. Monospace, large, cyan-glowing.
 */
    .scr-timer {
        font-family: monospace;
        font-size: 24px;
        font-weight: 700;
        color: var(--accent-cyan);
        text-shadow: 0 0 10px rgba(0, 229, 255, 0.3);
        letter-spacing: 0.04em;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-K : VIDEO PREVIEW WRAPPER
   Contains the <video> element for both live preview and post-record review.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-video-wrapper
 * Centred wrapper. Hidden by default; JS sets display:block when
 * a screen stream or recorded blob is ready.
 */
    .scr-video-wrapper {
        display: none;
        /* JS controls visibility                   */
        width: 100%;
        margin-bottom: 20px;
        border-radius: var(--radius-md);
        overflow: hidden;
        border: 1px solid var(--border-main);
        background: #000;
    }
    
    /**
 * .scr-preview-video
 * The actual <video> element — fills full width of its wrapper.
 */
    .scr-preview-video {
        width: 100%;
        height: auto;
        display: block;
        max-height: 480px;
        object-fit: contain;
        background: #000;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-L : RECORDING CONTROL BUTTON MODIFIERS
   Thin utility modifier on top of the global .btn system.
   The snapshot button needs icon-only (square) sizing.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-ctrl-btn
 * Light modifier for all control buttons — adds a subtle shadow on hover
 * consistent with the "studio" visual language. Does NOT override layout.
 */
    .scr-ctrl-btn {
        transition: var(--transition-base), box-shadow 0.2s ease;
    }
    
    .scr-ctrl-btn:hover:not(:disabled) {
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
    }
    
    /**
 * .scr-snap-btn
 * Square icon-only button for the screenshot action.
 * Overrides padding so the button stays compact and circular.
 */
    .scr-snap-btn {
        padding: 12px 14px !important;
        min-width: 46px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-M : SEO ARTICLE HELPERS
   Styles for elements unique to the info-card article section of this tool.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-accent-border
 * Left-accent border variant for the first info-card (prominent highlight).
 */
    .scr-accent-border {
        border-left: 4px solid var(--accent-cyan) !important;
    }
    
    /**
 * .scr-privacy-card
 * Subtle green-tinted background for the "Your Data Stays Private" card.
 */
    .scr-privacy-card {
        background: rgba(35, 134, 54, 0.05) !important;
        border: 1px solid rgba(35, 134, 54, 0.2) !important;
    }
    
    /**
 * .scr-guide-img
 * The full-width how-to infographic image inside the step-by-step card.
 */
    .scr-guide-img {
        max-width: 100%;
        height: auto;
        border-radius: var(--radius-md);
        border: 1px solid var(--border-main);
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
    }
    
    /**
 * .scr-guide-ol
 * Styled ordered list for the "How to Record" step-by-step instructions.
 */
    .scr-guide-ol {
        margin-left: 20px;
        color: var(--text-main);
        font-size: 15px;
        line-height: 1.8;
        padding-left: 0;
    }
    
    .scr-guide-ol li {
        margin-bottom: 12px;
    }
    
    .scr-guide-ol li:last-child {
        margin-bottom: 0;
    }
    
    /**
 * .scr-tips-grid
 * Responsive three-column grid for the troubleshooting tip cards.
 */
    .scr-tips-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
        gap: 20px;
    }
    
    /**
 * .scr-tip-card
 * Individual troubleshooting tip card with dark background + left border.
 */
    .scr-tip-card {
        background: rgba(13, 17, 23, 0.5);
        padding: 15px;
        border-radius: var(--radius-md);
        border-left: 3px solid var(--border-main);
        display: flex;
        flex-direction: column;
        gap: 6px;
    }
    
    /* Accent-coloured left border variant (cyan) */
    .scr-tip-accent {
        border-left-color: var(--accent-cyan);
    }
    
    /* Brand-primary left border variant (red/pink) */
    .scr-tip-primary {
        border-left-color: var(--brand-primary);
    }
    
    /**
 * .scr-tip-title
 * Bold heading inside each tip card.
 */
    .scr-tip-title {
        display: block;
        margin-bottom: 4px;
        font-size: 14px;
        font-weight: 700;
    }
    
    /**
 * .scr-tip-text
 * Body text inside each tip card.
 */
    .scr-tip-text {
        font-size: 14px;
        color: var(--text-muted);
        line-height: 1.6;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-N : FAQ BLOCK
   Individual FAQ question + answer pairs inside the FAQ info-card.
──────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .scr-faq-item
 * Wraps a single Q&A pair. Bottom margin creates visual separation.
 */
    .scr-faq-item {
        margin-bottom: 20px;
        padding-bottom: 20px;
        border-bottom: 1px solid var(--border-subtle);
    }
    
    .scr-faq-item:last-child {
        margin-bottom: 0;
        padding-bottom: 0;
        border-bottom: none;
    }
    
    /**
 * .scr-faq-q
 * The FAQ question heading — slightly larger, light-coloured.
 */
    .scr-faq-q {
        font-size: 16px;
        color: var(--text-inverse);
        margin-bottom: 8px;
        font-weight: 600;
    }
    
    /**
 * .scr-faq-a
 * The FAQ answer body text — muted colour, comfortable line height.
 */
    .scr-faq-a {
        font-size: 14px;
        color: var(--text-muted);
        margin: 0;
        line-height: 1.7;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-O : RESPONSIVE — TABLET  (max-width: 600px)
   Settings grid collapses to single column; teleprompter & facecam scale.
──────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* Single-column settings grid on tablet */
        .scr-settings-panel {
            grid-template-columns: 1fr;
        }
        
        /* Tighter settings panel padding */
        .scr-settings-panel {
            padding: 16px 14px;
        }
        
        /* Narrower teleprompter on tablet */
        .scr-teleprompter-box {
            width: calc(100vw - 40px);
            left: 20px;
        }
        
        /* Slightly smaller facecam box */
        .scr-facecam-box {
            width: 130px;
            height: 130px;
        }
        
        /* Tips grid collapses to single column */
        .scr-tips-grid {
            grid-template-columns: 1fr;
        }
        
        /* Smaller timer on tablet */
        .scr-timer {
            font-size: 20px;
        }
        
        /* Compact draw toolbar spacing */
        .scr-draw-toolbar {
            gap: 6px;
            padding: 7px 12px;
        }
        
        /* Smaller draw buttons */
        .scr-draw-btn {
            width: 32px;
            height: 32px;
            font-size: 13px;
        }
        
        /* Smaller colour picker */
        .scr-color-picker {
            width: 26px;
            height: 26px;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────
   46-P : RESPONSIVE — MOBILE  (max-width: 480px)
   Further reductions for small-phone screens.
──────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Smaller countdown digit on phone */
        .scr-countdown-overlay {
            font-size: 25vw;
        }
        
        /* Compact hotkey hint on phone */
        .scr-hotkey-hint {
            font-size: 10px;
            padding: 5px 12px;
        }
        
        /* Smaller app icon on phone */
        .scr-icon-wrap {
            width: 80px;
            height: 80px;
        }
        
        /* Verified badge scales with icon */
        .scr-verified-badge {
            width: 20px;
            height: 20px;
            font-size: 10px;
        }
        
        /* Compact settings panel */
        .scr-settings-panel {
            padding: 14px 12px;
        }
        
        /* Slightly smaller toggle buttons on phone */
        .scr-toggle-btn {
            font-size: 12px;
            padding: 9px 12px;
        }
        
        /* Smaller section badge */
        .scr-section-badge {
            font-size: 9px;
            letter-spacing: 1.5px;
        }
        
        /* Compact timer on phone */
        .scr-timer {
            font-size: 18px;
        }
        
        /* Full-width preview video with max-height cap */
        .scr-preview-video {
            max-height: 260px;
        }
        
        /* Smaller draw toolbar on phone */
        .scr-draw-toolbar {
            bottom: 60px;
            padding: 6px 10px;
            gap: 5px;
        }
        
        /* Icon-only buttons more compact on phone */
        .scr-draw-btn {
            width: 28px;
            height: 28px;
            font-size: 12px;
        }
        
        /* Colour picker smaller on phone */
        .scr-color-picker {
            width: 24px;
            height: 24px;
        }
        
        /* Facecam scales to smaller size on phone */
        .scr-facecam-box {
            width: 100px;
            height: 100px;
        }
        
        /* Guide list items tighter on phone */
        .scr-guide-ol li {
            margin-bottom: 8px;
            font-size: 14px;
        }
        
        /* FAQ items tighter on phone */
        .scr-faq-q {
            font-size: 15px;
        }
        
        .scr-faq-a {
            font-size: 13px;
        }
        
        /* Snap (screenshot) button stays square on phone */
        .scr-snap-btn {
            padding: 11px 13px !important;
            min-width: 42px;
        }
        
    }
    
}

/* end @media all */
