/* #region SECTION 55: P2P SHARE VAULT ULTRA — MINIMAL UNIQUE STYLES ONLY */
@media all {
    
    /*
 * =============================================================================
 *  SECTION 55: P2P SHARE VAULT ULTRA — Tool-Specific Component Styles
 *  Prefix   : p2p-
 *  Tool     : sec-p2p-share (P2P File Transfer via WebRTC + AES-256)
 *  Author   : MD KAWSAR | Trusted Tools Web
 *  Scope    : All components in this tool that have NO equivalent in
 *             the existing tools-template.css sections 1–54.
 *             Every class here is prefixed with `p2p-` for clear
 *             namespacing and future reusability in similar real-time
 *             communication tools.
 *
 *  COMPONENTS COVERED:
 *  ─────────────────────────────────────────────────────────────────
 *  55-A  : App Icon
 *  55-B  : Connection Status Bar
 *  55-C  : Two-Column App Grid
 *  55-D  : Left/Right Panels
 *  55-E  : Panel Tab Navigation
 *  55-F  : Tab Content & Header
 *  55-G  : Form Group, Label & Hint
 *  55-H  : Input Row (input + icon buttons inline)
 *  55-I  : Button Row (primary + icon-only side by side)
 *  55-J  : SDP Textarea & Box
 *  55-K  : QR Code Container
 *  55-L  : Connection Overlay (Awaiting connection)
 *  55-M  : File Drop Zone
 *  55-N  : File Queue List
 *  55-O  : Live Transfer Dashboard
 *  55-P  : Circular SVG Progress
 *  55-Q  : Stats Cards Grid
 *  55-R  : Linear Progress Bar
 *  55-S  : Received Files Section
 *  55-T  : QR Scanner Overlay
 *  55-U  : Transfer Success Overlay
 *  55-V  : Comparison Table
 *  55-W  : Responsive — Tablet (max-width: 600px)
 *  55-X  : Responsive — Mobile (max-width: 480px)
 * =============================================================================
 */
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-A : APP ICON
   Centered decorative icon displayed below the hero subtitle.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-app-icon
 * Rounded, centered app icon image in the hero area.
 * Adds a subtle glow border using the brand primary color.
 */
    .p2p-app-icon {
        display: block;
        margin: 0 auto var(--space-md);
        width: 64px;
        height: 64px;
        border-radius: var(--radius-md);
        border: 2px solid rgba(255, 0, 85, 0.35);
        box-shadow: 0 4px 18px rgba(255, 0, 85, 0.25);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-B : CONNECTION STATUS BAR
   A full-width bar inside a .container that shows the live WebRTC
   connection state: dot color, label text, and descriptive meta info.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-status-bar
 * Outer row for the connection status strip.
 * Uses flexbox to align three zones: indicator | meta | actions.
 */
    .p2p-status-bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 12px 16px;
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        flex-wrap: wrap;
    }
    
    /**
 * .p2p-status-indicator
 * Left zone: pulsing dot + connection state label.
 */
    .p2p-status-indicator {
        display: flex;
        align-items: center;
        gap: 8px;
        flex-shrink: 0;
    }
    
    /**
 * .p2p-status-dot
 * The colored pulsing circle representing connection state.
 * JS adds modifier classes: .connected | .connecting | .disconnected | .error
 */
    .p2p-status-dot {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: var(--text-muted);
        display: inline-block;
        flex-shrink: 0;
        transition: background 0.4s ease;
    }
    
    /* Modifier states applied by setStatus() in JS */
    .p2p-status-dot.connected {
        background: var(--accent-green);
        box-shadow: 0 0 8px var(--accent-green);
        animation: p2p-pulse 2s ease infinite;
    }
    
    .p2p-status-dot.connecting {
        background: var(--accent-yellow);
        animation: p2p-pulse 1s ease infinite;
    }
    
    .p2p-status-dot.disconnected {
        background: var(--text-muted);
    }
    
    .p2p-status-dot.error {
        background: var(--accent-red);
        box-shadow: 0 0 8px var(--accent-red);
    }
    
    /**
 * .p2p-status-label
 * Bold status text label beside the dot. Color changes with state.
 */
    .p2p-status-label {
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 1px;
        color: var(--text-muted);
        text-transform: uppercase;
        transition: color 0.4s ease;
    }
    
    .p2p-status-label.connected {
        color: var(--accent-green);
    }
    
    .p2p-status-label.connecting {
        color: var(--accent-yellow);
    }
    
    .p2p-status-label.disconnected {
        color: var(--text-muted);
    }
    
    .p2p-status-label.error {
        color: var(--accent-red);
    }
    
    /**
 * .p2p-status-meta
 * Center zone: descriptive hint text (icon + span).
 */
    .p2p-status-meta {
        display: flex;
        align-items: center;
        gap: 6px;
        font-size: 12px;
        color: var(--text-muted);
        flex: 1;
        min-width: 0;
    }
    
    .p2p-status-meta span {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    /**
 * .p2p-status-actions
 * Right zone: reset button.
 */
    .p2p-status-actions {
        flex-shrink: 0;
    }
    
    /**
 * .p2p-reset-btn
 * Small circular reset icon button in the status bar.
 */
    .p2p-reset-btn {
        width: 34px;
        height: 34px;
        padding: 0;
        border-radius: 50%;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        font-size: 13px;
        transition: var(--transition-base);
    }
    
    .p2p-reset-btn:hover {
        background: rgba(255, 0, 85, 0.15);
        border-color: var(--brand-primary);
        color: var(--brand-primary);
    }
    
    @keyframes p2p-pulse {

        0%,
        100% {
            opacity: 1;
        }
        
        50% {
            opacity: 0.5;
        }
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-C : TWO-COLUMN APP GRID
   Splits the main app container into a left handshake panel
   and right file transfer panel side by side.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-app-grid
 * Two-column CSS Grid: left panel (connection setup) + right panel (transfer).
 * Columns are equal width on desktop; collapse to single column on mobile.
 */
    .p2p-app-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
        text-align: left;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-D : PANEL BASE STYLES
   Shared styles for both left and right panels.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-panel
 * Base panel container — dark card background with a border.
 */
    .p2p-panel {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 20px;
        display: flex;
        flex-direction: column;
        gap: 0;
        min-height: 480px;
        position: relative;
        overflow: hidden;
    }
    
    /**
 * .p2p-panel-left
 * Left panel — connection / handshake setup.
 * Top accent border uses brand primary color.
 */
    .p2p-panel-left {
        border-top: 3px solid var(--brand-primary);
    }
    
    /**
 * .p2p-panel-right
 * Right panel — file transfer and dashboard.
 * Top accent border uses accent cyan.
 */
    .p2p-panel-right {
        border-top: 3px solid var(--accent-cyan);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-E : PANEL TAB NAVIGATION
   Sender / Receiver tab buttons across the top of the left panel.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-panel-tabs
 * Horizontal tab bar at the top of the left panel.
 */
    .p2p-panel-tabs {
        display: flex;
        gap: 4px;
        margin-bottom: 18px;
        background: var(--bg-input);
        border-radius: var(--radius-md);
        padding: 4px;
    }
    
    /**
 * .p2p-panel-tab
 * Individual tab button — inactive state is muted.
 */
    .p2p-panel-tab {
        flex: 1;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 7px;
        padding: 9px 12px;
        border-radius: var(--radius-sm);
        border: none;
        background: transparent;
        color: var(--text-muted);
        font-size: 13px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
    }
    
    /**
 * .p2p-panel-tab.active
 * Active tab has a bright background and white text.
 */
    .p2p-panel-tab.active {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        color: #ffffff;
        box-shadow: 0 2px 12px rgba(255, 0, 85, 0.35);
    }
    
    .p2p-panel-tab:not(.active):hover {
        color: var(--text-main);
        background: var(--bg-container);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-F : TAB CONTENT & HEADER
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-tab-content
 * Individual tab panel — hidden by default; .active shown.
 */
    .p2p-tab-content {
        display: none;
    }
    
    .p2p-tab-content.active {
        display: block;
    }
    
    /**
 * .p2p-tab-header
 * Row with an icon badge and a title + description block.
 */
    .p2p-tab-header {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        margin-bottom: 18px;
        padding-bottom: 14px;
        border-bottom: 1px solid var(--border-subtle);
    }
    
    .p2p-tab-header h3 {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 2px;
    }
    
    /**
 * .p2p-tab-desc
 * Small muted description line below the tab header title.
 */
    .p2p-tab-desc {
        font-size: 12px;
        color: var(--text-muted);
        line-height: 1.5;
        margin: 0;
    }
    
    /**
 * .p2p-tab-icon
 * Circular icon badge in the tab header — primary gradient background.
 */
    .p2p-tab-icon {
        width: 38px;
        height: 38px;
        border-radius: 50%;
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        display: flex;
        align-items: center;
        justify-content: center;
        color: #ffffff;
        font-size: 15px;
        flex-shrink: 0;
    }
    
    /**
 * .p2p-tab-icon-green
 * Variant icon badge for the Receiver tab — uses green accent.
 */
    .p2p-tab-icon-green {
        background: linear-gradient(135deg, var(--accent-green), var(--brand-secondary));
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-G : FORM GROUPS, LABELS & HINTS
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-form-group
 * Stacked label + input section with bottom spacing.
 */
    .p2p-form-group {
        margin-bottom: 16px;
    }
    
    /**
 * .p2p-form-label
 * Field label row — flex to align icon + text + optional badge.
 */
    .p2p-form-label {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: 6px;
        font-size: 12px;
        font-weight: 700;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 0.5px;
        margin-bottom: 8px;
    }
    
    /**
 * .p2p-label-badge
 * Small inline badge on a form label (e.g. "Required").
 * Inherits .badge base from tools-template but overrides size.
 */
    .p2p-label-badge {
        font-size: 9px !important;
        padding: 2px 7px !important;
        letter-spacing: 0.3px;
    }
    
    /**
 * .p2p-form-hint
 * Muted italic hint text below an input.
 */
    .p2p-form-hint {
        display: flex;
        align-items: flex-start;
        gap: 6px;
        font-size: 11px;
        color: var(--accent-yellow);
        margin-top: 7px;
        line-height: 1.5;
    }
    
    /**
 * .p2p-hint-success
 * Green variant hint used below the Answer SDP box.
 */
    .p2p-hint-success {
        color: var(--accent-green);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-H : INPUT ROW
   An inline row that groups a text input with icon buttons on the right.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-input-row
 * Flex row: text input stretches; icon buttons are fixed width on the right.
 */
    .p2p-input-row {
        display: flex;
        align-items: center;
        gap: 6px;
    }
    
    .p2p-input-row .input-control {
        flex: 1;
        min-width: 0;
        margin-bottom: 0;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-I : BUTTON ROW & SIZE HELPERS
   Used for the primary action button + camera icon button side by side.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-btn-row
 * Small flex row for a full-width button + icon-only button pair.
 */
    .p2p-btn-row {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-top: 8px;
    }
    
    /**
 * .p2p-btn-full
 * Makes a button stretch to fill remaining row space.
 */
    .p2p-btn-full {
        flex: 1;
    }
    
    /**
 * .p2p-btn-icon-only
 * A square secondary button holding only an icon.
 * Used for the camera/QR scan button beside SDP inputs.
 */
    .p2p-btn-icon-only {
        width: 44px;
        height: 44px;
        padding: 0;
        flex-shrink: 0;
        border-radius: var(--radius-md);
        font-size: 15px;
    }
    
    /**
 * .p2p-btn-sm
 * A compact button for tight areas like the queue header.
 */
    .p2p-btn-sm {
        padding: 7px 14px;
        font-size: 12px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-J : SDP TEXTAREA & BOX
   The SDP (Session Description Protocol) text areas for copy/paste exchange.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-sdp-textarea
 * Monospace, dark-background textarea for raw SDP JSON text.
 */
    .p2p-sdp-textarea {
        width: 100%;
        min-height: 110px;
        padding: 10px 12px;
        background: var(--bg-body);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        color: var(--accent-cyan);
        font-family: 'JetBrains Mono', 'Courier New', monospace;
        font-size: 11px;
        line-height: 1.6;
        resize: vertical;
        outline: none;
        transition: border-color 0.3s ease;
        box-sizing: border-box;
        display: block;
    }
    
    .p2p-sdp-textarea:focus {
        border-color: var(--brand-primary);
        box-shadow: 0 0 0 2px rgba(255, 0, 85, 0.15);
    }
    
    /**
 * .p2p-sdp-box
 * Wrapper card for an SDP output (readonly textarea + header + actions).
 */
    .p2p-sdp-box {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-bottom: 14px;
    }
    
    /**
 * .p2p-sdp-box-header
 * Top header row of the SDP box: file icon + label on left, buttons on right.
 */
    .p2p-sdp-box-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 9px 12px;
        background: var(--bg-input);
        border-bottom: 1px solid var(--border-main);
        font-size: 12px;
        font-weight: 600;
        color: var(--text-muted);
        gap: 8px;
    }
    
    /**
 * .p2p-sdp-box-actions
 * Right side of the SDP box header — holds copy + QR icon buttons.
 */
    .p2p-sdp-box-actions {
        display: flex;
        gap: 6px;
    }
    
    /* Ensure the SDP textarea inside .p2p-sdp-box has no extra margins */
    .p2p-sdp-box .p2p-sdp-textarea {
        border: none;
        border-radius: 0;
        background: var(--bg-body);
    }
    
    .p2p-sdp-box .p2p-form-hint {
        padding: 0 12px 10px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-K : QR CODE CONTAINER
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-qr-container
 * Centered container for the QRCode.js generated QR code image.
 */
    .p2p-qr-container {
        text-align: center;
        padding: 16px 12px;
        background: #ffffff;
        border-top: 1px solid var(--border-main);
    }
    
    /**
 * .p2p-qr-label
 * Caption above the QR code image.
 */
    .p2p-qr-label {
        font-size: 11px;
        color: #555555;
        margin-bottom: 10px;
        font-weight: 600;
    }
    
    /* QR code image centering */
    .p2p-qr-container>div,
    .p2p-qr-container img,
    .p2p-qr-container canvas {
        display: block;
        margin: 0 auto;
        max-width: 100%;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-L : CONNECTION OVERLAY (Awaiting Connection)
   Shown in the right panel before WebRTC handshake is complete.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-overlay-required
 * Full-panel centered placeholder shown when not yet connected.
 */
    .p2p-overlay-required {
        position: absolute;
        inset: 0;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        text-align: center;
        padding: 30px 24px;
        gap: 10px;
        background: var(--bg-card);
        border-radius: var(--radius-lg);
        z-index: 2;
        overflow: hidden;
    }
    
    .p2p-overlay-required h3 {
        font-size: 16px;
        font-weight: 700;
        color: var(--text-main);
        margin: 0;
    }
    
    .p2p-overlay-required p {
        font-size: 13px;
        color: var(--text-muted);
        max-width: 280px;
        line-height: 1.6;
        margin: 0;
    }
    
    /**
 * .p2p-overlay-icon
 * Large glowing icon in the center of the overlay.
 */
    .p2p-overlay-icon {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        background: rgba(0, 229, 255, 0.08);
        border: 2px solid rgba(0, 229, 255, 0.25);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 26px;
        color: var(--accent-cyan);
        margin-bottom: 6px;
        animation: p2p-float 3s ease-in-out infinite;
    }
    
    /**
 * .p2p-orbit-ring
 * Decorative animated orbit ring behind the overlay icon.
 */
    .p2p-orbit-ring {
        position: absolute;
        width: 160px;
        height: 160px;
        border-radius: 50%;
        border: 1px dashed rgba(0, 229, 255, 0.15);
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        animation: p2p-orbit-spin 12s linear infinite;
        pointer-events: none;
    }
    
    @keyframes p2p-float {

        0%,
        100% {
            transform: translateY(0);
        }
        
        50% {
            transform: translateY(-8px);
        }
    }
    
    @keyframes p2p-orbit-spin {
        from {
            transform: translate(-50%, -50%) rotate(0deg);
        }
        
        to {
            transform: translate(-50%, -50%) rotate(360deg);
        }
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-M : FILE DROP ZONE
   The drag-and-drop target area for files and folders.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-drop-zone
 * Dashed bordered card — the drag-and-drop landing area.
 */
    .p2p-drop-zone {
        border: 2px dashed var(--border-main);
        border-radius: var(--radius-lg);
        padding: 32px 20px;
        text-align: center;
        cursor: pointer;
        transition: var(--transition-base);
        background: var(--bg-body);
        margin-bottom: 14px;
    }
    
    /**
 * .p2p-drop-zone.drag-over
 * Visual feedback when a file is dragged over the zone.
 * JS adds this class on dragenter / removes on dragleave.
 */
    .p2p-drop-zone.drag-over {
        border-color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.05);
        box-shadow: 0 0 20px rgba(0, 229, 255, 0.12);
    }
    
    /**
 * .p2p-drop-zone-icon
 * Upload cloud icon centered above the title.
 */
    .p2p-drop-zone-icon {
        font-size: 36px;
        color: var(--accent-cyan);
        margin-bottom: 12px;
        opacity: 0.75;
    }
    
    /**
 * .p2p-drop-zone-title
 * Main heading inside the drop zone.
 */
    .p2p-drop-zone-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 6px;
    }
    
    /**
 * .p2p-drop-zone-sub
 * Muted sub-description in the drop zone.
 */
    .p2p-drop-zone-sub {
        font-size: 12px;
        color: var(--text-muted);
        margin-bottom: 18px;
        line-height: 1.6;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-N : FILE QUEUE LIST
   Populated by renderQueueItem() in JS. Shows each file with icon,
   name, size, and a status badge.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-file-queue
 * Card container for the queued files list.
 */
    .p2p-file-queue {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-bottom: 14px;
    }
    
    /**
 * .p2p-queue-header
 * Top strip of the file queue: title + clear & send buttons.
 */
    .p2p-queue-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 10px 14px;
        background: var(--bg-input);
        border-bottom: 1px solid var(--border-main);
    }
    
    .p2p-queue-header h4 {
        font-size: 13px;
        font-weight: 700;
        color: var(--text-main);
        display: flex;
        align-items: center;
        gap: 6px;
        margin: 0;
    }
    
    /**
 * .p2p-queue-actions
 * Right side of the queue header: clear + send all buttons.
 */
    .p2p-queue-actions {
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    /**
 * .p2p-queue-list
 * Scrollable list of queue items (max height to prevent overflow).
 */
    .p2p-queue-list {
        max-height: 220px;
        overflow-y: auto;
        padding: 8px;
        display: flex;
        flex-direction: column;
        gap: 5px;
    }
    
    /* Custom scrollbar for queue list */
    .p2p-queue-list::-webkit-scrollbar {
        width: 4px;
    }
    
    .p2p-queue-list::-webkit-scrollbar-track {
        background: transparent;
    }
    
    .p2p-queue-list::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 4px;
    }
    
    /**
 * .queue-item
 * Individual file row in the queue.
 * JS generates this class name — must stay exactly as-is.
 */
    .queue-item {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 8px 10px;
        background: var(--bg-body);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-sm);
        transition: var(--transition-base);
    }
    
    /**
 * .queue-item-icon
 * File type icon circle.
 */
    .queue-item-icon {
        width: 30px;
        height: 30px;
        border-radius: var(--radius-sm);
        background: rgba(0, 229, 255, 0.1);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        color: var(--accent-cyan);
        flex-shrink: 0;
    }
    
    /**
 * .queue-item-info
 * File name and size text block.
 */
    .queue-item-info {
        flex: 1;
        min-width: 0;
    }
    
    /**
 * .queue-item-name
 * File name — truncated if too long.
 */
    .queue-item-name {
        font-size: 12px;
        font-weight: 600;
        color: var(--text-main);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    /**
 * .queue-item-size
 * Human-readable file size in muted text.
 */
    .queue-item-size {
        font-size: 11px;
        color: var(--text-muted);
    }
    
    /**
 * .queue-item-status
 * Status badge pill on each queue item.
 * JS applies modifier classes: .pending | .sending | .done | .error | .zipping
 */
    .queue-item-status {
        font-size: 9px;
        font-weight: 700;
        letter-spacing: 0.5px;
        padding: 3px 8px;
        border-radius: var(--radius-pill);
        text-transform: uppercase;
        flex-shrink: 0;
    }
    
    .queue-item-status.pending {
        background: rgba(139, 148, 158, 0.15);
        color: var(--text-muted);
    }
    
    .queue-item-status.sending {
        background: rgba(241, 196, 15, 0.15);
        color: var(--accent-yellow);
    }
    
    .queue-item-status.done {
        background: var(--status-success-bg);
        color: var(--status-text-success);
    }
    
    .queue-item-status.error {
        background: var(--status-error-bg);
        color: var(--accent-red);
    }
    
    .queue-item-status.zipping {
        background: rgba(0, 229, 255, 0.12);
        color: var(--accent-cyan);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-O : LIVE TRANSFER DASHBOARD
   Header bar + grid of circular progress + stat cards.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-transfer-ui
 * Flex column wrapper for the file transfer area on the right panel.
 */
    .p2p-transfer-ui {
        display: flex;
        flex-direction: column;
        gap: 0;
        width: 100%;
    }
    
    /**
 * .p2p-dashboard
 * The live metrics card shown during file transfer.
 */
    .p2p-dashboard {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-bottom: 14px;
    }
    
    /**
 * .p2p-dashboard-header
 * Title bar of the dashboard with a phase badge on the right.
 */
    .p2p-dashboard-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 10px 14px;
        background: var(--bg-input);
        border-bottom: 1px solid var(--border-main);
    }
    
    .p2p-dashboard-header h4 {
        font-size: 12px;
        font-weight: 700;
        color: var(--text-main);
        display: flex;
        align-items: center;
        gap: 6px;
        margin: 0;
    }
    
    /**
 * .p2p-dash-phase
 * Animated phase badge: ENCRYPTING / TRANSMITTING / COMPLETE / RECEIVING.
 */
    .p2p-dash-phase {
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 1px;
        padding: 4px 10px;
        border-radius: var(--radius-pill);
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        color: #ffffff;
        animation: p2p-pulse 2s ease infinite;
    }
    
    /**
 * .p2p-dashboard-grid
 * Inner grid of the dashboard: circular progress card + stats column.
 */
    .p2p-dashboard-grid {
        display: grid;
        grid-template-columns: 130px 1fr;
        gap: 14px;
        padding: 14px;
        align-items: center;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-P : CIRCULAR SVG PROGRESS INDICATOR
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-dash-card
 * Generic dashboard card.
 */
    .p2p-dash-card {
        background: var(--bg-body);
        border-radius: var(--radius-md);
        border: 1px solid var(--border-subtle);
        padding: 12px;
    }
    
    /**
 * .p2p-dash-progress-card
 * The card containing the circular SVG progress ring.
 */
    .p2p-dash-progress-card {
        display: flex;
        align-items: center;
        justify-content: center;
    }
    
    /**
 * .p2p-circular-progress-wrapper
 * Wrapper for the SVG circle — centers it.
 */
    .p2p-circular-progress-wrapper {
        position: relative;
        width: 110px;
        height: 110px;
    }
    
    /**
 * .p2p-circular-progress
 * The SVG element for the circular progress ring.
 * viewBox is 0 0 120 120; radius=52; circumference≈326.73
 */
    .p2p-circular-progress {
        width: 100%;
        height: 100%;
        transform: rotate(-90deg);
        overflow: visible;
    }
    
    /**
 * .p2p-cp-track
 * Background ring of the circular progress.
 */
    .p2p-cp-track {
        fill: none;
        stroke: var(--border-main);
        stroke-width: 8;
    }
    
    /**
 * .p2p-cp-fill
 * Animated foreground arc — strokeDashoffset is updated by JS.
 */
    .p2p-cp-fill {
        fill: none;
        stroke: url(#progressGradient);
        stroke-width: 8;
        stroke-linecap: round;
        stroke-dasharray: 326.73;
        stroke-dashoffset: 326.73;
        transition: stroke-dashoffset 0.4s ease;
    }
    
    /**
 * .p2p-cp-percent
 * Large percentage text inside the circular ring.
 * Note: SVG text is not rotated back because transform rotate(-90deg)
 * applies to the SVG element, not individual text elements.
 */
    .p2p-cp-percent {
        fill: var(--text-main);
        font-size: 18px;
        font-weight: 800;
        transform: rotate(90deg);
        transform-origin: 60px 60px;
    }
    
    /**
 * .p2p-cp-label
 * Small label text below the percentage in the ring.
 */
    .p2p-cp-label {
        fill: var(--text-muted);
        font-size: 7px;
        font-weight: 600;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        transform: rotate(90deg);
        transform-origin: 60px 60px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-Q : STATS CARDS GRID
   A 2×2 grid of small metric cards: speed, ETA, size, chunks.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-dash-stats
 * 2×2 grid holding the four stat cards.
 */
    .p2p-dash-stats {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 8px;
    }
    
    /**
 * .p2p-stat-card
 * Individual stat card with an icon, value, and label.
 */
    .p2p-stat-card {
        background: var(--bg-body);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-md);
        padding: 10px;
        display: flex;
        flex-direction: column;
        gap: 3px;
    }
    
    /**
 * .p2p-stat-icon
 * Small colored icon at the top of each stat card.
 */
    .p2p-stat-icon {
        font-size: 12px;
        color: var(--accent-cyan);
        margin-bottom: 2px;
    }
    
    /**
 * .p2p-stat-body
 * Row containing the numeric value and unit label.
 */
    .p2p-stat-body {
        display: flex;
        align-items: baseline;
        gap: 3px;
    }
    
    /**
 * .p2p-stat-value
 * Large numeric metric value.
 */
    .p2p-stat-value {
        font-size: 18px;
        font-weight: 800;
        color: var(--text-main);
        line-height: 1;
        font-variant-numeric: tabular-nums;
    }
    
    /**
 * .p2p-stat-unit
 * Small unit label beside the value (MB/s, KB, etc.).
 */
    .p2p-stat-unit {
        font-size: 10px;
        color: var(--text-muted);
        font-weight: 600;
    }
    
    /**
 * .p2p-stat-label
 * Label below the value row.
 */
    .p2p-stat-label {
        font-size: 10px;
        color: var(--text-muted);
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.3px;
    }
    
    /**
 * .p2p-speedometer-bar
 * Thin progress bar below the speed card value.
 */
    .p2p-speedometer-bar {
        height: 3px;
        background: var(--border-main);
        border-radius: 2px;
        overflow: hidden;
        margin-top: 4px;
    }
    
    /**
 * .p2p-speedometer-fill
 * The animated fill inside the speedometer bar.
 * Width is set by JS as a percentage of max speed (50 MB/s).
 */
    .p2p-speedometer-fill {
        height: 100%;
        width: 0%;
        background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
        border-radius: 2px;
        transition: width 0.5s ease;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-R : LINEAR PROGRESS BAR
   Thin track under the dashboard grid showing overall transfer progress.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-progress-track
 * The full-width gray background track for the linear progress bar.
 */
    .p2p-progress-track {
        position: relative;
        height: 8px;
        background: var(--bg-input);
        border-radius: var(--radius-pill);
        overflow: visible;
        margin: 0 14px 6px;
    }
    
    /**
 * .p2p-progress-fill
 * Gradient fill inside the progress track.
 * Width is animated by JS: style.width = `${pct}%`
 */
    .p2p-progress-fill {
        position: absolute;
        top: 0;
        left: 0;
        height: 100%;
        background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple), var(--accent-cyan));
        border-radius: var(--radius-pill);
        transition: width 0.3s ease;
    }
    
    /**
 * .p2p-progress-glow
 * A glowing dot that trails the leading edge of the fill bar.
 */
    .p2p-progress-glow {
        position: absolute;
        top: 50%;
        transform: translate(-50%, -50%);
        width: 14px;
        height: 14px;
        background: var(--accent-cyan);
        border-radius: 50%;
        box-shadow: 0 0 10px var(--accent-cyan);
        transition: left 0.3s ease;
        pointer-events: none;
    }
    
    /**
 * .p2p-progress-meta
 * Row below the progress bar: current file name | bytes text.
 */
    .p2p-progress-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 0 14px 14px;
        font-size: 11px;
        color: var(--text-muted);
        gap: 8px;
    }
    
    .p2p-progress-meta span {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-S : RECEIVED FILES SECTION
   Shown on the receiver side once files start arriving.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-received-section
 * Card container for the list of successfully received files.
 */
    .p2p-received-section {
        background: var(--bg-card);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-top: 14px;
    }
    
    /**
 * .p2p-received-header
 * Title bar of the received files section with count badge.
 */
    .p2p-received-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 10px 14px;
        background: var(--status-success-bg);
        border-bottom: 1px solid var(--status-success-border);
    }
    
    .p2p-received-header h4 {
        font-size: 13px;
        font-weight: 700;
        color: var(--status-text-success);
        display: flex;
        align-items: center;
        gap: 6px;
        margin: 0;
    }
    
    /**
 * .p2p-received-list
 * Scrollable list of received file items.
 */
    .p2p-received-list {
        padding: 8px;
        display: flex;
        flex-direction: column;
        gap: 6px;
        max-height: 240px;
        overflow-y: auto;
    }
    
    .p2p-received-list::-webkit-scrollbar {
        width: 4px;
    }
    
    .p2p-received-list::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 4px;
    }
    
    /**
 * .received-item
 * Individual row for a received file — JS generates this class name.
 * Must NOT be renamed.
 */
    .received-item {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 9px 10px;
        background: var(--bg-body);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-sm);
        animation: fadeInUp 0.3s ease both;
    }
    
    /**
 * .received-item-icon
 * File type icon circle for received items.
 */
    .received-item-icon {
        width: 30px;
        height: 30px;
        border-radius: var(--radius-sm);
        background: var(--status-success-bg);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        color: var(--status-text-success);
        flex-shrink: 0;
    }
    
    /**
 * .received-item-info
 * File name + timestamp meta block.
 */
    .received-item-info {
        flex: 1;
        min-width: 0;
    }
    
    /**
 * .received-item-name
 * File name — truncated with ellipsis if too long.
 */
    .received-item-name {
        font-size: 12px;
        font-weight: 600;
        color: var(--text-main);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    /**
 * .received-item-meta
 * Size and time metadata below the file name.
 */
    .received-item-meta {
        font-size: 11px;
        color: var(--text-muted);
    }
    
    /**
 * .btn-download
 * Re-download button on each received item row.
 * JS generates this class name — must NOT be renamed.
 */
    .btn-download {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        padding: 6px 12px;
        border-radius: var(--radius-pill);
        border: 1px solid var(--status-success-border);
        background: var(--status-success-bg);
        color: var(--status-text-success);
        font-size: 11px;
        font-weight: 700;
        cursor: pointer;
        flex-shrink: 0;
        transition: var(--transition-base);
    }
    
    .btn-download:hover {
        background: var(--accent-green);
        color: #ffffff;
        border-color: var(--accent-green);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-T : QR SCANNER OVERLAY
   Full-screen dark overlay with camera viewfinder and corner markers.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-scanner-overlay
 * Fixed full-screen dark backdrop for the QR camera scanner.
 */
    .p2p-scanner-overlay {
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.96);
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 20px;
        z-index: 9999;
        padding: 20px;
    }
    
    /**
 * .p2p-hidden
 * Utility class to hide scanner and success overlay.
 * Applied by JS on initialization and toggle.
 */
    .p2p-hidden {
        display: none !important;
    }
    
    /**
 * .p2p-scanner-close
 * Top close button wrapper for the scanner overlay.
 */
    .p2p-scanner-close {
        position: absolute;
        top: 20px;
        right: 20px;
    }
    
    /**
 * .p2p-scanner-frame
 * White-bordered frame indicating the scan area.
 */
    .p2p-scanner-frame {
        position: relative;
        width: 300px;
        height: 300px;
        border: 2px solid rgba(255, 255, 255, 0.2);
        border-radius: var(--radius-lg);
        overflow: hidden;
    }
    
    /* Html5Qrcode mounts its video inside #reader — ensure it fills the frame */
    .p2p-scanner-frame #reader {
        width: 100% !important;
        height: 100% !important;
    }
    
    /**
 * .p2p-scanner-corners
 * Container for the four L-shaped corner markers.
 */
    .p2p-scanner-corners {
        position: absolute;
        inset: 0;
        pointer-events: none;
        z-index: 2;
    }
    
    /**
 * .p2p-corner
 * Base style for a corner L-shape marker.
 */
    .p2p-corner {
        position: absolute;
        width: 28px;
        height: 28px;
        border-color: var(--accent-cyan);
        border-style: solid;
    }
    
    .p2p-corner-tl {
        top: 0;
        left: 0;
        border-width: 3px 0 0 3px;
        border-top-left-radius: 4px;
    }
    
    .p2p-corner-tr {
        top: 0;
        right: 0;
        border-width: 3px 3px 0 0;
        border-top-right-radius: 4px;
    }
    
    .p2p-corner-bl {
        bottom: 0;
        left: 0;
        border-width: 0 0 3px 3px;
        border-bottom-left-radius: 4px;
    }
    
    .p2p-corner-br {
        bottom: 0;
        right: 0;
        border-width: 0 3px 3px 0;
        border-bottom-right-radius: 4px;
    }
    
    /**
 * .p2p-scanner-hint
 * Instructional text below the scanner viewfinder.
 */
    .p2p-scanner-hint {
        color: var(--text-muted);
        font-size: 13px;
        font-weight: 600;
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-U : TRANSFER SUCCESS OVERLAY
   A full-screen overlay with an animated SVG checkmark and a message.
   Shown after all files have been sent or a file has been received.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-success-overlay
 * Fixed full-screen dark backdrop for the success animation.
 */
    .p2p-success-overlay {
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.88);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 9998;
        padding: 20px;
    }
    
    /**
 * .p2p-success-card
 * Centered white/dark card with the success icon, title, and close button.
 */
    .p2p-success-card {
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 40px 36px;
        text-align: center;
        max-width: 380px;
        width: 100%;
        animation: fadeInUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
    }
    
    .p2p-success-card h2 {
        font-size: 22px;
        font-weight: 800;
        color: var(--text-main);
        margin: 14px 0 8px;
    }
    
    .p2p-success-card p {
        font-size: 14px;
        color: var(--text-muted);
        margin-bottom: 24px;
        line-height: 1.6;
    }
    
    /**
 * .p2p-success-icon
 * Wrapper for the SVG ring animation.
 */
    .p2p-success-icon {
        width: 90px;
        height: 90px;
        margin: 0 auto 8px;
    }
    
    /**
 * .p2p-success-ring
 * The outer SVG element for the animated checkmark ring.
 */
    .p2p-success-ring {
        width: 100%;
        height: 100%;
    }
    
    /**
 * .p2p-success-circle-track
 * Background circle of the success ring.
 */
    .p2p-success-circle-track {
        fill: none;
        stroke: var(--border-main);
        stroke-width: 4;
    }
    
    /**
 * .p2p-success-circle-fill
 * Animated foreground arc of the success ring (green).
 */
    .p2p-success-circle-fill {
        fill: none;
        stroke: var(--accent-green);
        stroke-width: 4;
        stroke-dasharray: 283;
        stroke-dashoffset: 283;
        stroke-linecap: round;
        transform: rotate(-90deg);
        transform-origin: 50px 50px;
        animation: p2p-ring-draw 0.7s ease 0.2s forwards;
    }
    
    /**
 * .p2p-success-check
 * Animated checkmark polyline inside the ring.
 */
    .p2p-success-check {
        fill: none;
        stroke: var(--accent-green);
        stroke-width: 5;
        stroke-linecap: round;
        stroke-linejoin: round;
        stroke-dasharray: 60;
        stroke-dashoffset: 60;
        animation: p2p-check-draw 0.4s ease 0.8s forwards;
    }
    
    @keyframes p2p-ring-draw {
        to {
            stroke-dashoffset: 0;
        }
    }
    
    @keyframes p2p-check-draw {
        to {
            stroke-dashoffset: 0;
        }
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-V : COMPARISON TABLE
   Feature comparison table in the SEO info section.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .p2p-comparison-table
 * Full-width styled table for comparing this tool vs cloud services.
 */
    .p2p-comparison-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 13px;
        color: var(--text-main);
    }
    
    .p2p-comparison-table th {
        background: var(--bg-input);
        color: var(--text-muted);
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        padding: 10px 14px;
        border-bottom: 2px solid var(--border-main);
        text-align: left;
    }
    
    .p2p-comparison-table th:first-child {
        border-radius: var(--radius-sm) 0 0 0;
    }
    
    .p2p-comparison-table th:last-child {
        border-radius: 0 var(--radius-sm) 0 0;
    }
    
    .p2p-comparison-table td {
        padding: 10px 14px;
        border-bottom: 1px solid var(--border-subtle);
        vertical-align: middle;
    }
    
    .p2p-comparison-table tbody tr:hover td {
        background: var(--bg-input);
    }
    
    /**
 * .p2p-cmp-good — Green "check" cells (this tool wins)
 * .p2p-cmp-bad  — Red "X" cells (competitor loses)
 * .p2p-cmp-warn — Yellow "minus" cells (partial support)
 */
    .p2p-cmp-good {
        color: var(--accent-green);
        font-weight: 600;
    }
    
    .p2p-cmp-bad {
        color: var(--accent-red);
    }
    
    .p2p-cmp-warn {
        color: var(--accent-yellow);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-W : RESPONSIVE — TABLET (max-width: 600px)
   Two-column grid collapses; panels stack vertically.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* App grid: single column on tablet — panels stack vertically */
        .p2p-app-grid {
            grid-template-columns: 1fr;
        }
        
        /* Dashboard grid: stack circular progress above stats */
        .p2p-dashboard-grid {
            grid-template-columns: 1fr;
            justify-items: center;
        }
        
        /* Stats grid: 2 columns on tablet */
        .p2p-dash-stats {
            grid-template-columns: 1fr 1fr;
            width: 100%;
        }
        
        /* Circular progress wrapper sizing for single-column layout */
        .p2p-circular-progress-wrapper {
            width: 120px;
            height: 120px;
        }
        
        /* Panel tabs: font reduction */
        .p2p-panel-tab {
            font-size: 12px;
            padding: 8px 8px;
        }
        
        /* Status bar wraps to two lines */
        .p2p-status-bar {
            flex-direction: column;
            align-items: flex-start;
            gap: 8px;
        }
        
        .p2p-status-meta {
            width: 100%;
        }
        
        /* SDP textarea height reduction */
        .p2p-sdp-textarea {
            min-height: 90px;
        }
        
        /* Success card: reduce padding */
        .p2p-success-card {
            padding: 28px 20px;
        }
        
        /* Overlay required: min-height removed on tablet */
        .p2p-panel {
            min-height: auto;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   55-X : RESPONSIVE — MOBILE (max-width: 480px)
   Further refinements for small phone screens.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Dashboard stats: single column on very small phones */
        .p2p-dash-stats {
            grid-template-columns: 1fr 1fr;
        }
        
        /* Stat value size: reduce for 2-column fit */
        .p2p-stat-value {
            font-size: 15px;
        }
        
        /* Panel tabs: icon only or very compact */
        .p2p-panel-tab {
            font-size: 11px;
            padding: 8px 6px;
            gap: 4px;
        }
        
        /* SDP textarea: tighter on phones */
        .p2p-sdp-textarea {
            font-size: 10px;
            min-height: 80px;
        }
        
        /* Tab header icon smaller */
        .p2p-tab-icon {
            width: 32px;
            height: 32px;
            font-size: 13px;
        }
        
        /* Drop zone: reduce padding on phone */
        .p2p-drop-zone {
            padding: 20px 14px;
        }
        
        .p2p-drop-zone-icon {
            font-size: 28px;
        }
        
        .p2p-drop-zone-title {
            font-size: 14px;
        }
        
        /* Queue header wraps on phone */
        .p2p-queue-header {
            flex-direction: column;
            align-items: flex-start;
            gap: 8px;
        }
        
        /* Progress meta wraps on phone */
        .p2p-progress-meta {
            flex-direction: column;
            align-items: flex-start;
            gap: 2px;
            font-size: 10px;
        }
        
        /* Scanner frame: full-width on phone */
        .p2p-scanner-frame {
            width: 100%;
            max-width: 300px;
            height: 280px;
        }
        
        /* Comparison table: allow horizontal scroll (already wrapped in overflow-x:auto) */
        .p2p-comparison-table td,
        .p2p-comparison-table th {
            padding: 8px 10px;
            font-size: 12px;
        }
        
        /* Success card: compact on phones */
        .p2p-success-card {
            padding: 24px 16px;
        }
        
        .p2p-success-card h2 {
            font-size: 18px;
        }
        
        /* Btn-row icon-only button: reduce size on phone */
        .p2p-btn-icon-only {
            width: 40px;
            height: 40px;
            font-size: 14px;
        }
        
        /* Status label text: smaller on phone */
        .p2p-status-label {
            font-size: 10px;
        }
        
        /* Input row: ensure icon buttons don't shrink too much */
        .p2p-input-row .btn-icon {
            width: 36px;
            height: 36px;
            flex-shrink: 0;
        }
        
    }
    
}

/* end @media all */
/* #endregion */



















/* ============================================================================================
   SECTION 56: PASSWORD GENERATOR — UNIQUE TOOL STYLES (pwd- prefix)
   Tool        : Ultra Strong Password Generator (Enterprise Edition v2.5)
   Author      : MD KAWSAR
   Description : Styles for the password output display box, action icons, strength meter,
                 range slider header, custom checkbox grid, and password history panel.
                 All colours reference CSS variables defined in Section 1 for full
                 dark/light-mode compatibility. Each class is prefixed with "pwd-" for
                 safe global reuse across future security-related tools.
   ============================================================================================
*/

/* #region SECTION 56: PASSWORD GENERATOR */
@media all {
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-A : PASSWORD OUTPUT DISPLAY BOX
   The main result container that holds the readonly password input and
   the action icon buttons (copy / regenerate).
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-display-box
 * Outer wrapper for the generated password result.
 * Uses a subtle gradient border to give a "secure vault" visual cue.
 * The JS attaches `.error-state` and `.shake` classes here on validation failure.
 */
    .pwd-display-box {
        display: flex;
        align-items: center;
        gap: 12px;
        background: var(--bg-input);
        border: 2px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 14px 18px;
        margin-bottom: 20px;
        transition: var(--transition-base);
        position: relative;
        overflow: hidden;
    }
    
    /**
 * .pwd-display-box — hover highlight
 * Subtle cyan glow on hover to indicate interactability.
 */
    .pwd-display-box:hover {
        border-color: var(--accent-cyan);
        box-shadow: 0 0 18px rgba(0, 229, 255, 0.12);
    }
    
    /**
 * .pwd-display-box.error-state
 * Red border + glow applied by JS when no character set is selected.
 */
    .pwd-display-box.error-state {
        border-color: var(--accent-red);
        box-shadow: 0 0 18px rgba(255, 71, 87, 0.25);
    }
    
    /**
 * .pwd-display-box.shake
 * Quick horizontal shake keyframe applied by JS on validation error.
 */
    .pwd-display-box.shake {
        animation: pwd-shake 0.5s ease;
    }
    
    @keyframes pwd-shake {

        0%,
        100% {
            transform: translateX(0);
        }
        
        20% {
            transform: translateX(-8px);
        }
        
        40% {
            transform: translateX(8px);
        }
        
        60% {
            transform: translateX(-5px);
        }
        
        80% {
            transform: translateX(5px);
        }
    }
    
    /**
 * .pwd-output-input
 * The readonly <input> that renders the generated password.
 * Uses JetBrains Mono for clear, monospace readability of complex strings.
 */
    .pwd-output-input {
        flex: 1;
        background: transparent !important;
        border: none !important;
        outline: none !important;
        color: var(--text-inverse) !important;
        font-family: 'JetBrains Mono', 'Courier New', monospace !important;
        font-size: 18px !important;
        font-weight: 700;
        letter-spacing: 1.5px;
        padding: 0 !important;
        min-width: 0;
        box-shadow: none !important;
    }
    
    /**
 * .pulse-animation
 * Applied by JS after each new generation to confirm visual update.
 * A brief opacity pulse to draw the user's eye to the new value.
 */
    .pulse-animation {
        animation: pwd-pulse 0.4s ease;
    }
    
    @keyframes pwd-pulse {
        0% {
            opacity: 0.4;
        }
        
        100% {
            opacity: 1;
        }
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-B : ACTION ICON BUTTONS (Copy / Regenerate)
   Small circular icon buttons displayed inside the password output box.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-action-icons
 * Flex row holding the copy and regen icon buttons inside .pwd-display-box.
 */
    .pwd-action-icons {
        display: flex;
        align-items: center;
        gap: 8px;
        flex-shrink: 0;
    }
    
    /**
 * .pwd-icon-btn
 * Individual circular icon button. Inherits its visual role from .btn-icon
 * but is intentionally kept as a separate component because it lives
 * inside the display box (not in a .btn-area group), and requires
 * a slightly different size for proportional balance with the password text.
 */
    .pwd-icon-btn {
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 16px;
        border: 1px solid var(--border-main);
        background: var(--bg-card);
        color: var(--text-muted);
        cursor: pointer;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .pwd-icon-btn:hover {
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.08);
        transform: scale(1.1);
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-C : STRENGTH METER
   Visual entropy bar + label displayed below the password output box.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-strength-section
 * Container for the strength header row and the four bar segments.
 */
    .pwd-strength-section {
        margin-bottom: 24px;
    }
    
    /**
 * .pwd-strength-header
 * Row that shows "Security Strength (Entropy)" label and the text value
 * ("WEAK" / "MEDIUM" / "STRONG" / "MILITARY") side by side.
 */
    .pwd-strength-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 10px;
    }
    
    /**
 * .pwd-strength-val
 * The dynamic strength label (#strengthText) — updated via JS.
 * Bold monospace for a technical readout feel.
 */
    .pwd-strength-val {
        font-family: 'JetBrains Mono', monospace;
        font-size: 13px;
        font-weight: 800;
        letter-spacing: 1px;
        color: var(--accent-red);
        /* default: WEAK */
        transition: color 0.3s ease;
    }
    
    /**
 * .pwd-meter-bars
 * Flex row of four strength bar segments.
 */
    .pwd-meter-bars {
        display: flex;
        gap: 6px;
    }
    
    /**
 * .pwd-bar
 * Individual bar segment. Background and box-shadow are set by JS
 * based on the calculated entropy level. Default = muted border color.
 */
    .pwd-bar {
        flex: 1;
        height: 6px;
        border-radius: var(--radius-pill);
        background: var(--border-main);
        transition: background 0.4s ease, box-shadow 0.4s ease;
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-D : GENERATOR CONTROLS GRID
   Layout wrapper for the length slider and checkbox group.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-controls-grid
 * Two-section stacked layout for the range-wrapper and checkbox-grid.
 * Uses a subtle card background to visually group the settings.
 */
    .pwd-controls-grid {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 22px 24px;
        margin-bottom: 24px;
        text-align: left;
        display: flex;
        flex-direction: column;
        gap: 22px;
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-E : RANGE SLIDER WRAPPER
   Custom-styled range slider for password length (8–64 chars).
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-range-wrapper
 * Container for the label row, range input, and min/max hint labels.
 */
    .pwd-range-wrapper {
        width: 100%;
    }
    
    /**
 * .pwd-range-header
 * Flex row: label on the left, live length value on the right.
 */
    .pwd-range-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 10px;
    }
    
    /**
 * .pwd-length-val
 * The live character-count number (#lengthVal) shown to the right of the label.
 * Branded primary color + monospace for clear readout.
 */
    .pwd-length-val {
        color: var(--brand-primary);
        font-weight: 800;
        font-family: 'JetBrains Mono', monospace;
        font-size: 18px;
        min-width: 32px;
        text-align: right;
    }
    
    /**
 * .pwd-range-slider
 * Full custom-styled range input.
 * Overrides browser defaults for thumb and track to match the tool's design.
 */
    .pwd-range-slider {
        width: 100%;
        -webkit-appearance: none;
        appearance: none;
        height: 6px;
        background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
        border-radius: var(--radius-pill);
        outline: none;
        cursor: pointer;
        border: none !important;
        padding: 0 !important;
        margin: 0;
        display: block;
        box-shadow: none !important;
    }
    
    /* Webkit (Chrome, Safari, Edge) thumb */
    .pwd-range-slider::-webkit-slider-thumb {
        -webkit-appearance: none;
        width: 20px;
        height: 20px;
        border-radius: 50%;
        background: #ffffff;
        border: 3px solid var(--brand-primary);
        cursor: pointer;
        box-shadow: 0 0 8px rgba(255, 0, 85, 0.5);
        transition: transform 0.2s ease;
    }
    
    .pwd-range-slider::-webkit-slider-thumb:hover {
        transform: scale(1.2);
    }
    
    /* Firefox thumb */
    .pwd-range-slider::-moz-range-thumb {
        width: 20px;
        height: 20px;
        border-radius: 50%;
        background: #ffffff;
        border: 3px solid var(--brand-primary);
        cursor: pointer;
        box-shadow: 0 0 8px rgba(255, 0, 85, 0.5);
    }
    
    /**
 * .pwd-range-labels
 * Small "8" / "64" hint text below the slider track.
 */
    .pwd-range-labels {
        display: flex;
        justify-content: space-between;
        margin-top: 5px;
        font-size: 11px;
        color: var(--text-muted);
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-F : CUSTOM CHECKBOX GRID
   2×2 grid of styled checkboxes for selecting character sets.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-checkbox-grid
 * Responsive 2×2 grid of custom checkbox labels.
 */
    .pwd-checkbox-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px;
    }
    
    /**
 * .pwd-custom-check
 * The full clickable label area for one checkbox option.
 * Contains a hidden native checkbox, a visual box, and a text label.
 */
    .pwd-custom-check {
        display: flex;
        align-items: center;
        gap: 10px;
        cursor: pointer;
        padding: 10px 14px;
        border-radius: var(--radius-sm);
        border: 1px solid var(--border-main);
        background: var(--bg-card);
        transition: var(--transition-base);
        user-select: none;
    }
    
    .pwd-custom-check:hover {
        border-color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.05);
    }
    
    /* Hide the native browser checkbox — replaced by .pwd-check-visual */
    .pwd-custom-check input[type="checkbox"] {
        position: absolute;
        opacity: 0;
        width: 0;
        height: 0;
        pointer-events: none;
    }
    
    /**
 * .pwd-check-visual
 * The stylised square checkbox replacement. Displays a checkmark icon
 * only when the real checkbox is :checked.
 */
    .pwd-check-visual {
        width: 20px;
        height: 20px;
        border-radius: var(--radius-sm);
        border: 2px solid var(--border-main);
        background: var(--bg-input);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 11px;
        color: transparent;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    /* When checked: fill the box with primary gradient, show the tick */
    .pwd-custom-check input[type="checkbox"]:checked~.pwd-check-visual {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        border-color: var(--brand-primary);
        color: #ffffff;
        box-shadow: 0 0 10px rgba(255, 0, 85, 0.4);
    }
    
    /* Override block label margin-bottom for tight checkbox layout */
    .pwd-custom-check label,
    .pwd-custom-check .text-small-label {
        margin-bottom: 0;
        cursor: pointer;
    }
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-G : PASSWORD HISTORY PANEL
   Shows the last N generated passwords with per-row copy buttons.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .pwd-history-section
 * Card-style container wrapping the history header and list.
 */
    .pwd-history-section {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 18px 20px;
        margin-top: 24px;
        text-align: left;
    }
    
    /**
 * .pwd-history-header
 * Flex row: "Recent History" label on the left, "Clear All" button on the right.
 */
    .pwd-history-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 14px;
        flex-wrap: wrap;
        gap: 8px;
    }
    
    /**
 * .pwd-clear-btn
 * The "Clear All" danger button. Sized small to fit beside the header label.
 * Uses .btn.btn-danger as its base — this rule only overrides the padding/font-size.
 */
    .pwd-clear-btn {
        padding: 5px 12px !important;
        font-size: 12px !important;
        border-radius: var(--radius-sm) !important;
    }
    
    /**
 * .pwd-history-list
 * The <ul> element that JS populates with .pwd-history-item rows.
 */
    .pwd-history-list {
        list-style: none;
        padding: 0;
        margin: 0;
        display: flex;
        flex-direction: column;
        gap: 7px;
        max-height: 280px;
        overflow-y: auto;
    }
    
    /* Thin custom scrollbar for the history list */
    .pwd-history-list::-webkit-scrollbar {
        width: 4px;
    }
    
    .pwd-history-list::-webkit-scrollbar-track {
        background: transparent;
    }
    
    .pwd-history-list::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 4px;
    }
    
    /**
 * .history-item
 * A single row in the history list, containing a truncated password text
 * and a small icon-copy button.
 * NOTE: This class is assigned in script.js (li.className = 'history-item'),
 * so the name MUST remain exactly "history-item".
 */
    .history-item {
        display: flex;
        align-items: center;
        justify-content: space-between;
        background: var(--bg-card);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-sm);
        padding: 8px 12px;
        animation: pwd-item-in 0.3s ease both;
        transition: border-color 0.2s ease;
    }
    
    .history-item:hover {
        border-color: var(--border-main);
    }
    
    @keyframes pwd-item-in {
        from {
            opacity: 0;
            transform: translateY(6px);
        }
        
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
    
    /**
 * .history-pwd-text
 * The truncated password string inside each history row.
 * NOTE: This class is assigned in script.js (textSpan.className = 'history-pwd-text'),
 * so the name MUST remain exactly "history-pwd-text".
 */
    .history-pwd-text {
        font-family: 'JetBrains Mono', monospace;
        font-size: 13px;
        color: var(--text-main);
        letter-spacing: 0.5px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        max-width: calc(100% - 50px);
    }
    
    /**
 * .icon-btn (history row copy button)
 * NOTE: The history copy button in script.js uses className = 'icon-btn'
 * which is already defined in Section 5 of tools-template.css.
 * The JS also applies inline width/height overrides (30px × 30px) — we do
 * NOT override those here, as script.js controls the sizing.
 */
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-H : RESPONSIVE — TABLET (max-width: 600px)
   Tighten spacing and adjust checkbox grid for medium-width screens.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* Reduce output font size for medium screens */
        .pwd-output-input {
            font-size: 15px !important;
            letter-spacing: 0.8px;
        }
        
        /* Tighten controls padding */
        .pwd-controls-grid {
            padding: 16px 16px;
            gap: 18px;
        }
        
        /* Checkbox grid stays 2-column on tablet */
        .pwd-checkbox-grid {
            grid-template-columns: 1fr 1fr;
        }
        
        /* History panel padding reduction */
        .pwd-history-section {
            padding: 14px 16px;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   56-I : RESPONSIVE — MOBILE (max-width: 480px)
   Full single-column layout and font adjustments for small phones.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Password output: compact font for small screens */
        .pwd-output-input {
            font-size: 13px !important;
            letter-spacing: 0.5px;
        }
        
        /* Reduce icon button size on phones */
        .pwd-icon-btn {
            width: 34px;
            height: 34px;
            font-size: 14px;
        }
        
        /* Single-column checkbox grid on phones */
        .pwd-checkbox-grid {
            grid-template-columns: 1fr;
        }
        
        /* Tighten checkbox label padding */
        .pwd-custom-check {
            padding: 9px 12px;
        }
        
        /* Reduce controls container padding */
        .pwd-controls-grid {
            padding: 14px 14px;
            gap: 16px;
        }
        
        /* Strength value: slightly smaller on phone */
        .pwd-strength-val {
            font-size: 12px;
        }
        
        /* Length value: match smaller layout */
        .pwd-length-val {
            font-size: 16px;
        }
        
        /* History section: compact on phones */
        .pwd-history-section {
            padding: 12px 14px;
        }
        
        /* History text: tighter on phones */
        .history-pwd-text {
            font-size: 11px;
        }
        
    }
    
}

/* end @media all */
/* #endregion */



















/*
 * =============================================================================
 *  TOOLS-TEMPLATE.CSS — APPEND-ONLY ADDITION
 *  Section 57: Stegano Vault ULTRA MAX — Unique UI Component Styles
 *
 *  Author  : MD KAWSAR
 *  Prefix  : stv-   (Stegano Vault)
 *  Scope   : Styles for sec-steganography tool ONLY — all reusable patterns
 *            (cards, tabs, buttons, inputs) use existing template classes.
 *
 *  WHAT IS NEW HERE (and why it cannot use existing classes):
 *    stv-hero / stv-badge  — Custom animated "GOD MODE" hero banner with
 *                            live badge dot not present in any other tool.
 *    stv-pills             — Horizontal scrollable feature pill row unique
 *                            to this tool's hero section.
 *    stv-tab-switcher      — Extended tab bar with <small> sub-labels inside
 *                            each tab button — not supported by base .tab-nav.
 *    stv-panel-grid        — 2-column responsive layout for encode/decode panels.
 *    stv-drop-zone         — Rich drag-and-drop zone with icon, titles, and
 *                            "drag-over" visual feedback state.
 *    stv-preview-wrap      — Canvas image preview container with meta line.
 *    stv-cap-*             — Capacity Analyzer bar, stats, and over-capacity
 *                            alert — entirely unique to this tool.
 *    stv-field-*           — Labelled field groups and textarea wrappers.
 *    stv-password-wrap     — Side-by-side input + eye-toggle button layout.
 *    stv-strength-*        — Password strength bar and label.
 *    stv-algo-badge        — "AES-256-CBC" info badge block.
 *    stv-download-area     — Post-encode success banner + download button area.
 *    stv-decoded-*         — Decoded message <pre> output and action row.
 *    stv-tool-error        — Red error panel shown on encode/decode failures.
 *    stv-steps-grid        — 5-column usage guide step cards.
 *    stv-step-card         — Individual numbered step card.
 *    stv-feature-grid      — 2-column security knowledge base grid.
 *    stv-section-header    — Section title row (icon + h2).
 *    stv-faq-*             — FAQ accordion (details/summary), orb, chevron.
 * =============================================================================
 */


/* #region SECTION 57: STEGANO VAULT ULTRA MAX */
@media all {
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-A : HERO SECTION
   The full-width banner above the tool interface.
   Contains the animated badge, H1, subtitle, and feature pills row.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-hero
 * Outer wrapper for the hero band. Adds a dark translucent gradient overlay
 * and subtle radial glow to give the tool a premium "vault" aesthetic.
 */
    .stv-hero {
        width: 100%;
        padding: 10px 0 0;
        text-align: center;
    }
    
    /**
 * .stv-badge
 * Animated "GOD MODE TOOL | CATEGORY: SECURITY" pill displayed above the H1.
 * Inline-flex with a pulsing green dot on the left.
 */
    .stv-badge {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        background: linear-gradient(135deg, rgba(0, 229, 255, 0.08), rgba(209, 36, 255, 0.08));
        border: 1px solid rgba(0, 229, 255, 0.25);
        color: var(--accent-cyan);
        padding: 6px 16px;
        border-radius: var(--radius-pill);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 1px;
        text-transform: uppercase;
        margin-bottom: 14px;
    }
    
    /**
 * .stv-badge-dot
 * Pulsing live-status dot inside the badge.
 * Animates with stv-pulse keyframe to indicate the tool is active.
 */
    .stv-badge-dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: var(--accent-green);
        box-shadow: 0 0 8px var(--accent-green);
        animation: stv-pulse 1.8s infinite;
        flex-shrink: 0;
    }
    
    @keyframes stv-pulse {

        0%,
        100% {
            opacity: 1;
            transform: scale(1);
        }
        
        50% {
            opacity: 0.5;
            transform: scale(1.3);
        }
    }
    
    /**
 * .stv-badge-sep
 * Vertical separator character between badge segments.
 */
    .stv-badge-sep {
        color: var(--border-main);
        font-weight: 400;
    }
    
    /**
 * .stv-pills
 * Horizontal flex row of feature pill chips below the subtitle.
 * Wraps gracefully on smaller viewports.
 */
    .stv-pills {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: 8px;
        margin-top: 18px;
    }
    
    /**
 * .stv-pill
 * Individual feature pill chip. Subtle border + semi-transparent background.
 * Icon + text displayed inline.
 */
    .stv-pill {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        padding: 5px 13px;
        border-radius: var(--radius-pill);
        font-size: 12px;
        font-weight: 600;
        transition: var(--transition-base);
    }
    
    .stv-pill:hover {
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.06);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-B : TOOL INTERFACE SECTION WRAPPER
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-interface-section
 * Full-width wrapper for the main tool area.
 */
    .stv-interface-section {
        width: 100%;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-C : TAB SWITCHER (EXTENDED — with <small> sub-labels)
   The base .tab-nav / .tab-btn classes handle the active state. These rules
   extend them with the 3-line layout: icon / label / small sub-label.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-tab-switcher
 * Extends .tab-nav with a consistent 2-column grid for Encode / Decode tabs.
 */
    .stv-tab-switcher {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0;
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-bottom: 24px;
    }
    
    /**
 * .stv-tab-btn
 * Extends .tab-btn with flex-column layout to stack icon / label / sub-label.
 */
    .stv-tab-btn {
        flex-direction: column;
        gap: 3px;
        padding: 18px 20px;
        border-radius: 0;
        font-size: 14px;
        font-weight: 700;
        color: var(--text-muted);
        background: transparent;
        border: none;
        cursor: pointer;
        transition: var(--transition-base);
    }
    
    .stv-tab-btn small {
        font-size: 11px;
        font-weight: 400;
        opacity: 0.6;
    }
    
    .stv-tab-btn.active {
        background: linear-gradient(135deg, rgba(255, 0, 85, 0.12), rgba(209, 36, 255, 0.12));
        color: var(--text-inverse);
        border-bottom: 2px solid var(--brand-primary);
    }
    
    .stv-tab-btn:hover:not(.active) {
        background: rgba(255, 255, 255, 0.04);
        color: var(--text-main);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-D : PANEL GRID (2-COLUMN LAYOUT FOR ENCODE / DECODE)
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-panel
 * Tab panel content area. Uses padding-top for visual breathing room.
 */
    .stv-panel {
        padding-top: 8px;
    }
    
    /**
 * .stv-panel-grid
 * Side-by-side 2-column grid for left (image) and right (form) columns.
 * Each column stacks its cards vertically.
 */
    .stv-panel-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
        align-items: start;
    }
    
    /**
 * .stv-panel-col
 * A single column inside the panel grid. Stacks child cards vertically.
 */
    .stv-panel-col {
        display: flex;
        flex-direction: column;
        gap: 16px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-E : CARD ENHANCEMENTS
   The base .card and .card-header classes from Section 8 are reused.
   These rules only add the Stegano-specific body padding and badge style.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-card
 * Extends .card with a slightly more pronounced border and box shadow to
 * differentiate encode/decode cards from each other visually.
 */
    .stv-card {
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        background: var(--bg-card);
        overflow: hidden;
    }
    
    /**
 * .stv-card-body
 * Content area inside each card. Consistent internal padding.
 */
    .stv-card-body {
        padding: 20px;
        display: flex;
        flex-direction: column;
        gap: 16px;
    }
    
    /**
 * .stv-card-badge
 * Small badge pill displayed in the card header (Step 1, Step 2, etc.).
 * Extends the global .badge classes with tighter padding.
 */
    .stv-card-badge {
        margin-left: auto;
        font-size: 11px;
        padding: 3px 9px;
        flex-shrink: 0;
    }
    
    /**
 * .stv-action-card
 * The "Encode & Export" card — slightly highlighted to draw the user's eye
 * to the primary action.
 */
    .stv-action-card {
        border-color: rgba(255, 0, 85, 0.25);
        box-shadow: 0 0 20px rgba(255, 0, 85, 0.05);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-F : DRAG-AND-DROP UPLOAD ZONE
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-drop-zone
 * The full-width clickable/droppable upload area.
 * position: relative needed to contain the hidden file input.
 */
    .stv-drop-zone {
        border: 2px dashed var(--border-main);
        border-radius: var(--radius-md);
        padding: 32px 20px;
        text-align: center;
        cursor: pointer;
        transition: var(--transition-base);
        position: relative;
        background: var(--bg-input);
    }
    
    .stv-drop-zone:hover,
    .stv-drop-zone:focus-visible {
        border-color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.04);
        outline: none;
    }
    
    /**
 * .stv-drop-zone.drag-over
 * Applied by JS during an active drag-over event.
 */
    .stv-drop-zone.drag-over {
        border-color: var(--brand-primary);
        background: rgba(255, 0, 85, 0.05);
        transform: scale(1.01);
    }
    
    /**
 * .stv-drop-inner
 * Centers the icon + text content within the drop zone.
 */
    .stv-drop-inner {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 6px;
        pointer-events: none;
    }
    
    /**
 * .stv-drop-icon
 * Large upload / magnify icon displayed in the center of the drop zone.
 */
    .stv-drop-icon {
        font-size: 36px;
        color: var(--accent-cyan);
        margin-bottom: 8px;
        opacity: 0.75;
        transition: var(--transition-base);
    }
    
    .stv-drop-zone:hover .stv-drop-icon,
    .stv-drop-zone.drag-over .stv-drop-icon {
        opacity: 1;
        transform: scale(1.1);
    }
    
    /** .stv-drop-title — Primary instruction text in the drop zone */
    .stv-drop-title {
        font-weight: 700;
        font-size: 15px;
        color: var(--text-main);
    }
    
    /** .stv-drop-sub — Secondary instruction text ("or click to browse") */
    .stv-drop-sub {
        font-size: 13px;
        color: var(--text-muted);
    }
    
    /** .stv-drop-types — Accepted file types label */
    .stv-drop-types {
        font-size: 11px;
        color: var(--text-muted);
        opacity: 0.7;
        letter-spacing: 0.5px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-G : IMAGE PREVIEW WRAP
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-preview-wrap
 * Container revealed after image upload. Centers the canvas and metadata.
 */
    .stv-preview-wrap {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 10px;
        padding: 12px 0 0;
    }
    
    /**
 * Canvas inside the preview wrap.
 * Scaled to fit the container width while preserving aspect ratio.
 */
    .stv-preview-wrap canvas {
        width: 100%;
        height: auto;
        max-height: 280px;
        object-fit: contain;
        border-radius: var(--radius-sm);
        border: 1px solid var(--border-main);
        display: block;
    }
    
    /**
 * .stv-image-meta
 * One-line text displaying image dimensions, file size, and format.
 */
    .stv-image-meta {
        font-size: 12px;
        color: var(--text-muted);
        text-align: center;
    }
    
    /**
 * .stv-clear-btn
 * The "Remove" button shown in the image preview. Extends .btn.btn-danger
 * with compact sizing appropriate for this context.
 */
    .stv-clear-btn {
        padding: 6px 14px !important;
        font-size: 12px !important;
        border-radius: var(--radius-sm) !important;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-H : CAPACITY ANALYZER
   Real-time progress bar + stats for the encode panel.
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-cap-bar-wrap
 * Outer wrapper for the progress bar + char count text.
 */
    .stv-cap-bar-wrap {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }
    
    /**
 * .stv-cap-track
 * The progress bar background track.
 */
    .stv-cap-track {
        height: 10px;
        background: var(--bg-input);
        border-radius: var(--radius-pill);
        border: 1px solid var(--border-main);
        overflow: hidden;
    }
    
    /**
 * .stv-cap-fill
 * The animated fill bar inside the track.
 * Width is set inline by CapacityAnalyzer.update() in script.js.
 * Transitions smoothly on change.
 */
    .stv-cap-fill {
        height: 100%;
        border-radius: var(--radius-pill);
        background: linear-gradient(90deg, var(--accent-cyan), var(--accent-green));
        transition: width 0.4s ease, background 0.3s ease;
    }
    
    /**
 * .stv-cap-fill.over-capacity
 * Applied by JS when message length exceeds image capacity.
 * Shifts the gradient to danger red.
 */
    .stv-cap-fill.over-capacity {
        background: linear-gradient(90deg, var(--accent-red), var(--brand-primary));
    }
    
    /**
 * .stv-cap-stats
 * Character usage counter text (e.g., "423 chars used / 72000 chars max").
 */
    .stv-cap-stats {
        font-size: 13px;
        color: var(--text-muted);
        text-align: right;
    }
    
    /**
 * .stv-cap-details
 * List of three detail rows below the progress bar.
 */
    .stv-cap-details {
        display: flex;
        flex-direction: column;
        gap: 8px;
        border-top: 1px solid var(--border-subtle);
        padding-top: 12px;
    }
    
    /**
 * .stv-cap-stat
 * A single detail row: icon + text side by side.
 */
    .stv-cap-stat {
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 12px;
        color: var(--text-muted);
    }
    
    .stv-cap-stat i {
        color: var(--accent-cyan);
        font-size: 13px;
        flex-shrink: 0;
        width: 16px;
        text-align: center;
    }
    
    /**
 * .stv-cap-alert
 * Warning box shown when the message is too large for the loaded image.
 * Uses danger colors for immediate visual attention.
 */
    .stv-cap-alert {
        display: flex;
        align-items: flex-start;
        gap: 10px;
        background: var(--status-error-bg);
        border: 1px solid rgba(218, 54, 51, 0.35);
        border-radius: var(--radius-sm);
        padding: 10px 14px;
        font-size: 13px;
        color: var(--accent-red);
        animation: fadeInUp 0.3s ease both;
    }
    
    .stv-cap-alert i {
        flex-shrink: 0;
        margin-top: 2px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-I : FORM FIELDS (LABEL + INPUT / TEXTAREA)
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-field-group
 * Wrapper for a label + input pair. Stacks them vertically with a gap.
 */
    .stv-field-group {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }
    
    /**
 * .stv-field-label
 * Styled label text with icon. Small, uppercase, muted color.
 */
    .stv-field-label {
        font-size: 13px;
        font-weight: 600;
        color: var(--text-muted);
        display: flex;
        align-items: center;
        gap: 6px;
    }
    
    .stv-field-label i {
        color: var(--accent-cyan);
    }
    
    /**
 * .stv-textarea-wrap
 * Wraps the textarea and the character count footer below it.
 * Uses border + radius to group them visually.
 */
    .stv-textarea-wrap {
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        background: var(--bg-input);
        transition: border-color 0.2s ease;
    }
    
    .stv-textarea-wrap:focus-within {
        border-color: var(--accent-cyan);
    }
    
    /**
 * .stv-textarea
 * The secret message textarea. Extends .input-control with no border
 * (border is on the parent wrap) and monospace font.
 */
    .stv-textarea {
        border: none !important;
        border-radius: 0 !important;
        resize: vertical;
        min-height: 160px;
        font-family: 'JetBrains Mono', 'Courier New', monospace;
        font-size: 13px;
        line-height: 1.6;
        background: transparent !important;
        width: 100%;
        padding: 14px;
        color: var(--text-main);
        outline: none;
    }
    
    /**
 * .stv-textarea-footer
 * The character count bar below the textarea.
 */
    .stv-textarea-footer {
        padding: 7px 14px;
        border-top: 1px solid var(--border-subtle);
        font-size: 12px;
        color: var(--text-muted);
        display: flex;
        align-items: center;
        gap: 5px;
        background: var(--bg-input);
    }
    
    /**
 * .stv-field-input
 * Extends .input-control for single-line inputs inside the password wrap.
 * Removes the default border radius on the right side so it flows into
 * the adjacent toggle button seamlessly.
 */
    .stv-field-input {
        flex: 1;
        border-right: none !important;
        border-radius: var(--radius-md) 0 0 var(--radius-md) !important;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-J : PASSWORD FIELD WITH SHOW/HIDE TOGGLE
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-password-wrap
 * Flex row combining the password input and the eye-toggle button into
 * a single visually unified control.
 */
    .stv-password-wrap {
        display: flex;
        align-items: stretch;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        transition: border-color 0.2s ease;
    }
    
    .stv-password-wrap:focus-within {
        border-color: var(--accent-cyan);
    }
    
    /* The input inside the password wrap inherits the wrap's border */
    .stv-password-wrap .stv-field-input {
        border: none !important;
        border-radius: 0 !important;
        background: var(--bg-input);
        flex: 1;
        padding: 12px 14px;
        color: var(--text-main);
        outline: none;
        font-size: 14px;
    }
    
    /**
 * .stv-toggle-password
 * The eye icon button on the right of the password field.
 * Toggles input type between "password" and "text".
 */
    .stv-toggle-password {
        background: var(--bg-input);
        border: none;
        border-left: 1px solid var(--border-main);
        padding: 0 14px;
        color: var(--text-muted);
        cursor: pointer;
        transition: var(--transition-base);
        font-size: 14px;
        flex-shrink: 0;
    }
    
    .stv-toggle-password:hover {
        color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.05);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-K : PASSWORD STRENGTH METER & MATCH STATUS
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-strength-wrap
 * Container for the strength bar and label, displayed below the password input.
 */
    .stv-strength-wrap {
        display: flex;
        flex-direction: column;
        gap: 5px;
    }
    
    /**
 * .stv-strength-track
 * Background track for the strength progress bar.
 */
    .stv-strength-track {
        height: 5px;
        background: var(--bg-input);
        border-radius: var(--radius-pill);
        border: 1px solid var(--border-subtle);
        overflow: hidden;
    }
    
    /**
 * .stv-strength-fill
 * Animated fill bar. Width (0–100%) and background color are set inline
 * by PasswordHelper.updateStrength() in script.js.
 */
    .stv-strength-fill {
        height: 100%;
        border-radius: var(--radius-pill);
        transition: width 0.4s ease, background 0.3s ease;
        width: 0%;
    }
    
    /**
 * .stv-strength-label
 * Text label showing the current strength assessment (e.g., "Strong").
 * Text color set inline by JS to match the fill bar color.
 */
    .stv-strength-label {
        font-size: 12px;
        color: var(--text-muted);
        font-weight: 600;
    }
    
    /**
 * .stv-match-status
 * Displayed below the confirm password field.
 * JS applies .match-ok (green) or .match-fail (red) modifier class.
 */
    .stv-match-status {
        font-size: 12px;
        font-weight: 600;
    }
    
    /* These modifier classes are toggled by PasswordHelper.updateMatch() in JS.
   The class names "match-ok" and "match-fail" MUST remain unchanged. */
    .match-status.match-ok {
        color: var(--accent-green);
    }
    
    .match-status.match-fail {
        color: var(--accent-red);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-L : AES ALGORITHM BADGE
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-algo-badge
 * Informational badge showing the encryption algorithm in use.
 * Renders as a compact flex row with a shield icon.
 */
    .stv-algo-badge {
        display: flex;
        align-items: center;
        gap: 12px;
        background: var(--status-success-bg);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-md);
        padding: 12px 16px;
        font-size: 13px;
        color: var(--status-text-success);
    }
    
    .stv-algo-badge>i {
        font-size: 20px;
        flex-shrink: 0;
    }
    
    .stv-algo-badge strong {
        display: block;
        font-size: 14px;
        font-weight: 700;
    }
    
    .stv-algo-badge small {
        display: block;
        font-size: 11px;
        opacity: 0.75;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-M : ACTION BUTTON (FULL-WIDTH ENCODE / DECODE)
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-action-btn
 * Full-width extend for the primary Encode / Decode buttons.
 * Sits inside .btn-area which handles centering.
 */
    .stv-action-btn {
        width: 100%;
        max-width: 100%;
        padding: 16px 28px;
        font-size: 16px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-N : DOWNLOAD AREA (POST-ENCODE SUCCESS)
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-download-area
 * Container revealed after a successful encode operation.
 * Contains success banner, download link button, and output preview.
 */
    .stv-download-area {
        display: flex;
        flex-direction: column;
        gap: 14px;
        animation: fadeInUp 0.4s ease both;
    }
    
    /**
 * .stv-download-success
 * Green success banner: checkmark icon + success message text.
 */
    .stv-download-success {
        display: flex;
        align-items: center;
        gap: 12px;
        background: var(--status-success-bg);
        border: 1px solid var(--status-success-border);
        border-radius: var(--radius-md);
        padding: 12px 16px;
        color: var(--status-text-success);
    }
    
    .stv-download-success>i {
        font-size: 22px;
        flex-shrink: 0;
    }
    
    .stv-download-success strong {
        display: block;
        font-size: 14px;
    }
    
    .stv-download-success small {
        font-size: 12px;
        opacity: 0.8;
    }
    
    /**
 * .stv-download-btn
 * The "Download Stegano PNG" anchor styled as a button.
 * Extends .btn.btn-success with full width.
 */
    .stv-download-btn {
        width: 100%;
        justify-content: center;
        padding: 14px 20px;
        font-size: 15px;
        border-radius: var(--radius-pill);
        display: flex;
        align-items: center;
        gap: 8px;
        font-weight: 700;
        text-decoration: none;
    }
    
    /**
 * .stv-output-preview-wrap
 * Container for the thumbnail preview of the encoded output PNG.
 */
    .stv-output-preview-wrap {
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        background: var(--bg-input);
    }
    
    .stv-output-preview-wrap img {
        width: 100%;
        height: auto;
        max-height: 200px;
        object-fit: contain;
        display: block;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-O : DECODED MESSAGE OUTPUT
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-decoded-wrap
 * Container for the <pre> decoded message output.
 */
    .stv-decoded-wrap {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 16px;
        max-height: 320px;
        overflow-y: auto;
    }
    
    /* Custom scrollbar for decoded output */
    .stv-decoded-wrap::-webkit-scrollbar {
        width: 4px;
    }
    
    .stv-decoded-wrap::-webkit-scrollbar-track {
        background: transparent;
    }
    
    .stv-decoded-wrap::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 4px;
    }
    
    /**
 * .stv-decoded-output
 * The <pre> element where the decrypted message is displayed.
 * Uses monospace font and wraps long lines cleanly.
 */
    .stv-decoded-output {
        font-family: 'JetBrains Mono', 'Courier New', monospace;
        font-size: 13px;
        color: var(--text-main);
        line-height: 1.7;
        white-space: pre-wrap;
        word-break: break-word;
        margin: 0;
    }
    
    /**
 * .stv-decode-actions
 * Button group row below the decoded output.
 * Extends .btn-area with a slightly tighter top margin.
 */
    .stv-decode-actions {
        margin-top: 4px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-P : INLINE ERROR DISPLAY
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-tool-error
 * Red inline error block shown when encode/decode fails.
 * Content (icon + message) is injected by UIController.showError() in JS.
 */
    .stv-tool-error {
        display: flex;
        align-items: flex-start;
        gap: 10px;
        background: var(--status-error-bg);
        border: 1px solid rgba(218, 54, 51, 0.35);
        border-radius: var(--radius-md);
        padding: 12px 16px;
        font-size: 13px;
        color: var(--accent-red);
        animation: fadeInUp 0.3s ease both;
        margin-top: 4px;
    }
    
    .stv-tool-error i {
        flex-shrink: 0;
        margin-top: 1px;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-Q : INFORMATIONAL SECTION HEADERS
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-section-header
 * Icon + h2 row that introduces each info section (Usage Guide, FAQ, etc.).
 */
    .stv-section-header {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 28px;
        padding-bottom: 14px;
        border-bottom: 1px solid var(--border-main);
    }
    
    .stv-section-header i {
        font-size: 22px;
        color: var(--accent-cyan);
        flex-shrink: 0;
    }
    
    .stv-section-header h2 {
        font-size: 20px;
        font-weight: 700;
        color: var(--text-main);
        margin: 0;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-R : USAGE GUIDE STEP CARDS
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-steps-grid
 * Responsive multi-column grid containing numbered step cards.
 * Uses auto-fill so it adapts from 5-col desktop to 1-col mobile.
 */
    .stv-steps-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
        gap: 16px;
        margin-bottom: 16px;
    }
    
    /**
 * .stv-step-card
 * Individual step card: number badge, icon, heading, description.
 */
    .stv-step-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 20px 16px;
        text-align: center;
        transition: var(--transition-base);
    }
    
    .stv-step-card:hover {
        border-color: var(--accent-cyan);
        transform: translateY(-3px);
        box-shadow: 0 8px 24px rgba(0, 229, 255, 0.08);
    }
    
    /**
 * .stv-step-num
 * The large ordinal number displayed at the top of each step card.
 * Gradient text for visual distinction.
 */
    .stv-step-num {
        font-size: 32px;
        font-weight: 800;
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        line-height: 1;
        margin-bottom: 10px;
    }
    
    /**
 * .stv-step-icon
 * Icon circle below the step number.
 */
    .stv-step-icon {
        font-size: 22px;
        color: var(--accent-cyan);
        margin-bottom: 10px;
    }
    
    .stv-step-card h4 {
        font-size: 14px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 8px;
    }
    
    .stv-step-card p {
        font-size: 12px;
        color: var(--text-muted);
        line-height: 1.6;
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-S : SECURITY KNOWLEDGE BASE FEATURE GRID
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-feature-grid
 * 2-column grid for the security knowledge base info cards.
 * Uses existing .info-card for the card content.
 */
    .stv-feature-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 16px;
    }
    
    .stv-feature-grid .info-card h3 {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 10px;
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    .stv-feature-grid .info-card p {
        font-size: 13px;
        line-height: 1.65;
        color: var(--text-muted);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-T : FAQ ACCORDION
───────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .stv-faq-wrapper
 * Outer card holding the FAQ section. Extends .info-card.
 * Overflow:hidden + position:relative needed for the decorative orb.
 */
    .stv-faq-wrapper {
        position: relative;
        overflow: hidden;
    }
    
    /**
 * .stv-faq-orb
 * Purely decorative gradient orb in the background of the FAQ card.
 * Adds depth without cluttering the content.
 */
    .stv-faq-orb {
        position: absolute;
        width: 300px;
        height: 300px;
        border-radius: 50%;
        background: radial-gradient(circle, rgba(209, 36, 255, 0.06) 0%, transparent 70%);
        top: -80px;
        right: -80px;
        pointer-events: none;
        z-index: 0;
    }
    
    /**
 * .stv-faq-heading
 * The "Frequently Asked Questions" title inside the FAQ card.
 */
    .stv-faq-heading {
        font-size: 18px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 24px;
        position: relative;
        z-index: 1;
    }
    
    /**
 * .stv-faq-container
 * Wrapper for all FAQ items. Stacks them vertically.
 */
    .stv-faq-container {
        display: flex;
        flex-direction: column;
        gap: 10px;
        position: relative;
        z-index: 1;
    }
    
    /**
 * .stv-faq-item
 * A single FAQ accordion item using native <details> element.
 * Native open/close is handled by the browser; no JS needed.
 */
    .stv-faq-item {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        transition: border-color 0.2s ease;
    }
    
    .stv-faq-item[open] {
        border-color: var(--accent-cyan);
    }
    
    /**
 * .stv-faq-question
 * The <summary> clickable row of each FAQ item.
 * Flex layout positions the chevron icon on the right.
 */
    .stv-faq-question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 14px 18px;
        cursor: pointer;
        font-weight: 600;
        font-size: 14px;
        color: var(--text-main);
        list-style: none;
        gap: 12px;
        transition: var(--transition-base);
        user-select: none;
    }
    
    .stv-faq-question::-webkit-details-marker {
        display: none;
    }
    
    .stv-faq-question:hover {
        color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.03);
    }
    
    /**
 * .stv-faq-chevron
 * The rotating chevron icon. Animates 180° when the <details> opens.
 */
    .stv-faq-chevron {
        font-size: 11px;
        transition: transform 0.3s ease;
        color: var(--text-muted);
        flex-shrink: 0;
    }
    
    details.stv-faq-item[open] .stv-faq-chevron {
        transform: rotate(180deg);
    }
    
    /**
 * .stv-faq-answer
 * The answer body revealed when the <details> is opened.
 */
    .stv-faq-answer {
        padding: 0 18px 16px;
        font-size: 13px;
        line-height: 1.7;
        color: var(--text-muted);
        border-top: 1px solid var(--border-subtle);
    }
    
    .stv-faq-answer p {
        margin-top: 14px;
    }
    
    .stv-faq-answer strong {
        color: var(--text-main);
    }
    
    .stv-faq-answer code {
        background: var(--bg-card);
        padding: 2px 6px;
        border-radius: var(--radius-sm);
        font-size: 12px;
        color: var(--accent-cyan);
        border: 1px solid var(--border-subtle);
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-U : RESPONSIVE — TABLET (max-width: 600px)
   Collapse 2-column panel grid to single column.
   Adjust card padding, pill wrapping, and step grid layout.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 600px) {
        
        /* Stack panel columns vertically on tablets */
        .stv-panel-grid {
            grid-template-columns: 1fr;
            gap: 14px;
        }
        
        /* Feature grid collapses to single column */
        .stv-feature-grid {
            grid-template-columns: 1fr;
        }
        
        /* Steps grid: 2-column on tablet */
        .stv-steps-grid {
            grid-template-columns: 1fr 1fr;
        }
        
        /* Tab buttons: slightly tighter padding */
        .stv-tab-btn {
            padding: 14px 12px;
            font-size: 13px;
        }
        
        /* Hero subtitle: smaller on tablet */
        .stv-badge {
            font-size: 10px;
            padding: 5px 12px;
            flex-wrap: wrap;
            justify-content: center;
        }
        
        /* Drop zone: reduce height */
        .stv-drop-zone {
            padding: 24px 16px;
        }
        
        /* Card body: tighter padding */
        .stv-card-body {
            padding: 16px;
            gap: 14px;
        }
        
        /* FAQ question: slightly smaller */
        .stv-faq-question {
            font-size: 13px;
            padding: 12px 14px;
        }
        
        /* Section header: reduce heading size */
        .stv-section-header h2 {
            font-size: 18px;
        }
        
    }
    
    
    /* ─────────────────────────────────────────────────────────────────────────────
   57-V : RESPONSIVE — MOBILE (max-width: 480px)
   Full single-column layout for small phones. Compact all spacings.
───────────────────────────────────────────────────────────────────────────── */
    
    @media (max-width: 480px) {
        
        /* Steps grid: single column on phone */
        .stv-steps-grid {
            grid-template-columns: 1fr;
        }
        
        /* Tab buttons: compact on phones */
        .stv-tab-btn {
            padding: 12px 8px;
            font-size: 12px;
        }
        
        .stv-tab-btn small {
            display: none;
            /* Hide sub-labels on very small screens */
        }
        
        /* Hero pills: allow full-width wrapping */
        .stv-pills {
            gap: 6px;
        }
        
        .stv-pill {
            font-size: 11px;
            padding: 4px 10px;
        }
        
        /* Drop zone: compact on phones */
        .stv-drop-zone {
            padding: 20px 14px;
        }
        
        .stv-drop-icon {
            font-size: 28px;
        }
        
        .stv-drop-title {
            font-size: 14px;
        }
        
        /* Card body: minimal padding */
        .stv-card-body {
            padding: 14px 12px;
            gap: 12px;
        }
        
        /* Textarea: fewer visible rows on phone */
        .stv-textarea {
            min-height: 120px;
            font-size: 12px;
        }
        
        /* Algo badge: reduce padding */
        .stv-algo-badge {
            padding: 10px 12px;
            font-size: 12px;
        }
        
        /* Action button: full width naturally in btn-area */
        .stv-action-btn {
            font-size: 14px;
            padding: 14px 20px;
        }
        
        /* Download success banner: stack icon + text */
        .stv-download-success {
            flex-direction: column;
            text-align: center;
            gap: 8px;
        }
        
        /* Decoded output: smaller font */
        .stv-decoded-output {
            font-size: 12px;
        }
        
        /* FAQ answer: tighter padding */
        .stv-faq-answer {
            padding: 0 12px 14px;
            font-size: 12px;
        }
        
        /* Error block: compact */
        .stv-tool-error {
            font-size: 12px;
            padding: 10px 12px;
        }
        
        /* Capacity stats: smaller */
        .stv-cap-stats {
            font-size: 11px;
        }
        
        /* Step card: comfortable padding on phone */
        .stv-step-card {
            padding: 16px 12px;
        }
        
        .stv-step-num {
            font-size: 26px;
        }
        
        /* Section header: compact */
        .stv-section-header {
            gap: 10px;
            margin-bottom: 20px;
        }
        
        .stv-section-header h2 {
            font-size: 16px;
        }
        
        .stv-section-header i {
            font-size: 18px;
        }
        
    }
    
}

/* end @media all */
