    /* ──────────────────────────────────────────────────────────────────────────
   U) HISTORY HEADER ROW
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .usp-history-header
 * Flex row that places the "Recent Links" title on the left and the
 * "Clear All" button on the right.
 */
    .usp-history-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 14px;
        gap: 10px;
    }
    
    /**
 * .usp-history-title
 * The section title label — slightly larger than body text for hierarchy.
 */
    .usp-history-title {
        font-size: 15px;
        font-weight: 600;
        color: var(--text-main);
        display: flex;
        align-items: center;
        gap: 7px;
    }
    
    .usp-history-title i {
        color: var(--brand-secondary);
    }
    
    /**
 * .usp-clear-btn
 * Inherits .btn.btn-danger for colors. Only size/padding tuning here.
 */
    .usp-clear-btn {
        font-size: 12px;
        padding: 6px 14px;
    }
    
    
    /* ──────────────────────────────────────────────────────────────────────────
   V & W) HISTORY LIST & ROWS
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .usp-history-list
 * Unstyled <ul> that holds individual history item rows.
 */
    .usp-history-list {
        list-style: none;
        padding: 0;
        margin: 0;
        display: flex;
        flex-direction: column;
        gap: 8px;
    }
    
    /**
 * .usp-history-item  (dynamically injected by loadHistory() as .history-item)
 * Each row shows: short URL + original URL + date on the left,
 * and a copy button on the right. Injected class kept as .history-item by JS.
 */
    .history-item {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 10px 14px;
        transition: var(--transition-base);
        animation-fill-mode: both;
    }
    
    .history-item:hover {
        border-color: var(--border-subtle);
        background: var(--bg-card);
    }
    
    
    /* ──────────────────────────────────────────────────────────────────────────
   X) HISTORY ITEM TEXT COLUMNS (injected by JS as .h-info / .h-link / .h-orig)
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .h-info
 * Left column inside a history item. Stacks short URL, original URL, and date.
 */
    .h-info {
        display: flex;
        flex-direction: column;
        gap: 3px;
        flex: 1;
        min-width: 0;
        /* prevent overflow */
        overflow: hidden;
    }
    
    /**
 * .h-link
 * The short URL anchor inside a history item.
 */
    .h-link {
        font-size: 14px;
        font-weight: 700;
        color: var(--accent-cyan);
        text-decoration: none;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        transition: var(--transition-base);
    }
    
    .h-link:hover {
        color: var(--brand-primary);
    }
    
    /**
 * .h-orig
 * The original (long) URL shown below the short URL in the history item.
 * Truncated with ellipsis to prevent overflow on narrow screens.
 */
    .h-orig {
        font-size: 11px;
        color: var(--text-muted);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    
    /* ──────────────────────────────────────────────────────────────────────────
   Y) HISTORY ITEM ACTION BUTTONS (injected by JS as .h-actions)
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .h-actions
 * Right column inside a history item — holds the copy icon button.
 */
    .h-actions {
        flex-shrink: 0;
    }
    
    /**
 * Inline <button> injected by JS inside .h-actions.
 * Styled to look like a subtle icon-only action trigger.
 */
    .h-actions button {
        background: transparent;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-sm);
        color: var(--text-muted);
        width: 32px;
        height: 32px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        cursor: pointer;
        transition: var(--transition-base);
    }
    
    .h-actions button:hover {
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
        background: rgba(0, 229, 255, 0.07);
    }
    
    
    /* ──────────────────────────────────────────────────────────────────────────
   Z) KNOWLEDGE BASE ARTICLE SUB-CARD (SEO Info Section)
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .usp-kb-article
 * Sub-article card displayed inside an .info-card. Used in the "Advanced
 * Marketing Strategies" SEO section to visually group related mini-topics.
 */
    .usp-kb-article {
        background: var(--bg-input);
        border: 1px solid var(--border-subtle);
        border-radius: var(--radius-md);
        padding: 16px;
        margin-bottom: 14px;
    }
    
    .usp-kb-article:last-child {
        margin-bottom: 0;
    }
    
    .usp-kb-article h4 {
        font-size: 14px;
        font-weight: 700;
        color: var(--brand-secondary);
        margin-bottom: 8px;
        display: flex;
        align-items: center;
        gap: 7px;
    }
    
    .usp-kb-article h4 i {
        color: var(--accent-cyan);
        font-size: 13px;
    }
    
    .usp-kb-article p {
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.65;
        margin: 0;
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════
   SECTION 60-F : RESPONSIVE — TABLET (max-width: 600px)
   Form rows reflow to vertical stack. Share grid tightens up.
   Advanced panel reduces padding for comfortable tablet use.
══════════════════════════════════════════════════════════════════════════ */
    
    @media (max-width: 600px) {
        
        /* URL row: stack input above paste button on tablet */
        .usp-url-row {
            flex-direction: column;
            gap: 8px;
        }
        
        .usp-paste-btn {
            width: 100%;
            justify-content: center;
            padding: 12px 20px;
            font-size: 14px;
        }
        
        /* Alias prefix: slightly smaller font on tablet */
        .usp-alias-prefix {
            font-size: 12px;
            padding: 0 10px;
        }
        
        /* Advanced panel: tighter padding on tablet */
        .usp-advanced-panel {
            padding: 16px;
        }
        
        /* Toggle button: smaller font */
        .usp-toggle-btn {
            font-size: 13px;
            padding: 10px 16px;
        }
        
        /* Shorten button: full width on tablet */
        .usp-shorten-btn {
            max-width: 100%;
        }
        
        /* Result link box: allow text to wrap on tablet */
        .usp-result-link-box {
            flex-wrap: wrap;
        }
        
        /* QR image: slightly smaller on tablet */
        .usp-qr-image {
            width: 180px;
            height: 180px;
        }
        
        /* History header: allow wrap if space is tight */
        .usp-history-header {
            flex-wrap: wrap;
        }
        
        /* KB article: tighter padding */
        .usp-kb-article {
            padding: 14px;
        }
        
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════
   SECTION 60-G : RESPONSIVE — MOBILE (max-width: 480px)
   Full single-column layout. Touch-friendly sizing for all controls.
══════════════════════════════════════════════════════════════════════════ */
    
    @media (max-width: 480px) {
        
        /* Input group: reduce bottom gap on small phones */
        .usp-input-group {
            margin-bottom: 14px;
        }
        
        /* Alias prefix: compact for very small screens */
        .usp-alias-prefix {
            font-size: 11px;
            padding: 0 8px;
        }
        
        /* Share grid: 4 buttons stay in one row but smaller */
        .usp-share-btn {
            width: 40px;
            height: 40px;
            font-size: 15px;
        }
        
        /* QR image: compact on phone */
        .usp-qr-image {
            width: 160px;
            height: 160px;
        }
        
        /* Short URL text: smaller on phone */
        .usp-short-url-text {
            font-size: 14px;
        }
        
        /* History item: tighter padding */
        .history-item {
            padding: 9px 12px;
        }
        
        /* History short link: smaller on phone */
        .h-link {
            font-size: 13px;
        }
        
        /* Clear button: compact on phone */
        .usp-clear-btn {
            font-size: 11px;
            padding: 5px 10px;
        }
        
        /* Section divider: smaller on phone */
        .usp-section-divider {
            font-size: 13px;
        }
        
        /* Advanced panel: minimal padding on phone */
        .usp-advanced-panel {
            padding: 14px 12px;
        }
        
        /* KB article h4: smaller on phone */
        .usp-kb-article h4 {
            font-size: 13px;
        }
        
        /* Result container: tighter padding on phone */
        .usp-result-container {
            padding: 16px 14px;
        }
        
        /* Result label: compact on phone */
        .usp-result-label {
            font-size: 13px;
        }
        
    }
    
}

/* end @media all */
/* #endregion */



















/* ════════════════════════════════════════════════════════════════════════════
   SECTION 61: META GEN ULTRA — SEO META TAG GENERATOR
   Prefix  : mgu-
   Purpose : Styles for the two-column SEO meta tag generator tool.
             Covers: split layout wrapper, live score meter, keyword tag
             system, color picker row, preview panel tabs, Google SERP card,
             social card (OG preview), code output textarea, step guide grid,
             knowledge base feature grid, and FAQ accordion.
   Reuse   : All classes are prefixed .mgu- and are safe to reuse in any
             future two-panel / live-preview tool with minimal overrides.
════════════════════════════════════════════════════════════════════════════ */

/* #region SECTION 61: META GEN ULTRA */
@media all {
    
    /* ──────────────────────────────────────────────────────────────────────────
   A) TWO-COLUMN LAYOUT WRAPPER
   Sits inside <main>. Left = form container, Right = preview panel.
   Collapses to single column on mobile automatically via media queries.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-layout-wrapper
 * Flex row that holds the input .container on the left and the
 * .mgu-preview-panel on the right. Max-width 1200px keeps it readable
 * on ultra-wide screens.
 */
    .mgu-layout-wrapper {
        display: flex;
        align-items: flex-start;
        gap: 20px;
        width: 100%;
        max-width: 1200px;
        margin-bottom: 30px;
    }
    
    /**
 * Left panel (.container) — takes fixed basis so it doesn't shrink below
 * the comfortable form-field width.
 */
    .mgu-layout-wrapper>.container {
        flex: 0 0 460px;
        max-width: 460px;
        margin-bottom: 0;
        /* override container default; gap handles spacing */
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   B) LIVE SEO SCORE METER BOX
   Horizontal strip at the top of the form showing a real-time score bar.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-score-box
 * Outer wrapper for the score meter strip: label group | bar | value.
 * Uses a subtle background to visually separate it from the form fields.
 */
    .mgu-score-box {
        display: flex;
        align-items: center;
        gap: 16px;
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 14px 18px;
        margin-bottom: 24px;
    }
    
    /**
 * .mgu-score-label-group
 * Stacks the "LIVE SEO SCORE" heading above the standards sub-label.
 */
    .mgu-score-label-group {
        display: flex;
        flex-direction: column;
        gap: 2px;
        flex-shrink: 0;
    }
    
    /**
 * .mgu-score-title
 * Bold uppercase label for the meter strip.
 */
    .mgu-score-title {
        font-size: 13px;
        font-weight: 700;
        color: var(--text-main);
        white-space: nowrap;
    }
    
    /**
 * .mgu-score-bar-wrap
 * Flex-grows to fill horizontal space between label and numeric value.
 */
    .mgu-score-bar-wrap {
        flex: 1;
        min-width: 60px;
    }
    
    /**
 * .mgu-score-bar-bg
 * Full-width track for the animated progress bar.
 */
    .mgu-score-bar-bg {
        width: 100%;
        height: 10px;
        background: var(--bg-input);
        border-radius: var(--radius-pill);
        overflow: hidden;
        border: 1px solid var(--border-subtle);
    }
    
    /**
 * .mgu-score-bar-fill
 * Animated fill; width and background-color are set dynamically by JS
 * (calculateScore function) to reflect the current score percentage.
 */
    .mgu-score-bar-fill {
        height: 100%;
        width: 0%;
        background-color: var(--brand-primary);
        border-radius: var(--radius-pill);
        transition: width 0.5s ease, background-color 0.5s ease;
    }
    
    /**
 * .mgu-score-value
 * Numeric score display (e.g. "75/100"). Set by JS via scoreText element.
 */
    .mgu-score-value {
        font-size: 16px;
        font-weight: 800;
        color: var(--text-main);
        min-width: 52px;
        text-align: right;
        flex-shrink: 0;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   C) FORM INPUT GROUPS
   Wrapper for a label + optional counter badge + input/textarea/select.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-input-group
 * Stacks: label row (label + char-count) above the input control.
 * Margin-bottom spaces it from the next group.
 */
    .mgu-input-group {
        position: relative;
        margin-bottom: 18px;
        text-align: left;
    }
    
    /**
 * Label text inside input groups — small, muted, uppercase feel.
 */
    .mgu-input-group label {
        display: inline-block;
        font-size: 12px;
        font-weight: 700;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 0.6px;
        margin-bottom: 7px;
    }
    
    /**
 * .char-count
 * Character / pixel counter badge floated to the right of the label row.
 * JS adds .limit-ok / .limit-warn / .limit-err to colorise the badge.
 */
    .char-count {
        float: right;
        font-size: 11px;
        font-weight: 700;
        padding: 2px 8px;
        border-radius: var(--radius-pill);
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        transition: var(--transition-base);
    }
    
    .char-count.limit-ok {
        color: var(--status-text-success);
        border-color: var(--status-success);
    }
    
    .char-count.limit-warn {
        color: var(--accent-yellow);
        border-color: var(--accent-yellow);
    }
    
    .char-count.limit-err {
        color: var(--accent-red);
        border-color: var(--accent-red);
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   D) KEYWORD TAG SYSTEM
   Interactive pill-tag input area. JS renders .mgu-tag spans with an
   ×-icon inside the #tagContainer div.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-tag-container
 * The clickable area that hosts all keyword pill tags and the live text
 * input. Matches the visual style of .input-control.
 */
    .mgu-tag-container {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 6px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 8px 12px;
        cursor: text;
        min-height: 46px;
        transition: border-color 0.25s ease;
    }
    
    .mgu-tag-container:focus-within {
        border-color: var(--brand-primary);
        box-shadow: 0 0 0 3px rgba(255, 0, 85, 0.15);
    }
    
    /**
 * .mgu-tag-input
 * The always-visible text input inside the tag container. Has no visible
 * border of its own; the container provides the box styling.
 */
    .mgu-tag-input {
        flex: 1;
        min-width: 100px;
        background: transparent;
        border: none;
        outline: none;
        color: var(--text-main);
        font-size: 14px;
        padding: 2px 4px;
    }
    
    .mgu-tag-input::placeholder {
        color: var(--text-muted);
        font-size: 13px;
    }
    
    /**
 * .tag
 * Individual keyword pill injected by renderTags() in JS.
 * Contains the keyword text and an ×-icon for removal.
 */
    .tag {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        background: rgba(255, 0, 85, 0.12);
        border: 1px solid rgba(255, 0, 85, 0.35);
        color: var(--brand-primary);
        border-radius: var(--radius-pill);
        padding: 3px 10px 3px 10px;
        font-size: 12px;
        font-weight: 600;
        cursor: default;
        transition: var(--transition-base);
    }
    
    .tag:hover {
        background: rgba(255, 0, 85, 0.2);
    }
    
    /**
 * ×-icon inside a .tag pill — becomes a remove button via JS onclick.
 */
    .tag i {
        cursor: pointer;
        opacity: 0.7;
        font-size: 10px;
        transition: opacity 0.2s ease;
    }
    
    .tag i:hover {
        opacity: 1;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   E) THEME COLOR ROW
   Side-by-side: native color picker + read-only hex text input.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-color-row
 * Flex row that holds the color picker swatch and the hex value input.
 */
    .mgu-color-row {
        display: flex;
        align-items: center;
        gap: 10px;
    }
    
    /**
 * .mgu-color-picker
 * Native <input type="color"> styled to a fixed square swatch.
 * Padding removed so the swatch fills the border box cleanly.
 */
    .mgu-color-picker {
        padding: 0;
        height: 46px;
        width: 60px;
        cursor: pointer;
        border-radius: var(--radius-sm);
        border: 1px solid var(--border-main);
        background: transparent;
        flex-shrink: 0;
    }
    
    /**
 * .mgu-hex-input
 * The read-only hex display input. Inherits .input-control styles;
 * cursor: default signals it is non-editable.
 */
    .mgu-hex-input {
        flex: 1;
        cursor: default;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   F) SECTION DIVIDER (Social & Advanced label stripe)
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-section-divider
 * Decorative horizontal rule with inline label. Separates the primary SEO
 * fields from the social/advanced fields visually.
 */
    .mgu-section-divider {
        margin: 26px 0 18px;
        border-bottom: 1px solid var(--border-main);
        padding-bottom: 10px;
        color: var(--brand-secondary);
        font-weight: 700;
        font-size: 13px;
        text-transform: uppercase;
        letter-spacing: 1px;
        text-align: left;
    }
    
    .mgu-section-divider i {
        margin-right: 6px;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   G) RIGHT PREVIEW PANEL
   Wraps the tab nav + three tab content panels (Google, Social, Code).
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-preview-panel
 * Sticky right column that displays the live preview as the user types.
 * Position: sticky keeps it in view while scrolling the long form.
 */
    .mgu-preview-panel {
        flex: 1;
        min-width: 0;
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 24px;
        box-shadow: var(--shadow-card);
        position: sticky;
        top: 90px;
        /* clears the sticky global header */
        align-self: flex-start;
    }
    
    /**
 * .preview-content
 * Each tab panel. Hidden by default; JS adds .active to show one at a time.
 */
    .preview-content {
        display: none;
    }
    
    .preview-content.active {
        display: block;
    }
    
    /**
 * .mgu-preview-label
 * Small uppercase label above each preview card (e.g. "GOOGLE SEARCH RESULT").
 */
    .mgu-preview-label {
        display: block;
        margin-bottom: 12px;
        font-size: 11px;
        font-weight: 700;
        color: var(--text-muted);
        letter-spacing: 0.8px;
        text-transform: uppercase;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   H) GENERIC PREVIEW CARD SHELL
   Shared visual container for both the Google card and the social card.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-preview-card
 * White-ish card shell that wraps a preview simulation.
 */
    .mgu-preview-card {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   I) GOOGLE SERP PREVIEW
   Simulates a Google search result: cite row, blue title, grey description.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-google-preview
 * Padding that mirrors real Google result spacing.
 */
    .mgu-google-preview {
        padding: 18px 20px;
        font-family: Arial, sans-serif;
        /* match Google's actual SERP font */
    }
    
    /**
 * .mgu-g-cite
 * Breadcrumb row: small favicon icon + domain + overflow menu icon.
 */
    .mgu-g-cite {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 6px;
        font-size: 14px;
        color: var(--text-muted);
    }
    
    /**
 * .mgu-g-icon
 * Circular favicon placeholder.
 */
    .mgu-g-icon {
        width: 26px;
        height: 26px;
        border-radius: 50%;
        background: var(--bg-input);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        flex-shrink: 0;
    }
    
    /**
 * .mgu-g-title
 * Blue clickable title link — matches Google's exact #1a0dab / blue style.
 * Updated dynamically by updatePreviews() in JS.
 */
    .mgu-g-title {
        display: block;
        font-size: 20px;
        font-weight: 400;
        color: #8ab4f8;
        /* Google-style blue for dark mode */
        text-decoration: none;
        margin-bottom: 4px;
        line-height: 1.3;
        word-break: break-word;
    }
    
    .mgu-g-title:hover {
        text-decoration: underline;
        color: #8ab4f8;
    }
    
    /**
 * .mgu-g-desc
 * Grey snippet paragraph. Truncated at 160 chars by JS.
 */
    .mgu-g-desc {
        font-size: 14px;
        color: var(--text-muted);
        line-height: 1.58;
        word-break: break-word;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   J) SOCIAL CARD PREVIEW (Facebook / LinkedIn / Twitter)
   Replicates the link-unfurl card shown on social platforms.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-social-preview
 * Outer card — no additional padding needed; image bleeds to edges.
 */
    .mgu-social-preview {
        border-radius: var(--radius-md);
    }
    
    /**
 * .mgu-social-img-box
 * 16:9-ish image placeholder. JS replaces the icon with a real <img>
 * when a valid OG Image URL is entered.
 */
    .mgu-social-img-box {
        width: 100%;
        height: 200px;
        background: var(--bg-input);
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--text-muted);
        overflow: hidden;
        border-bottom: 1px solid var(--border-main);
    }
    
    /**
 * .mgu-social-text
 * Text block below the image — domain, title, description.
 */
    .mgu-social-text {
        padding: 14px 16px;
        background: var(--bg-card);
    }
    
    /**
 * .mgu-s-domain
 * Small uppercase domain label (e.g. "EXAMPLE.COM").
 */
    .mgu-s-domain {
        font-size: 11px;
        color: var(--text-muted);
        text-transform: uppercase;
        letter-spacing: 0.5px;
        margin-bottom: 4px;
    }
    
    /**
 * .mgu-s-title
 * Bold card title text (maps to og:title).
 */
    .mgu-s-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 4px;
        line-height: 1.3;
        word-break: break-word;
    }
    
    /**
 * .mgu-s-desc
 * Shorter description snippet below the social title.
 */
    .mgu-s-desc {
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.5;
        word-break: break-word;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   K) HTML CODE OUTPUT TEXTAREA
   Read-only monospace textarea showing the generated <head> tags.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-code-output
 * Styled textarea for the generated HTML code. Uses Fira Code for
 * readability; a custom scrollbar matches the dark theme.
 */
    .mgu-code-output {
        width: 100%;
        height: 340px;
        font-family: 'Fira Code', 'Courier New', monospace;
        font-size: 12px;
        color: #a5d6ff;
        line-height: 1.6;
        background: var(--bg-card);
        border-radius: var(--radius-md);
        padding: 15px;
        border: 1px solid var(--border-main);
        resize: vertical;
        outline: none;
        box-sizing: border-box;
        display: block;
        scrollbar-width: thin;
        scrollbar-color: var(--border-main) transparent;
    }
    
    .mgu-code-output::-webkit-scrollbar {
        width: 6px;
    }
    
    .mgu-code-output::-webkit-scrollbar-track {
        background: transparent;
    }
    
    .mgu-code-output::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 3px;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   L) SEO INFO SECTION — STEP GUIDE GRID
   Four-card numbered step layout inside .info-section-wrapper.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-step-grid
 * Responsive two-column card grid for the numbered step cards.
 */
    .mgu-step-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
        gap: 20px;
        margin-top: 10px;
    }
    
    /**
 * .mgu-step-card
 * Individual step card with a numbered bubble header.
 */
    .mgu-step-card {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        padding: 20px;
        text-align: left;
        transition: var(--transition-base);
    }
    
    .mgu-step-card:hover {
        border-color: var(--brand-primary);
        box-shadow: var(--shadow-soft);
    }
    
    .mgu-step-card h4 {
        font-size: 15px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 10px;
    }
    
    .mgu-step-card p {
        font-size: 13px;
        color: var(--text-muted);
        line-height: 1.65;
    }
    
    /**
 * .mgu-step-num
 * Circular gradient numbered bubble at the top of each step card.
 */
    .mgu-step-num {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: var(--gradient-text);
        color: #fff;
        font-size: 16px;
        font-weight: 800;
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 14px;
        flex-shrink: 0;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   M) KNOWLEDGE BASE SECTION HEADING
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-kb-heading
 * Large section heading for the "Advanced SEO Knowledge Base" divider.
 */
    .mgu-kb-heading {
        font-size: 1.35rem;
        font-weight: 700;
        color: var(--text-main);
        margin: 50px 0 25px;
        display: flex;
        align-items: center;
        gap: 12px;
        border-left: 4px solid var(--accent-cyan);
        padding-left: 15px;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   N) KNOWLEDGE BASE FEATURE GRID
   Two-column grid of info-cards for SEO knowledge topics.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-feature-grid
 * Auto-fill two-column grid wrapping the knowledge base .info-card items.
 */
    .mgu-feature-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
        gap: 20px;
        margin-bottom: 30px;
    }
    
    .mgu-feature-grid .info-card h3 {
        display: flex;
        align-items: center;
        gap: 10px;
        font-size: 16px;
        font-weight: 700;
        color: var(--text-main);
        margin-bottom: 12px;
    }
    
    .mgu-feature-grid .info-card p {
        font-size: 13.5px;
        color: var(--text-muted);
        line-height: 1.7;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   O) INFO SECTION HEADINGS (shared by guide and FAQ)
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-info-heading
 * h2-level heading with a coloured left border accent used in the info
 * section cards (Usage Guide, FAQ).
 */
    .mgu-info-heading {
        display: flex;
        align-items: center;
        gap: 12px;
        font-size: 22px;
        font-weight: 700;
        color: var(--text-main);
        border-left: 5px solid var(--brand-primary);
        padding-left: 18px;
        margin-bottom: 25px;
        line-height: 1.3;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   P) FAQ ACCORDION
   HTML <details> / <summary> accordion for the Frequently Asked Questions.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-faq-container
 * Outer wrapper that stacks all FAQ items with a gap between them.
 */
    .mgu-faq-container {
        display: flex;
        flex-direction: column;
        gap: 12px;
    }
    
    /**
 * .mgu-faq-item
 * Individual <details> accordion item. Border highlights on open state.
 */
    .mgu-faq-item {
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        transition: border-color 0.25s ease;
    }
    
    .mgu-faq-item[open] {
        border-color: var(--accent-cyan);
    }
    
    /**
 * .mgu-faq-question
 * <summary> element — acts as the clickable header of each accordion item.
 * The chevron icon rotates 180° when the item is open.
 */
    .mgu-faq-question {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 16px 18px;
        font-size: 14px;
        font-weight: 600;
        color: var(--text-main);
        cursor: pointer;
        list-style: none;
        gap: 10px;
    }
    
    .mgu-faq-question::-webkit-details-marker {
        display: none;
    }
    
    .mgu-faq-question i {
        font-size: 12px;
        color: var(--text-muted);
        flex-shrink: 0;
        transition: transform 0.3s ease;
    }
    
    .mgu-faq-item[open] .mgu-faq-question i {
        transform: rotate(180deg);
    }
    
    /**
 * .mgu-faq-answer
 * Revealed content below the summary when the <details> is open.
 */
    .mgu-faq-answer {
        padding: 0 18px 16px;
        border-top: 1px solid var(--border-subtle);
    }
    
    .mgu-faq-answer p {
        font-size: 13.5px;
        color: var(--text-muted);
        line-height: 1.7;
        margin-top: 12px;
    }
    
    /* ──────────────────────────────────────────────────────────────────────────
   Q) FAQ DECORATIVE GLOW
   Cosmetic radial gradient orb in the top-right corner of the FAQ card.
────────────────────────────────────────────────────────────────────────── */
    
    /**
 * .mgu-faq-glow
 * Absolutely positioned decorative blur; pointer-events: none ensures it
 * never interferes with user interaction.
 */
    .mgu-faq-glow {
        position: absolute;
        top: -50px;
        right: -50px;
        width: 150px;
        height: 150px;
        background: radial-gradient(circle, rgba(0, 229, 255, 0.1) 0%, transparent 70%);
        border-radius: 50%;
        pointer-events: none;
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════
   SECTION 61-F : RESPONSIVE — TABLET (max-width: 600px)
   Two-column layout becomes single column; preview panel loses sticky.
   Score meter reflowed to wrap; step grid collapses to single column.
══════════════════════════════════════════════════════════════════════════ */
    
    @media (max-width: 600px) {
        
        /* Stack layout: form above, preview below */
        .mgu-layout-wrapper {
            flex-direction: column;
            gap: 16px;
        }
        
        /* Left panel: full width */
        .mgu-layout-wrapper>.container {
            flex: none;
            max-width: 100%;
            width: 100%;
        }
        
        /* Preview panel: full width, no sticky */
        .mgu-preview-panel {
            position: static;
            width: 100%;
            padding: 18px;
        }
        
        /* Score meter: wrap to two lines on tablet */
        .mgu-score-box {
            flex-wrap: wrap;
            gap: 10px;
        }
        
        .mgu-score-value {
            min-width: 44px;
            font-size: 15px;
        }
        
        /* Step grid: single column */
        .mgu-step-grid {
            grid-template-columns: 1fr;
        }
        
        /* Feature grid: single column */
        .mgu-feature-grid {
            grid-template-columns: 1fr;
        }
        
        /* Code textarea: shorter on tablet */
        .mgu-code-output {
            height: 260px;
        }
        
        /* Social image box: slightly shorter */
        .mgu-social-img-box {
            height: 170px;
        }
        
        /* KB heading: smaller text */
        .mgu-kb-heading {
            font-size: 1.1rem;
            margin: 36px 0 18px;
        }
        
        /* Info heading: smaller on tablet */
        .mgu-info-heading {
            font-size: 19px;
        }
        
    }
    
    
    /* ══════════════════════════════════════════════════════════════════════════
   SECTION 61-G : RESPONSIVE — MOBILE (max-width: 480px)
   Touch-friendly sizing: larger tap targets, reduced padding, compact UI.
══════════════════════════════════════════════════════════════════════════ */
    
    @media (max-width: 480px) {
        
        /* Score box: stack label + bar on separate lines */
        .mgu-score-box {
            flex-direction: column;
            align-items: stretch;
            gap: 8px;
            padding: 12px 14px;
        }
        
        .mgu-score-bar-wrap {
            width: 100%;
        }
        
        .mgu-score-value {
            text-align: left;
            font-size: 14px;
        }
        
        /* Input group: tighter spacing on small phones */
        .mgu-input-group {
            margin-bottom: 14px;
        }
        
        /* Tag container: smaller padding */
        .mgu-tag-container {
            padding: 7px 10px;
        }
        
        /* Color row: picker same height as input on phone */
        .mgu-color-picker {
            height: 42px;
            width: 50px;
        }
        
        /* Preview panel: minimal padding on phone */
        .mgu-preview-panel {
            padding: 14px 12px;
        }
        
        /* Code textarea: shorter on phone */
        .mgu-code-output {
            height: 220px;
            font-size: 11px;
        }
        
        /* Social image box: compact on phone */
        .mgu-social-img-box {
            height: 150px;
        }
        
        /* Google title: smaller on phone */
        .mgu-g-title {
            font-size: 17px;
        }
        
        /* Step card: tighter padding */
        .mgu-step-card {
            padding: 16px;
        }
        
        /* FAQ question: smaller text on phone */
        .mgu-faq-question {
            font-size: 13px;
            padding: 14px 14px;
        }
        
        .mgu-faq-answer {
            padding: 0 14px 14px;
        }
        
        /* Section divider: compact on phone */
        .mgu-section-divider {
            font-size: 12px;
            margin: 20px 0 14px;
        }
        
        /* Info heading: compact on phone */
        .mgu-info-heading {
            font-size: 17px;
            gap: 8px;
            padding-left: 14px;
        }
        
        /* KB heading: compact on phone */
        .mgu-kb-heading {
            font-size: 1rem;
            margin: 28px 0 14px;
            padding-left: 12px;
        }
        
    }
    
}

