/* #region SECTION 65: ULTRA DIFF PRO MAX — MINIMAL UNIQUE STYLES ONLY */

/*
 * =============================================================================
 *  SECTION 65 — Ultra Diff Pro Max (dif- prefix)
 *  Tool    : Text & Code Diff Checker
 *  Scope   : All UI components unique to this tool that have no equivalent
 *            in the shared tools-template.css component library.
 *            Everything reusable (buttons, containers, badges, alerts) is
 *            already handled by the global system.  Only truly tool-specific
 *            layouts and diff-rendering classes live here.
 * =============================================================================
 *
 *  Components defined in this section
 *  ────────────────────────────────────────────────────────────────────────────
 *  .dif-toolbar            — Horizontal pill-button toolbar (view / utility)
 *  .dif-toolbar-divider    — 1 px vertical separator inside the toolbar
 *  .dif-tool-btn           — Individual toolbar pill button
 *  .dif-tool-btn.active    — Active / pressed state
 *  .dif-tool-btn-danger    — Danger (red) variant for the Clear button
 *  .dif-editor-grid        — Three-column flex layout: left | mid | right
 *  .dif-editor-box         — Individual editor panel (header + textarea)
 *  .dif-box-header         — Header bar inside each editor panel
 *  .dif-box-label          — Label text (ORIGINAL / MODIFIED)
 *  .dif-label-original     — Accent color override for ORIGINAL label
 *  .dif-label-modified     — Accent color override for MODIFIED label
 *  .dif-file-actions       — Right-side file-action controls in header
 *  .dif-stat-badge         — Character count badge inside editor header
 *  .dif-editor-textarea    — Monospace code-input textarea
 *  .dif-editor-box.drag-active — Drag-over highlight state
 *  .dif-mid-controls       — Column of Copy / Swap arrow buttons
 *  .dif-mid-btn            — Individual mid-column icon button
 *  .dif-compare-wrap       — Full-width wrapper for the CTA compare button
 *  .dif-compare-btn        — Primary gradient CTA button
 *  .dif-loading-overlay    — Loading state overlay inside compare button
 *  .dif-loader-inner       — Flex row: spinner + "Processing…" text
 *  .dif-spinner            — CSS-only animated spinner
 *  .dif-viewer             — Outer wrapper for the diff results section
 *  .dif-results-header     — Flex bar: stats (left) + action buttons (right)
 *  .dif-result-stats       — Removed / Added count display
 *  .dif-stat-removed       — Red "Removed" label
 *  .dif-stat-added         — Green "Added" label
 *  .dif-result-actions     — Container for Copy Changes / Save Report btns
 *  .dif-result-btn         — Compact variant of .dif-tool-btn for results bar
 *  .dif-content            — Scrollable diff output region
 *  .diff-view-split        — Side-by-side split diff layout
 *  .diff-view-unified      — Single-column unified diff layout
 *  .diff-row               — One row in the diff output
 *  .diff-half              — One half-panel in split-view rows
 *  .line-num               — Line-number gutter cell
 *  .line-code              — Code content cell
 *  .bg-add / .text-add     — Insertion highlight (green)
 *  .bg-rem / .text-rem     — Deletion highlight (red)
 *  .bg-empty               — Placeholder cell for side with no change
 *  .dif-info-flex          — Flex row for the info-card security section
 *  .dif-info-text          — Text column inside info flex
 *  .dif-info-img-wrap      — Image column inside info flex
 *  .dif-info-img           — The shield illustration image
 *  .dif-feature-list       — Styled unstyled list with icon + text rows
 *  .dif-icon-green         — Green icon color helper
 *  .dif-feature-grid       — 2-column auto-fit grid for feature cards
 *  .dif-feature-heading    — Colored sub-heading inside feature cards
 *  .dif-how-to-img         — How-to guide screenshot image
 *  .dif-how-to-list        — Styled ordered list for usage instructions
 * =============================================================================
 */

@media all {
    
    /* ──────────────────────────────────────────────
   TOOLBAR
   A horizontally scrollable row of pill-shaped
   toggle / action buttons above the editor grid.
   The .active class is toggled by JS to mark the
   currently selected mode (Split / Unified / Wrap).
────────────────────────────────────────────── */
    .dif-toolbar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 6px;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-pill);
        padding: 7px 12px;
        margin-bottom: 18px;
        justify-content: center;
    }
    
    /* ── 1 px vertical separator bar between toolbar button groups ── */
    .dif-toolbar-divider {
        width: 1px;
        height: 22px;
        background: var(--border-main);
        margin: 0 4px;
        flex-shrink: 0;
    }
    
    /* ── Individual pill button inside the toolbar ── */
    .dif-tool-btn {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        background: transparent;
        color: var(--text-muted);
        border: 1px solid transparent;
        border-radius: var(--radius-pill);
        padding: 5px 13px;
        font-size: 12.5px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
        white-space: nowrap;
    }
    
    .dif-tool-btn:hover {
        background: var(--bg-card);
        color: var(--text-main);
        border-color: var(--border-main);
    }
    
    /* Active / pressed state — brand primary highlight */
    .dif-tool-btn.active {
        background: var(--brand-primary);
        color: #fff;
        border-color: var(--brand-primary);
    }
    
    /* Danger variant — used for the Clear (trash) button */
    .dif-tool-btn.dif-tool-btn-danger {
        color: var(--accent-red);
    }
    
    .dif-tool-btn.dif-tool-btn-danger:hover {
        background: rgba(255, 71, 87, 0.12);
        border-color: var(--accent-red);
        color: var(--accent-red);
    }
    
    /* ──────────────────────────────────────────────
   EDITOR GRID
   Three-column flex layout:
     [Left Editor] [Mid Controls] [Right Editor]
   The mid column is a fixed-width strip of icon
   buttons; left and right editors share remaining
   space equally (flex: 1 each).
────────────────────────────────────────────── */
    .dif-editor-grid {
        display: flex;
        gap: 10px;
        align-items: stretch;
        margin-bottom: 18px;
        min-width: 0;
    }
    
    /* ── Individual editor panel (header + textarea) ── */
    .dif-editor-box {
        flex: 1;
        min-width: 0;
        /* Prevents flex overflow on small text */
        display: flex;
        flex-direction: column;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        transition: border-color 0.25s ease;
    }
    
    /* Highlight the dropzone when a file is dragged over it */
    .dif-editor-box.drag-active {
        border-color: var(--accent-cyan);
        box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.18);
    }
    
    /* ── Editor header bar: label on left, actions on right ── */
    .dif-box-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 8px 12px;
        background: var(--bg-card);
        border-bottom: 1px solid var(--border-main);
        gap: 8px;
        flex-shrink: 0;
    }
    
    /* ── Editor label text (ORIGINAL / MODIFIED) ── */
    .dif-box-label {
        font-size: 11px;
        font-weight: 800;
        letter-spacing: 0.8px;
        color: var(--text-muted);
        text-transform: uppercase;
        display: flex;
        align-items: center;
        gap: 5px;
    }
    
    /* ORIGINAL label accent — brand primary */
    .dif-label-original {
        color: var(--brand-primary);
    }
    
    /* MODIFIED label accent — brand secondary / cyan */
    .dif-label-modified {
        color: var(--accent-cyan);
    }
    
    /* ── Right-side actions in the editor header (stat + upload btn) ── */
    .dif-file-actions {
        display: flex;
        align-items: center;
        gap: 6px;
        flex-shrink: 0;
    }
    
    /* Character count badge */
    .dif-stat-badge {
        color: var(--text-muted);
        font-size: 11px;
        font-weight: 500;
    }
    
    /* ── Monospace code textarea ── */
    .dif-editor-textarea {
        flex: 1;
        width: 100%;
        min-height: 260px;
        background: var(--bg-input);
        color: var(--text-main);
        border: none;
        outline: none;
        resize: vertical;
        padding: 12px 14px;
        font-family: 'Fira Code', 'Courier New', monospace;
        font-size: 13px;
        line-height: 1.65;
        white-space: pre;
        overflow: auto;
        tab-size: 4;
        transition: background 0.2s ease;
        color-scheme: var(--input-scheme);
    }
    
    .dif-editor-textarea::placeholder {
        color: var(--text-muted);
        opacity: 0.6;
        font-style: italic;
    }
    
    /* ──────────────────────────────────────────────
   MID CONTROLS
   A narrow vertical strip between the two editors
   containing three icon buttons: Copy →, Swap, ← Copy.
   Centered vertically in the editor grid row.
────────────────────────────────────────────── */
    .dif-mid-controls {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 6px;
        flex-shrink: 0;
        padding: 4px 0;
    }
    
    /* ── Individual mid-column icon button ── */
    .dif-mid-btn {
        width: 32px;
        height: 32px;
        border-radius: 50%;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 12px;
        transition: var(--transition-base);
        flex-shrink: 0;
    }
    
    .dif-mid-btn:hover {
        background: var(--brand-primary);
        border-color: var(--brand-primary);
        color: #fff;
        transform: scale(1.1);
    }
    
    /* ──────────────────────────────────────────────
   COMPARE CTA BUTTON
   Full-width gradient button that triggers the
   Web Worker diff engine. Contains an internal
   .dif-loading-overlay to indicate processing.
────────────────────────────────────────────── */
    .dif-compare-wrap {
        margin-bottom: 20px;
    }
    
    .dif-compare-btn {
        position: relative;
        width: 100%;
        padding: 16px 24px;
        background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
        color: #fff;
        border: none;
        border-radius: var(--radius-md);
        font-size: 16px;
        font-weight: 800;
        letter-spacing: 1.5px;
        cursor: pointer;
        transition: opacity 0.3s ease, transform 0.15s ease;
        overflow: hidden;
    }
    
    .dif-compare-btn:hover:not(:disabled) {
        opacity: 0.92;
        transform: translateY(-1px);
    }
    
    .dif-compare-btn:disabled {
        cursor: not-allowed;
        opacity: 0.6;
    }
    
    /* ── Internal Loading Overlay (absolute, sits over the button text) ── */
    .dif-loading-overlay {
        position: absolute;
        inset: 0;
        background: rgba(0, 0, 0, 0.55);
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: var(--radius-md);
    }
    
    /* Flex row inside the overlay: spinner + text */
    .dif-loader-inner {
        display: flex;
        align-items: center;
        gap: 10px;
    }
    
    .dif-loader-inner span {
        color: #fff;
        font-size: 14px;
        font-weight: 600;
    }
    
    /* ── CSS-only animated ring spinner ── */
    .dif-spinner {
        width: 20px;
        height: 20px;
        border: 3px solid rgba(255, 255, 255, 0.3);
        border-top-color: #fff;
        border-radius: 50%;
        animation: dif-spin 0.7s linear infinite;
        flex-shrink: 0;
    }
    
    @keyframes dif-spin {
        to {
            transform: rotate(360deg);
        }
    }
    
    /* ──────────────────────────────────────────────
   DIFF RESULTS SECTION
   Hidden until a comparison is run (.hidden removed
   by JS).  Contains a stats header and the scrollable
   diff output canvas.
────────────────────────────────────────────── */
    .dif-viewer {
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-top: 10px;
        background: var(--bg-card);
    }
    
    /* ── Results header: stats + action buttons on one line ── */
    .dif-results-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 10px 14px;
        background: var(--bg-input);
        border-bottom: 1px solid var(--border-main);
        flex-wrap: wrap;
        gap: 8px;
    }
    
    /* ── Removed / Added count group ── */
    .dif-result-stats {
        display: flex;
        align-items: center;
        gap: 16px;
        font-size: 13px;
        font-weight: 700;
    }
    
    .dif-stat-removed {
        color: var(--accent-red);
        display: flex;
        align-items: center;
        gap: 5px;
    }
    
    .dif-stat-added {
        color: var(--accent-green);
        display: flex;
        align-items: center;
        gap: 5px;
    }
    
    /* ── Action buttons inside the results header ── */
    .dif-result-actions {
        display: flex;
        align-items: center;
        gap: 6px;
        flex-wrap: wrap;
    }
    
    /* Compact toolbar-button variant used inside results header */
    .dif-result-btn {
        font-size: 11px !important;
        padding: 5px 12px !important;
    }
    
    /* ── Scrollable diff output canvas ── */
    .dif-content {
        overflow: auto;
        font-family: 'Fira Code', 'Courier New', monospace;
        font-size: 12.5px;
        line-height: 1.6;
        max-height: 600px;
    }
    
    /* ──────────────────────────────────────────────
   DIFF ROW LAYOUT
   Split view: each .diff-row contains two .diff-half
   panels side by side, separated by a border.
   Unified view: each .diff-row is a single full-width
   entry showing +/- symbol with highlighted background.
────────────────────────────────────────────── */
    
    /* One row in the diff output */
    .diff-row {
        display: flex;
        border-bottom: 1px solid var(--border-subtle);
    }
    
    /* Half-panel in split view — each occupies 50% */
    .diff-half {
        width: 50%;
        display: flex;
        border-right: 1px solid var(--border-main);
        min-width: 0;
        overflow: hidden;
    }
    
    /* Remove right border from the second half-panel */
    .diff-half:last-child {
        border-right: none;
    }
    
    /* ── Line number gutter ── */
    .line-num {
        min-width: 42px;
        width: 42px;
        padding: 4px 6px;
        text-align: right;
        color: var(--text-muted);
        background: var(--bg-card);
        border-right: 1px solid var(--border-main);
        font-size: 11px;
        user-select: none;
        flex-shrink: 0;
    }
    
    /* ── Code content cell ── */
    .line-code {
        flex: 1;
        padding: 4px 10px;
        white-space: inherit;
        /* Inherits pre / pre-wrap from parent .dif-content */
        overflow: hidden;
        min-width: 0;
    }
    
    /* ── Insertion: green background + text ── */
    .bg-add {
        background: rgba(46, 204, 113, 0.12);
    }
    
    .text-add {
        color: #3fb950;
    }
    
    /* ── Deletion: red background + text ── */
    .bg-rem {
        background: rgba(255, 71, 87, 0.12);
    }
    
    .text-rem {
        color: #ff6b7a;
    }
    
    /* ── Empty placeholder cell (no change on this side in split view) ── */
    .bg-empty {
        background: rgba(255, 255, 255, 0.02);
    }
    
    /* ──────────────────────────────────────────────
   SEO INFO SECTION COMPONENTS
   Custom layout helpers used within the .info-card
   components in the editorial SEO section below
   the tool.
────────────────────────────────────────────── */
    
    /* Flex row for the security info card (text + image) */
    .dif-info-flex {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 30px;
    }
    
    /* Text column inside the info flex row */
    .dif-info-text {
        flex: 1;
        min-width: 280px;
    }
    
    .dif-info-text h2 {
        margin-bottom: 12px;
    }
    
    .dif-info-text p {
        margin-bottom: 10px;
        color: var(--text-muted);
        line-height: 1.7;
    }
    
    /* Image column — fixed width, centered */
    .dif-info-img-wrap {
        flex: 0 0 250px;
        text-align: center;
        margin: 0 auto;
    }
    
    /* Shield illustration image */
    .dif-info-img {
        width: 100%;
        max-width: 250px;
        height: auto;
        filter: drop-shadow(0 0 15px rgba(0, 229, 255, 0.15));
    }
    
    /* ── Icon + Text feature list (no bullets) ── */
    .dif-feature-list {
        list-style: none;
        padding: 0;
        margin-top: 15px;
        display: flex;
        flex-direction: column;
        gap: 10px;
    }
    
    .dif-feature-list li {
        display: flex;
        align-items: center;
        gap: 10px;
        font-size: 13.5px;
        color: var(--text-main);
    }
    
    /* Accent green icon color helper used inside .dif-feature-list */
    .dif-icon-green {
        color: var(--accent-green);
        flex-shrink: 0;
        width: 16px;
        text-align: center;
    }
    
    /* ── 2-column auto-fit grid for developer feature cards ── */
    .dif-feature-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: 20px;
        margin-top: 20px;
    }
    
    .dif-feature-grid p {
        color: var(--text-muted);
        font-size: 13.5px;
        line-height: 1.7;
    }
    
    /* Sub-heading inside feature grid cards */
    .dif-feature-heading {
        color: var(--brand-primary);
        font-size: 15px;
        font-weight: 700;
        margin-bottom: 10px;
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    /* ── How-to-use guide screenshot ── */
    .dif-how-to-img {
        max-width: 100%;
        height: auto;
        border-radius: 10px;
        border: 1px solid var(--border-main);
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
    }
    
    /* ── Styled ordered list for the "How to Use" steps ── */
    .dif-how-to-list {
        margin-left: 20px;
        color: var(--text-muted);
        line-height: 1.9;
        font-size: 13.5px;
    }
    
    .dif-how-to-list li {
        margin-bottom: 6px;
    }
    
    .dif-how-to-list strong {
        color: var(--text-main);
    }
    
}

/* end @media all */


/* ════════════════════════════════════════════════════════════════════════════
   SECTION 65 — TABLET BREAKPOINT (max-width: 600px)
   Editor grid switches to a vertical two-column layout.
   The mid-controls row becomes horizontal.
════════════════════════════════════════════════════════════════════════════ */

@media (max-width: 600px) {
    
    /* Stack the toolbar buttons, allow wrapping on small screens */
    .dif-toolbar {
        padding: 8px 10px;
        gap: 5px;
        border-radius: var(--radius-md);
    }
    
    .dif-tool-btn {
        font-size: 12px;
        padding: 5px 10px;
    }
    
    /* Hide toolbar divider on small screens — saves space */
    .dif-toolbar-divider {
        display: none;
    }
    
    /* Stack editor grid vertically: Original on top, Modified below */
    .dif-editor-grid {
        flex-direction: column;
        gap: 10px;
    }
    
    /* When stacked, mid-controls becomes a horizontal row between editors */
    .dif-mid-controls {
        flex-direction: row;
        justify-content: center;
        gap: 12px;
        padding: 0;
    }
    
    /* Slightly taller editors on tablet for usability */
    .dif-editor-textarea {
        min-height: 180px;
    }
    
    /* Info section: stack image below text */
    .dif-info-flex {
        flex-direction: column;
    }
    
    .dif-info-img-wrap {
        flex: unset;
        width: 100%;
    }
    
    /* Compare button font size reduction */
    .dif-compare-btn {
        font-size: 14px;
        padding: 14px 18px;
    }
    
    /* Results header wraps stat + action buttons on two lines */
    .dif-results-header {
        flex-direction: column;
        align-items: flex-start;
    }
    
    .dif-result-actions {
        width: 100%;
    }
    
}

/* ════════════════════════════════════════════════════════════════════════════
   SECTION 65 — MOBILE BREAKPOINT (max-width: 480px)
   Maximum compactness. Full-width everything.
   Ensure touch targets meet 44px minimum.
════════════════════════════════════════════════════════════════════════════ */

@media (max-width: 480px) {
    
    /* Compact toolbar with tighter font */
    .dif-toolbar {
        padding: 6px 8px;
        gap: 4px;
    }
    
    .dif-tool-btn {
        font-size: 11.5px;
        padding: 4px 9px;
    }
    
    /* Shorter editors on very small screens */
    .dif-editor-textarea {
        min-height: 140px;
        font-size: 12px;
        padding: 10px 10px;
    }
    
    /* Make mid-buttons slightly bigger for touch */
    .dif-mid-btn {
        width: 36px;
        height: 36px;
        font-size: 13px;
    }
    
    /* Compact compare button */
    .dif-compare-btn {
        font-size: 13.5px;
        padding: 13px 14px;
        letter-spacing: 0.8px;
    }
    
    /* Smaller line numbers on mobile */
    .line-num {
        min-width: 32px;
        width: 32px;
        font-size: 10px;
        padding: 3px 4px;
    }
    
    .line-code {
        font-size: 11.5px;
        padding: 3px 7px;
    }
    
    /* Diff content — allow full height scroll */
    .dif-content {
        max-height: 400px;
        font-size: 11.5px;
    }
    
    /* Result stats compact */
    .dif-result-stats {
        gap: 10px;
        font-size: 12px;
    }
    
    .dif-result-btn {
        font-size: 10.5px !important;
        padding: 5px 10px !important;
    }
    
    /* Feature heading smaller */
    .dif-feature-heading {
        font-size: 14px;
    }
    
    /* How-to list slightly smaller */
    .dif-how-to-list {
        font-size: 13px;
        margin-left: 16px;
    }
    
    /* Feature grid: single column on phone */
    .dif-feature-grid {
        grid-template-columns: 1fr;
    }
    
    /* Box header label smaller */
    .dif-box-label {
        font-size: 10px;
    }
    
    .dif-stat-badge {
        font-size: 10px;
    }
    
}

/* #endregion */



















/* #region SECTION 37: TEXTNOVA CORE — TEXT MANIPULATION STUDIO */

/*
 * ════════════════════════════════════════════════════════════════════════════
 *  SECTION 37 — TextNova Core  (prefix: tnc-)
 *  Version : 3.2 — Full-width textarea, sidebar always off-canvas,
 *                  all devices optimised, clean professional UI.
 * ════════════════════════════════════════════════════════════════════════════
 */

/* ════════════════════════════════════════════════════════════════════════════
   BASE — ALL DEVICES
════════════════════════════════════════════════════════════════════════════ */
@media all {
    
    /* ── Hero Title ── */
    .tnc-hero-title-wrap {
        width: 100%;
        max-width: 1200px;
        margin: 20px auto 0;
        padding: 0 20px;
        text-align: center;
    }
    
    /* ── SEO Info Section ── */
    .tnc-info-inner {
        max-width: 900px;
        margin: 0 auto;
        padding: 0 20px;
    }
    
    .tnc-info-img {
        width: 100%;
        max-width: 600px;
        height: auto;
        display: block;
        margin: 16px auto;
        border-radius: var(--radius-md);
        border: 1px solid var(--border-main);
    }
    
    .tnc-info-img-purple {
        border-color: rgba(209, 36, 255, 0.3);
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       APP WRAPPER
    ───────────────────────────────────────────────────────────────────── */
    .tnc-app-wrapper {
        width: 100%;
        max-width: 1400px;
        margin: 20px auto 30px;
        padding: 0 16px;
        box-sizing: border-box;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       APP LAYOUT — Single column, workspace fills everything.
       Sidebar is fixed/overlay; it does NOT affect this layout.
    ───────────────────────────────────────────────────────────────────── */
    .tnc-app-layout {
        display: flex;
        flex-direction: column;
        width: 100%;
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        background: var(--bg-container);
        min-height: 600px;
        overflow: visible;
        /* ← Allow fixed sidebar to escape */
        position: relative;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       SIDEBAR — Fixed overlay, ALWAYS off-screen until .active
    ───────────────────────────────────────────────────────────────────── */
    .tnc-sidebar {
        position: fixed;
        top: 0;
        left: 0;
        height: 100vh;
        width: 270px;
        max-width: 85vw;
        background: var(--bg-card);
        border-right: 1px solid var(--border-main);
        display: flex;
        flex-direction: column;
        z-index: 9999;
        transform: translateX(-100%);
        transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
            box-shadow 0.3s ease;
        box-shadow: none;
        overflow: hidden;
    }
    
    .tnc-sidebar.active {
        transform: translateX(0);
        box-shadow: 8px 0 40px rgba(0, 0, 0, 0.7);
    }
    
    /* Backdrop */
    .tnc-sidebar-backdrop {
        display: none;
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.65);
        z-index: 9998;
    }
    
    .tnc-sidebar-backdrop.active {
        display: block;
    }
    
    /* Sidebar Header */
    .tnc-sidebar-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 16px 18px;
        border-bottom: 1px solid var(--border-main);
        background: rgba(0, 0, 0, 0.3);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 2px;
        color: var(--accent-cyan);
        text-transform: uppercase;
        flex-shrink: 0;
    }
    
    .tnc-sidebar-header span {
        display: flex;
        align-items: center;
        gap: 8px;
    }
    
    /* × Close button */
    .tnc-toggle-btn {
        background: rgba(255, 255, 255, 0.08);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        cursor: pointer;
        font-size: 14px;
        width: 30px;
        height: 30px;
        border-radius: var(--radius-sm);
        display: flex;
        align-items: center;
        justify-content: center;
        transition: var(--transition-base);
        padding: 0;
        flex-shrink: 0;
    }
    
    .tnc-toggle-btn:hover {
        background: var(--brand-primary);
        border-color: var(--brand-primary);
        color: #fff;
    }
    
    /* Scrollable tool list */
    .tnc-tools-scroll {
        overflow-y: auto;
        overflow-x: hidden;
        flex: 1;
        padding: 8px 0 20px;
    }
    
    .tnc-tools-scroll::-webkit-scrollbar {
        width: 3px;
    }
    
    .tnc-tools-scroll::-webkit-scrollbar-thumb {
        background: var(--border-main);
        border-radius: 3px;
    }
    
    .tnc-tools-scroll details {
        border-bottom: 1px solid var(--border-subtle);
    }
    
    /* Accordion summary */
    .tnc-summary {
        list-style: none;
        padding: 12px 18px;
        font-size: 10.5px;
        font-weight: 700;
        letter-spacing: 1.4px;
        text-transform: uppercase;
        color: var(--text-muted);
        cursor: pointer;
        user-select: none;
        display: flex;
        align-items: center;
        gap: 8px;
        transition: background 0.2s, color 0.2s;
    }
    
    .tnc-summary::-webkit-details-marker {
        display: none;
    }
    
    .tnc-summary::before {
        content: '▶';
        font-size: 7px;
        transition: transform 0.2s ease;
        flex-shrink: 0;
        opacity: 0.5;
    }
    
    details[open]>.tnc-summary::before {
        transform: rotate(90deg);
    }
    
    .tnc-summary:hover {
        background: rgba(255, 255, 255, 0.05);
        color: var(--text-main);
    }
    
    /* Tool button grid */
    .tnc-tool-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 6px;
        padding: 6px 14px 14px;
    }
    
    .tnc-tool-btn {
        background: rgba(255, 255, 255, 0.04);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        padding: 10px 6px;
        border-radius: var(--radius-sm);
        font-size: 11px;
        font-weight: 600;
        cursor: pointer;
        transition: var(--transition-base);
        text-align: center;
        line-height: 1.3;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    .tnc-tool-btn:hover {
        background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
        border-color: var(--brand-primary);
        color: #fff;
        transform: translateY(-1px);
        box-shadow: 0 4px 12px rgba(255, 0, 85, 0.3);
    }
    
    .tnc-tool-btn:active {
        transform: scale(0.97);
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       WORKSPACE — fills 100% of the layout at all times
    ───────────────────────────────────────────────────────────────────── */
    .tnc-workspace {
        display: flex;
        flex-direction: column;
        width: 100%;
        flex: 1 1 auto;
        min-height: 600px;
        box-sizing: border-box;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       TOP BAR
    ───────────────────────────────────────────────────────────────────── */
    .tnc-top-bar {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 10px 16px;
        background: rgba(0, 0, 0, 0.22);
        border-bottom: 1px solid var(--border-main);
        min-height: 54px;
        flex-wrap: nowrap;
        position: relative;
        box-sizing: border-box;
        width: 100%;
    }
    
    /* ☰ Icon button */
    .tnc-action-icon-btn {
        background: rgba(255, 255, 255, 0.07);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        width: 38px;
        height: 38px;
        border-radius: var(--radius-sm);
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        font-size: 15px;
        flex-shrink: 0;
        transition: var(--transition-base);
        padding: 0;
    }
    
    .tnc-action-icon-btn:hover {
        background: var(--brand-primary);
        border-color: var(--brand-primary);
        color: #fff;
    }
    
    .tnc-action-primary {
        background: rgba(0, 229, 255, 0.1);
        border-color: var(--accent-cyan);
        color: var(--accent-cyan);
    }
    
    .tnc-action-primary:hover {
        background: var(--accent-cyan);
        color: #000;
    }
    
    .tnc-ml-auto {
        margin-left: auto;
    }
    
    /* Search & Replace panel */
    .tnc-search-box {
        display: flex;
        align-items: center;
        gap: 6px;
        flex: 1 1 0;
        min-width: 0;
    }
    
    .tnc-find-wrap {
        display: flex;
        align-items: center;
        gap: 4px;
        flex: 1 1 0;
        min-width: 0;
    }
    
    .tnc-search-input {
        flex: 1 1 0;
        min-width: 0;
        background: var(--bg-input);
        border: 1px solid var(--border-main);
        color: var(--text-main);
        padding: 8px 12px;
        border-radius: var(--radius-sm);
        font-size: 13px;
        outline: none;
        transition: border-color 0.2s ease;
        font-family: 'JetBrains Mono', monospace;
    }
    
    .tnc-search-input:focus {
        border-color: var(--accent-cyan);
    }
    
    .tnc-search-input::placeholder {
        color: var(--text-muted);
    }
    
    .tnc-match-counter {
        font-size: 10px;
        color: var(--accent-cyan);
        font-weight: 700;
        white-space: nowrap;
        flex-shrink: 0;
        min-width: 30px;
        text-align: center;
    }
    
    .tnc-find-next-btn {
        background: transparent;
        border: none;
        color: var(--text-muted);
        cursor: pointer;
        padding: 6px 8px;
        font-size: 12px;
        border-radius: var(--radius-sm);
        flex-shrink: 0;
        transition: color 0.2s ease;
    }
    
    .tnc-find-next-btn:hover {
        color: var(--accent-cyan);
    }
    
    .tnc-search-divider {
        display: none;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       CONFIG BAR — single scrollable row
    ───────────────────────────────────────────────────────────────────── */
    .tnc-config-bar {
        display: flex;
        align-items: center;
        gap: 20px;
        padding: 8px 16px;
        background: rgba(0, 0, 0, 0.14);
        border-bottom: 1px solid var(--border-subtle);
        flex-wrap: nowrap;
        overflow-x: auto;
        width: 100%;
        box-sizing: border-box;
    }
    
    .tnc-config-bar::-webkit-scrollbar {
        display: none;
    }
    
    .tnc-check-item {
        display: flex;
        align-items: center;
        gap: 6px;
        color: var(--text-muted);
        font-size: 12px;
        font-weight: 600;
        cursor: pointer;
        user-select: none;
        white-space: nowrap;
        flex-shrink: 0;
    }
    
    .tnc-check-item input[type="checkbox"] {
        accent-color: var(--accent-cyan);
        width: 14px;
        height: 14px;
        cursor: pointer;
        flex-shrink: 0;
    }
    
    .tnc-size-label {
        font-family: 'JetBrains Mono', monospace;
        color: var(--accent-cyan);
        font-size: 11px;
        font-weight: 700;
        flex-shrink: 0;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       EDITOR AREA — full width, flex-grow fills remaining space
    ───────────────────────────────────────────────────────────────────── */
    .tnc-editor-area {
        flex: 1 1 auto;
        position: relative;
        display: flex;
        width: 100%;
        min-height: 460px;
        box-sizing: border-box;
    }
    
    /* THE TEXTAREA — fills every pixel of editor-area */
    .tnc-textarea {
        position: absolute;
        /* ← key: fills editor-area completely */
        inset: 0;
        width: 100%;
        height: 100%;
        min-height: 460px;
        background: var(--bg-card);
        color: var(--text-main);
        border: none;
        outline: none;
        padding: 20px 60px 20px 20px;
        /* right padding for FABs */
        font-size: 14px;
        font-family: 'JetBrains Mono', 'Courier New', monospace;
        line-height: 1.8;
        resize: none;
        /* ← no resize handle needed */
        box-sizing: border-box;
        tab-size: 4;
        caret-color: var(--accent-cyan);
    }
    
    .tnc-textarea::placeholder {
        color: rgba(139, 148, 158, 0.45);
        font-style: italic;
        font-size: 13px;
        line-height: 1.75;
    }
    
    .tnc-textarea:focus {
        background: rgba(8, 11, 16, 1);
    }
    
    /* Processing overlay */
    .tnc-processing-overlay {
        position: absolute;
        inset: 0;
        background: rgba(13, 13, 13, 0.78);
        display: none;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 14px;
        z-index: 20;
        backdrop-filter: blur(3px);
    }
    
    .tnc-processing-overlay.active {
        display: flex;
    }
    
    .tnc-spinner {
        width: 38px;
        height: 38px;
        border: 3px solid var(--border-main);
        border-top: 3px solid var(--brand-primary);
        border-radius: 50%;
        animation: tnc-spin 0.75s linear infinite;
    }
    
    @keyframes tnc-spin {
        to {
            transform: rotate(360deg);
        }
    }
    
    .tnc-processing-label {
        font-size: 12px;
        color: var(--text-muted);
        font-family: 'JetBrains Mono', monospace;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       FAB BUTTONS — anchored to right edge of editor-area
    ───────────────────────────────────────────────────────────────────── */
    .tnc-fab-container {
        position: absolute;
        right: 10px;
        top: 14px;
        display: flex;
        flex-direction: column;
        gap: 8px;
        z-index: 15;
    }
    
    .tnc-fab {
        width: 38px;
        height: 38px;
        border-radius: var(--radius-sm);
        background: rgba(22, 27, 34, 0.92);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 15px;
        cursor: pointer;
        transition: var(--transition-base);
        flex-shrink: 0;
        backdrop-filter: blur(6px);
        padding: 0;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    }
    
    .tnc-fab:hover {
        background: var(--brand-secondary);
        border-color: var(--brand-secondary);
        color: #fff;
        transform: scale(1.1);
        box-shadow: 0 4px 16px rgba(10, 189, 227, 0.4);
    }
    
    .tnc-fab-danger {
        color: var(--status-error);
        border-color: rgba(218, 54, 51, 0.4);
    }
    
    .tnc-fab-danger:hover {
        background: var(--status-error);
        border-color: var(--status-error);
        color: #fff;
        box-shadow: 0 4px 16px rgba(218, 54, 51, 0.45);
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       STATUS BAR
    ───────────────────────────────────────────────────────────────────── */
    .tnc-status-bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 8px 16px;
        background: rgba(0, 0, 0, 0.28);
        border-top: 1px solid var(--border-main);
        font-size: 12px;
        font-family: 'JetBrains Mono', monospace;
        flex-shrink: 0;
        gap: 8px;
        width: 100%;
        box-sizing: border-box;
    }
    
    .tnc-stat-group {
        display: flex;
        gap: 20px;
        color: var(--text-muted);
    }
    
    .tnc-stat-group b {
        color: var(--text-main);
    }
    
    .tnc-secure-badge {
        display: flex;
        align-items: center;
        gap: 5px;
        font-size: 11px;
        color: var(--status-text-success);
        font-weight: 700;
        letter-spacing: 0.5px;
    }
    
    /* ─────────────────────────────────────────────────────────────────────
       ANALYSIS MODAL
    ───────────────────────────────────────────────────────────────────── */
    .tnc-modal-content {
        background: var(--bg-container);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-lg);
        padding: 28px;
        max-width: 560px;
        width: calc(100% - 32px);
        position: relative;
        box-shadow: var(--shadow-card);
        animation: fadeInUp 0.3s ease both;
    }
    
    .tnc-modal-close {
        position: absolute;
        top: 14px;
        right: 14px;
        background: rgba(255, 255, 255, 0.07);
        border: 1px solid var(--border-main);
        color: var(--text-muted);
        width: 30px;
        height: 30px;
        border-radius: var(--radius-sm);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 14px;
        transition: var(--transition-base);
        padding: 0;
