    .ung-terminal {
        background: var(--bg-card);
        border: 1px solid var(--border-main);
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-top: 24px;
        min-height: 200px;
        text-align: left;
        font-family: 'JetBrains Mono', 'Courier New', monospace;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       2. TERMINAL TOP BAR
    ────────────────────────────────────────────────────────────────────── */
    .ung-terminal-bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        background: rgba(0, 0, 0, 0.3);
        padding: 10px 16px;
        border-bottom: 1px solid var(--border-main);
        font-size: 13px;
        font-weight: 700;
        color: var(--text-muted);
        gap: 8px;
        flex-wrap: wrap;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       3. STATUS TEXT
    ────────────────────────────────────────────────────────────────────── */
    .ung-status-txt {
        color: var(--accent-cyan);
        margin-left: 8px;
        font-weight: 700;
        font-size: 0.9em;
        white-space: nowrap;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       4. CLEAR BUTTON
    ────────────────────────────────────────────────────────────────────── */
    .ung-clear-btn {
        padding: 6px 14px !important;
        font-size: 12px !important;
        flex-shrink: 0;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       5. EMPTY STATE
    ────────────────────────────────────────────────────────────────────── */
    .ung-empty-state {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 60px 20px;
        gap: 8px;
        color: var(--text-muted);
        font-size: 2rem;
    }
    
    .ung-empty-title {
        font-size: 1.1rem;
        font-weight: 700;
        color: var(--text-muted);
    }
    
    .ung-empty-hint {
        font-size: 0.85rem;
        color: #666;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
