    .ung-loader-wrap {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 80px 20px;
        gap: 16px;
    }
    
    .ung-loader-icon {
        font-size: 34px;
        color: var(--brand-primary);
    }
    
    .ung-loader-label {
        font-size: 13px;
        color: var(--text-muted);
        font-family: 'JetBrains Mono', monospace;
        margin: 0;
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       7. ERROR STATE
    ────────────────────────────────────────────────────────────────────── */
    .ung-error-state {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 50px 20px;
        gap: 10px;
        color: var(--status-error);
        font-size: 2rem;
        text-align: center;
    }
    
    .ung-error-title {
        font-size: 1rem;
        font-weight: 700;
        color: var(--status-error);
    }
    
    .ung-error-detail {
        font-size: 0.8rem;
        color: var(--text-muted);
    }
    
    /* ──────────────────────────────────────────────────────────────────────
       8. RESULT LIST WRAPPER
