    ────────────────────────────────────────────────────────────────────── */
    .ung-result-row {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 11px 16px;
        border-bottom: 1px solid var(--border-subtle);
        transition: background var(--transition-base);
        flex-wrap: nowrap;
    }
    
    .ung-result-row:last-child {
        border-bottom: none;
    }
    
    .ung-result-row:hover {
        background: rgba(255, 255, 255, 0.03);
