        display: grid;
        grid-template-columns: 22px 1.4em 1fr auto;
        grid-template-rows: auto auto;
        column-gap: 8px;
        row-gap: 4px;
        padding: 10px 12px;
        align-items: center;
    }
    
    /* Index: row 1, col 1 */
    .ung-result-index {
        grid-column: 1 / 2;
        grid-row: 1 / 2;
        font-size: 10px;
        min-width: auto;
        text-align: center;
    }
    
    /* Flag: row 1, col 2 */
    .ung-result-flag {
        grid-column: 2 / 3;
        grid-row: 1 / 2;
        font-size: 1.2em;
    }
    
    /* Name: row 1, col 3 — takes main content column */
    .ung-result-name {
        grid-column: 3 / 4;
        grid-row: 1 / 2;
        flex: unset;
        font-size: 13px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    /* Actions: row 1, col 4 — spans both rows on the right */
    .ung-result-actions {
        grid-column: 4 / 5;
        grid-row: 1 / 3;
        flex-direction: column;
        gap: 5px;
        margin-left: 0;
        align-self: center;
    }
    
    /* Meta: row 2, col 2–3 (spans flag + name columns) */
    .ung-result-meta {
        grid-column: 2 / 4;
        grid-row: 2 / 3;
        gap: 8px;
        flex: unset;
        overflow: hidden;
    }
    
    .ung-result-email {
        font-size: 11.5px;
        flex: 1 1 0;
        min-width: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    
    .ung-result-gender {
        display: none;
        /* Hidden on mobile — saves space */
    }
    
    .ung-result-age {
        font-size: 11px;
        flex-shrink: 0;
    }
    
    /* Copy buttons: compact square */
    .ung-copy-btn {
        width: 28px;
        height: 28px;
        font-size: 11px;
    }
    
    /* Feature grid */
    .ung-feature-grid {
        grid-template-columns: 1fr;
        gap: 14px;
    }
    
    /* Empty / loader */
    .ung-loader-wrap {
        padding: 40px 12px;
    }
    
    .ung-empty-state {
        padding: 30px 12px;
        font-size: 1.6rem;
    }
    
    .ung-empty-title {
        font-size: 1rem;
    }
    
}


/* ════════════════════════════════════════════════════════════════════════════
   MOBILE — max-width: 480px
   Portrait phone (standard). Email truncates, index hidden.
════════════════════════════════════════════════════════════════════════════ */
@media (max-width: 480px) {
    
    .ung-terminal {
        border-radius: var(--radius-sm);
        margin-top: 16px;
    }
    
    /* Hide row index — save column space */
    .ung-result-index {
        display: none;
    }
    
    /* Adjust grid: no index column */
    .ung-result-row {
        grid-template-columns: 1.3em 1fr auto;
        column-gap: 8px;
        padding: 10px 12px;
    }
    
    .ung-result-flag {
        grid-column: 1 / 2;
        grid-row: 1 / 2;
    }
    
    .ung-result-name {
        grid-column: 2 / 3;
        grid-row: 1 / 2;
        font-size: 12.5px;
    }
    
    .ung-result-actions {
        grid-column: 3 / 4;
        grid-row: 1 / 3;
    }
    
    .ung-result-meta {
        grid-column: 1 / 3;
        grid-row: 2 / 3;
    }
    
    .ung-result-email {
        font-size: 11px;
    }
    
    .ung-result-age {
        font-size: 11px;
    }
    
    .ung-copy-btn {
        width: 26px;
        height: 26px;
        font-size: 10px;
    }
    
    .ung-loader-icon {
        font-size: 28px;
    }
    
    .ung-loader-wrap {
        padding: 36px 12px;
    }
    
    .ung-feature-grid {
        gap: 12px;
    }
    
    .ung-empty-state {
        padding: 28px 10px;
        font-size: 1.4rem;
    }
    
}


/* ════════════════════════════════════════════════════════════════════════════
   EXTRA SMALL — max-width: 360px
   Very small phones (Galaxy A-series, older iPhones).
════════════════════════════════════════════════════════════════════════════ */
@media (max-width: 360px) {
    
    .ung-result-row {
        column-gap: 6px;
        padding: 8px 10px;
    }
    
    .ung-result-name {
        font-size: 12px;
    }
    
    .ung-result-email {
        font-size: 10.5px;
    }
    
    .ung-result-age {
        font-size: 10.5px;
    }
    
    .ung-copy-btn {
        width: 24px;
        height: 24px;
        font-size: 10px;
    }
    
    .ung-terminal-bar {
        padding: 7px 10px;
        font-size: 10.5px;
    }
    
    .ung-clear-btn {
        padding: 4px 8px !important;
        font-size: 10px !important;
    }
    
}

/* #endregion */













/*
 * =============================================================================
 *  TRUSTED TOOLS WEB — textpro-max.css
 *  Tool-Specific Stylesheet for TextPro Max Studio
 *  Author  : MD KAWSAR
 *  Version : 1.0
 *  Scope   : fancy-text-generator.html ONLY
 *            All classes use "tpm-" prefix to avoid collision with
 *            tools-template.css — zero overrides guaranteed.
 * =============================================================================
 *
 *  TABLE OF CONTENTS
 *  ─────────────────────────────────────────────────────────────────────────
 *  SECTION 1  : Sidebar Drawer & Overlay
 *  SECTION 2  : Editor Wrapper & Controls
 *  SECTION 3  : Main Textarea
 *  SECTION 4  : Find & Replace Bar
 *  SECTION 5  : Action Toolbar (Scrollable Buttons)
 *  SECTION 6  : Utility Chips
 *  SECTION 7  : Navigation Tabs
 *  SECTION 8  : Content Area Panels
 *  SECTION 9  : Card Components
 *  SECTION 10 : Grid List (Font & Decor Output)
 *  SECTION 11 : Mini Buttons
 *  SECTION 12 : Modal Overlay (Image Studio & Symbol Picker)
 *  SECTION 13 : Image Studio Internals
 *  SECTION 14 : Symbol Grid
 *  SECTION 15 : Feature Image Grid & Boxes
 *  SECTION 16 : Responsive — Tablet, Mobile, Small
 * =============================================================================
 */


/* ─────────────────────────────────────────────────────────────────────────────
   NOTE ON THEMING
   This file relies 100% on the CSS variables already declared in
   tools-template.css (:root dark defaults + body.light-mode overrides).
   No variable is redeclared here. Adding this file after tools-template.css
   is all that is required for full dark/light mode support.
───────────────────────────────────────────────────────────────────────────── */


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 1 — Sidebar Drawer & Overlay
   Left-side panel that lists saved drafts. Slides in from the left edge.
═════════════════════════════════════════════════════════════════════════════ */

/* Dark backdrop behind open sidebar */
.tpm-sidebar-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.55);
    z-index: 998;
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
}

.tpm-sidebar-overlay.active {
    display: block;
}

/* Sidebar drawer panel */
.tpm-sidebar {
    position: fixed;
    top: 0;
    left: 0;
    height: 100%;
    width: 280px;
    background: var(--bg-container);
    border-right: 1px solid var(--border-main);
    z-index: 999;
    padding: 0;
    display: flex;
    flex-direction: column;
    transform: translateX(-100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 4px 0 30px rgba(0, 0, 0, 0.35);
}

.tpm-sidebar.open {
    transform: translateX(0);
}

/* Sidebar top header row */
.tpm-sidebar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px;
    border-bottom: 1px solid var(--border-main);
    background: var(--bg-card);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    flex-shrink: 0;
}

/* "New Draft" full-width button inside sidebar */
.tpm-sidebar-new-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    width: calc(100% - 32px);
    margin: 14px 16px 10px;
    padding: 10px 0;
    border-radius: var(--radius-pill);
    background: var(--brand-primary);
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    border: none;
    cursor: pointer;
    transition: var(--transition-base);
    flex-shrink: 0;
}

.tpm-sidebar-new-btn:hover {
    background: var(--brand-primary-hover);
    transform: translateY(-1px);
}

/* Scrollable draft list area */
.tpm-draft-list {
    flex: 1;
    overflow-y: auto;
    padding: 6px 12px 20px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

/* Scrollbar styling for sidebar list */
.tpm-draft-list::-webkit-scrollbar {
    width: 4px;
}
.tpm-draft-list::-webkit-scrollbar-track {
    background: transparent;
}
.tpm-draft-list::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 4px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 2 — Editor Wrapper & Controls
═════════════════════════════════════════════════════════════════════════════ */

/* Outer wrapper: gives the editor its bordered card look */
.tpm-editor-wrapper {
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    overflow: hidden;
    background: var(--bg-card);
    margin-bottom: 14px;
}

/* Top control bar: stat counter left + icon buttons right */
.tpm-editor-controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 14px;
    background: var(--bg-body);
    border-bottom: 1px solid var(--border-main);
    gap: 10px;
    flex-wrap: wrap;
}

/* "3 CHARS / 1 WORDS" stat text */
.tpm-stat-text {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.8px;
    color: var(--text-muted);
    font-family: 'Courier New', monospace;
    white-space: nowrap;
}

/* Group of icon buttons on the right side of the control bar */
.tpm-control-btns {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 3 — Main Textarea
═════════════════════════════════════════════════════════════════════════════ */

.tpm-textarea {
    width: 100%;
    min-height: 180px;
    resize: vertical;
    padding: 16px;
    background: var(--bg-card);
    color: var(--text-main);
    border: none;
    outline: none;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    font-size: 15px;
    line-height: 1.7;
    display: block;
    box-sizing: border-box;
    transition: background 0.2s ease;
    color-scheme: var(--input-scheme);
}

.tpm-textarea::placeholder {
    color: var(--text-muted);
    opacity: 0.7;
}

.tpm-textarea:focus {
    background: var(--bg-input);
}

/* Scrollbar inside textarea */
.tpm-textarea::-webkit-scrollbar {
    width: 5px;
}
.tpm-textarea::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 4px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 4 — Find & Replace Bar
═════════════════════════════════════════════════════════════════════════════ */

.tpm-find-replace-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    background: var(--bg-body);
    border-top: 1px solid var(--border-main);
    flex-wrap: wrap;
}

/* Text inputs inside find/replace bar */
.tpm-fr-input {
    flex: 1;
    min-width: 100px;
    padding: 7px 12px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-main);
    background: var(--bg-input);
    color: var(--text-main);
    font-size: 13px;
    outline: none;
    transition: border-color 0.2s ease;
    color-scheme: var(--input-scheme);
}

.tpm-fr-input:focus {
    border-color: var(--brand-primary);
}

/* "GO" action button — inherits .btn .btn-primary from tools-template.css */
.tpm-fr-go-btn {
    flex-shrink: 0;
    padding: 7px 20px;
    font-size: 12px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 5 — Action Toolbar (Scrollable Buttons)
═════════════════════════════════════════════════════════════════════════════ */

/* Horizontally scrollable row of tool buttons */
.tpm-toolbar-scroll {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 7px;
    padding: 12px 2px;
    margin-bottom: 12px;
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none; /* IE */
}

.tpm-toolbar-scroll::-webkit-scrollbar {
    display: none;
}

/* Individual toolbar button */
.tpm-tool-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    border-radius: var(--radius-pill);
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    border: 1px solid var(--border-main);
    background: var(--bg-card);
    color: var(--text-main);
    white-space: nowrap;
    flex-shrink: 0;
    transition: var(--transition-base);
    outline: none;
}

.tpm-tool-btn:hover {
    border-color: var(--brand-secondary);
    color: var(--brand-secondary);
    background: rgba(10, 189, 227, 0.08);
    transform: translateY(-1px);
}

.tpm-tool-btn:active {
    transform: scale(0.96);
}

/* Primary highlight variant */
.tpm-tool-btn--primary {
    background: linear-gradient(135deg, var(--brand-primary), #c0006b);
    color: #fff;
    border-color: transparent;
}

.tpm-tool-btn--primary:hover {
    color: #fff;
    opacity: 0.88;
    border-color: transparent;
    background: linear-gradient(135deg, var(--brand-primary), #c0006b);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 6 — Utility Chips
   One-tap text transformation shortcuts (UPPERCASE, Title Case, etc.)
═════════════════════════════════════════════════════════════════════════════ */

.tpm-utility-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
    justify-content: center;
    margin-bottom: 16px;
}

/* Single chip pill */
.tpm-chip {
    padding: 6px 14px;
    border-radius: var(--radius-pill);
    border: 1px solid var(--border-main);
    background: var(--bg-card);
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    user-select: none;
    transition: var(--transition-base);
    white-space: nowrap;
}

.tpm-chip:hover {
    border-color: var(--accent-cyan);
    color: var(--accent-cyan);
    background: rgba(0, 229, 255, 0.07);
    transform: translateY(-1px);
}

.tpm-chip:active {
    transform: scale(0.95);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 7 — Navigation Tabs
   Switches between Fancy Fonts / Repeater / Glitch / etc.
═════════════════════════════════════════════════════════════════════════════ */

.tpm-tabs {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 6px;
    border-bottom: 1px solid var(--border-main);
    margin-bottom: 20px;
    padding-bottom: 0;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.tpm-tabs::-webkit-scrollbar {
    display: none;
}

/* Individual tab button */
.tpm-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 16px;
    border-radius: var(--radius-md) var(--radius-md) 0 0;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    border: 1px solid transparent;
    border-bottom: none;
    background: transparent;
    color: var(--text-muted);
    white-space: nowrap;
    flex-shrink: 0;
    transition: var(--transition-base);
    outline: none;
    position: relative;
    bottom: -1px; /* sits flush on the border line */
}

.tpm-tab:hover {
    color: var(--text-main);
    background: var(--bg-card);
}

/* Active tab */
.tpm-tab.active {
    color: var(--brand-primary);
    background: var(--bg-card);
    border-color: var(--border-main);
    border-bottom-color: var(--bg-card);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 8 — Content Area Panels
   Each tab panel; hidden by default, shown when .active.
═════════════════════════════════════════════════════════════════════════════ */

.tpm-content-area {
    display: none;
    animation: fadeInUp 0.35s ease forwards;
}

.tpm-content-area.active {
    display: block;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 9 — Card Components
   Used for output results, settings blocks, glitch output, etc.
═════════════════════════════════════════════════════════════════════════════ */

.tpm-card {
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    padding: 16px;
    margin-bottom: 14px;
    text-align: left;
    position: relative;
    transition: border-color 0.2s ease;
}

/* Clickable card — shows pointer and highlights on hover */
.tpm-card--clickable {
    cursor: pointer;
}

.tpm-card--clickable:hover {
    border-color: var(--accent-cyan);
    box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.08);
}

/* Card label / heading */
.tpm-card-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 10px;
}

/* Card body text / output content */
.tpm-card-text {
    font-size: 15px;
    line-height: 1.7;
    color: var(--text-main);
    word-break: break-word;
    white-space: pre-wrap;
    min-height: 40px;
}

/* Scrollable variant for long repeater output */
.tpm-card-text--scroll {
    max-height: 200px;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--border-main) transparent;
}

.tpm-card-text--scroll::-webkit-scrollbar {
    width: 4px;
}
.tpm-card-text--scroll::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 4px;
}

/* Stack of inputs inside a card */
.tpm-card-inner-stack {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* "Tap to Copy" hint shown at card bottom */
.tpm-copy-hint {
    margin-top: 10px;
    font-size: 11px;
    color: var(--accent-cyan);
    font-weight: 600;
    letter-spacing: 0.4px;
    display: flex;
    align-items: center;
    gap: 4px;
}

.tpm-copy-hint::before {
    content: "\f0c5";
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
    font-size: 10px;
    opacity: 0.8;
}

/* pre-formatted text inside card (ASCII art output) */
.tpm-pre-text {
    font-family: 'Courier New', monospace;
    font-size: 12px;
    white-space: pre;
    overflow-x: auto;
    line-height: 1.4;
    color: var(--text-main);
    scrollbar-width: thin;
    scrollbar-color: var(--border-main) transparent;
}

.tpm-pre-text::-webkit-scrollbar {
    height: 4px;
}
.tpm-pre-text::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 4px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 10 — Grid List (Font Cards & Decoration Cards)
   Renders each fancy-font variant or decoration as a tappable card.
═════════════════════════════════════════════════════════════════════════════ */

/* Responsive auto-fill grid */
.tpm-grid-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 12px;
    padding-bottom: 6px;
}

/* Each cell injected by JS renderFonts() / renderDecor() should use this
   class. If JS generates plain divs, the grid layout still applies. */
.tpm-grid-list > * {
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    padding: 14px;
    cursor: pointer;
    transition: var(--transition-base);
    text-align: left;
    word-break: break-word;
}

.tpm-grid-list > *:hover {
    border-color: var(--brand-primary);
    box-shadow: 0 0 0 2px rgba(255, 0, 85, 0.08);
    transform: translateY(-2px);
}

.tpm-grid-list > *:active {
    transform: scale(0.97);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 11 — Mini Buttons
   Small icon buttons used in editor controls, sidebar header, modal header.
═════════════════════════════════════════════════════════════════════════════ */

.tpm-mini-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-main);
    background: var(--bg-card);
    color: var(--text-muted);
    font-size: 13px;
    cursor: pointer;
    transition: var(--transition-base);
    outline: none;
    flex-shrink: 0;
}

.tpm-mini-btn:hover {
    border-color: var(--brand-secondary);
    color: var(--brand-secondary);
    background: rgba(10, 189, 227, 0.08);
}

.tpm-mini-btn:active {
    transform: scale(0.92);
}

/* Accent (image studio) variant */
.tpm-mini-btn--accent {
    border-color: var(--accent-purple);
    color: var(--accent-purple);
}

.tpm-mini-btn--accent:hover {
    background: rgba(209, 36, 255, 0.1);
    border-color: var(--accent-purple);
    color: var(--accent-purple);
}

/* Danger (clear/delete) variant */
.tpm-mini-btn--danger {
    border-color: var(--accent-red);
    color: var(--accent-red);
}

.tpm-mini-btn--danger:hover {
    background: rgba(255, 71, 87, 0.1);
    border-color: var(--accent-red);
    color: var(--accent-red);
}

/* Purple (search) variant */
.tpm-mini-btn--purple {
    border-color: var(--accent-purple);
    color: var(--accent-purple);
    width: auto;
    padding: 0 14px;
    font-size: 12px;
    height: 36px;
    gap: 6px;
}

.tpm-mini-btn--purple:hover {
    background: rgba(209, 36, 255, 0.1);
    border-color: var(--accent-purple);
    color: var(--accent-purple);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 12 — Modal Overlay
   Full-screen backdrop for Image Studio and Symbol Picker.
   Uses the existing .modal-overlay base (declared in tools-template.css)
   combined with tpm-specific inner box styles.
═════════════════════════════════════════════════════════════════════════════ */

/* Main modal content box */
.tpm-modal-box {
    background: var(--bg-container);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-lg);
    width: 100%;
    max-width: 680px;
    max-height: 90vh;
    overflow-y: auto;
    padding: 24px;
    position: relative;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    display: flex;
    flex-direction: column;
    gap: 16px;
    scrollbar-width: thin;
    scrollbar-color: var(--border-main) transparent;
}

.tpm-modal-box::-webkit-scrollbar {
    width: 5px;
}
.tpm-modal-box::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 5px;
}

/* Small variant for symbol picker */
.tpm-modal-box--sm {
    max-width: 420px;
}

/* Modal top row: title left + close button right */
.tpm-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    flex-shrink: 0;
}

/* Modal title text */
.tpm-modal-title {
    font-size: 17px;
    font-weight: 700;
    color: var(--text-main);
    display: flex;
    align-items: center;
    gap: 8px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 13 — Image Studio Internals
   Canvas preview, form fields, Unsplash search, gradient row, color pickers.
═════════════════════════════════════════════════════════════════════════════ */

/* Canvas preview wrapper */
.tpm-canvas-wrap {
    width: 100%;
    border-radius: var(--radius-md);
    overflow: hidden;
    border: 1px solid var(--border-main);
    background: #09090b;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 160px;
}

.tpm-canvas-wrap canvas {
    display: block;
    max-width: 100%;
    height: auto;
}

/* 2-column form grid */
.tpm-modal-grid {
    display: grid;
    gap: 12px;
}

.tpm-modal-grid--2col {
    grid-template-columns: 1fr 1fr;
}

.tpm-modal-grid--3col {
    grid-template-columns: 1fr 1fr 1fr;
}

/* Single field wrapper */
.tpm-modal-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

/* Field label */
.tpm-modal-label {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--text-muted);
}

/* Caps/uppercase label variant */
.tpm-modal-label--caps {
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-size: 11px;
}

/* Number size input (short width) */
.tpm-size-input {
    max-width: 90px;
}

/* Color picker input */
.tpm-color-picker {
    width: 40px;
    height: 36px;
    padding: 2px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-main);
    background: var(--bg-input);
    cursor: pointer;
    outline: none;
    transition: border-color 0.2s ease;
}

.tpm-color-picker:hover {
    border-color: var(--accent-cyan);
}

/* Wide color picker (gradient row) */
.tpm-color-picker--wide {
    width: 100%;
    height: 42px;
    flex: 1;
}

/* Gradient row: two color pickers side by side */
.tpm-gradient-row {
    display: flex;
    gap: 10px;
    align-items: center;
}

/* ── Unsplash search section ── */
.tpm-unsplash-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

/* Search input + button row */
.tpm-unsplash-row {
    display: flex;
    gap: 8px;
    align-items: center;
}

.tpm-unsplash-input {
    flex: 1;
}

/* Results thumbnail grid */
.tpm-unsplash-results {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    min-height: 48px;
    padding: 6px 0;
}

/* Hint text before any search */
.tpm-unsplash-hint {
    font-size: 12px;
    color: var(--text-muted);
    font-style: italic;
    width: 100%;
    text-align: center;
    padding: 10px 0;
}

/* Each Unsplash result thumbnail injected by JS */
.tpm-unsplash-results img {
    width: 80px;
    height: 55px;
    object-fit: cover;
    border-radius: var(--radius-sm);
    cursor: pointer;
    border: 2px solid transparent;
    transition: var(--transition-base);
}

.tpm-unsplash-results img:hover,
.tpm-unsplash-results img.selected {
    border-color: var(--accent-cyan);
    transform: scale(1.05);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 14 — Symbol Grid
   Grid of tappable Unicode symbols inside the symbol picker modal.
═════════════════════════════════════════════════════════════════════════════ */

.tpm-symbol-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(38px, 1fr));
    gap: 6px;
    max-height: 300px;
    overflow-y: auto;
    padding: 4px 2px;
    scrollbar-width: thin;
    scrollbar-color: var(--border-main) transparent;
}

.tpm-symbol-grid::-webkit-scrollbar {
    width: 4px;
}
.tpm-symbol-grid::-webkit-scrollbar-thumb {
    background: var(--border-main);
    border-radius: 4px;
}

/* Each symbol cell injected by JS */
.tpm-symbol-grid > * {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    font-size: 18px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-main);
    background: var(--bg-card);
    cursor: pointer;
    transition: var(--transition-base);
    user-select: none;
}

.tpm-symbol-grid > *:hover {
    border-color: var(--accent-cyan);
    background: rgba(0, 229, 255, 0.08);
    transform: scale(1.1);
}

.tpm-symbol-grid > *:active {
    transform: scale(0.93);
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 15 — Feature Image Grid & Boxes (SEO Content Section)
═════════════════════════════════════════════════════════════════════════════ */

/* Two-column feature image showcase */
.tpm-feature-img-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin: 16px 0;
}

/* Feature box: card with optional text */
.tpm-feature-box {
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    padding: 16px;
    transition: var(--transition-base);
}

.tpm-feature-box:hover {
    border-color: var(--border-subtle);
    box-shadow: var(--shadow-soft);
}

/* Centered variant (image + caption centered) */
.tpm-feature-box--center {
    text-align: center;
}

.tpm-feature-box--center h3 {
    font-size: 14px;
    margin-top: 10px;
    color: var(--text-main);
}

.tpm-feature-box--center p {
    font-size: 13px;
    color: var(--text-muted);
    margin-top: 4px;
}

/* Feature image inside box */
.tpm-feature-img {
    width: 100%;
    height: 140px;
    object-fit: cover;
    border-radius: var(--radius-sm);
    display: block;
}

/* 3-column use-case feature grid */
.tpm-feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-top: 14px;
}

.tpm-feature-grid .tpm-feature-box {
    font-size: 13px;
    line-height: 1.6;
}

.tpm-feature-grid .tpm-feature-box p {
    color: var(--text-muted);
    margin-top: 6px;
    font-size: 13px;
}


/* ═════════════════════════════════════════════════════════════════════════════
   SECTION 16 — Responsive Breakpoints
═════════════════════════════════════════════════════════════════════════════ */

/* ── TABLET (≤ 768px) ─────────────────────────────────────────────────── */
@media (max-width: 768px) {

    .tpm-modal-grid--3col {
        grid-template-columns: 1fr 1fr;
    }

    .tpm-feature-img-grid {
        grid-template-columns: 1fr;
    }

    .tpm-modal-box {
        padding: 18px;
        max-height: 92vh;
    }

    .tpm-grid-list {
        grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    }

}

/* ── LARGE PHONE (≤ 600px) ────────────────────────────────────────────── */
@media (max-width: 600px) {

    .tpm-sidebar {
        width: 260px;
    }

    .tpm-tabs {
        gap: 4px;
    }

    .tpm-tab {
        padding: 8px 12px;
        font-size: 12px;
    }

    .tpm-editor-controls {
        padding: 7px 12px;
    }

    .tpm-textarea {
        font-size: 14px;
        min-height: 150px;
        padding: 14px;
    }

    .tpm-modal-grid--2col,
    .tpm-modal-grid--3col {
        grid-template-columns: 1fr;
    }

    .tpm-gradient-row {
        flex-direction: column;
    }

    .tpm-color-picker--wide {
        height: 40px;
    }

    .tpm-grid-list {
        grid-template-columns: 1fr 1fr;
        gap: 9px;
    }

    .tpm-feature-grid {
        grid-template-columns: 1fr;
    }

    .tpm-tool-btn {
        padding: 7px 13px;
        font-size: 12px;
    }

    .tpm-chip {
        padding: 5px 12px;
        font-size: 11.5px;
    }

}

/* ── MOBILE (≤ 480px) ─────────────────────────────────────────────────── */
@media (max-width: 480px) {

    .tpm-sidebar {
        width: 240px;
    }

    .tpm-modal-box {
        padding: 14px;
        border-radius: var(--radius-md);
    }

    .tpm-modal-title {
        font-size: 15px;
    }

    .tpm-canvas-wrap {
        min-height: 120px;
    }

    .tpm-grid-list {
        grid-template-columns: 1fr;
    }

    .tpm-feature-img {
        height: 120px;
    }

    .tpm-symbol-grid {
        grid-template-columns: repeat(auto-fill, minmax(34px, 1fr));
    }

    .tpm-symbol-grid > * {
        width: 34px;
        height: 34px;
        font-size: 16px;
    }

    .tpm-tab {
        padding: 7px 10px;
        font-size: 11.5px;
        gap: 4px;
    }

    .tpm-tab i {
        display: none;
    }

    .tpm-fr-input {
        font-size: 12px;
    }

    .tpm-card {
        padding: 12px;
    }

    .tpm-card-text {
        font-size: 14px;
    }

    .tpm-mini-btn {
        width: 30px;
        height: 30px;
        font-size: 12px;
    }

    .tpm-unsplash-results img {
        width: 68px;
        height: 48px;
    }

}

/* ── EXTRA SMALL (≤ 360px) ────────────────────────────────────────────── */
@media (max-width: 360px) {

    .tpm-sidebar {
        width: 220px;
    }

    .tpm-tab {
        padding: 6px 9px;
        font-size: 11px;
    }

    .tpm-tool-btn {
        padding: 6px 11px;
        font-size: 11px;
    }

    .tpm-chip {
        padding: 4px 10px;
        font-size: 11px;
    }

    .tpm-grid-list > * {
        padding: 12px;
        font-size: 13px;
    }

    .tpm-modal-box {
        padding: 12px;
    }

}






















        /* ─────────────────────────────────────────────────────────
           CV BUILDER — ROOT LAYOUT
           The main builder area uses a two-column split:
           Left = Input Form | Right = Live Resume Preview
           On mobile (≤ 900px) they stack vertically.
           ───────────────────────────────────────────────────────── */

        /* Override container max-width for this wide tool */
        .cvb-wrapper {
            max-width: 1300px;
            width: 100%;
            margin: 0 auto;
        }

        /* Hero section uses text-align: center from .container,
           but the builder itself needs left-aligned layouts. */
        .cvb-hero {
            text-align: center;
            margin-bottom: 24px;
        }

        /* ── SPLIT SCREEN LAYOUT ── */
        .cvb-split {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            align-items: start;
        }

        /* Left panel — the input form */
        .cvb-form-panel {
            background: var(--bg-card);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-lg);
            overflow: hidden;
            position: sticky;
            top: 80px; /* stick below fixed global header */
            max-height: calc(100vh - 100px);
            display: flex;
            flex-direction: column;
        }

        /* Right panel — the live preview */
        .cvb-preview-panel {
            background: var(--bg-card);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-lg);
            overflow: hidden;
        }

        /* ── PANEL HEADERS ── */
        .cvb-panel-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 14px 18px;
            background: var(--bg-container);
            border-bottom: 1px solid var(--border-main);
            flex-shrink: 0;
        }

        .cvb-panel-title {
            font-size: 13px;
            font-weight: 700;
            color: var(--text-main);
            display: flex;
            align-items: center;
            gap: 7px;
            letter-spacing: 0.3px;
            text-transform: uppercase;
        }

        .cvb-panel-title i {
            color: var(--accent-cyan);
            font-size: 14px;
        }

        /* Small action buttons in panel header */
        .cvb-panel-actions {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
        }

        .cvb-icon-btn {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            padding: 6px 12px;
            border-radius: var(--radius-pill);
            font-size: 11px;
            font-weight: 700;
            cursor: pointer;
            border: 1px solid var(--border-main);
            background: var(--bg-input);
            color: var(--text-main);
            transition: var(--transition-base);
            white-space: nowrap;
            letter-spacing: 0.2px;
        }

        .cvb-icon-btn:hover {
            border-color: var(--accent-cyan);
            color: var(--accent-cyan);
            background: rgba(0, 229, 255, 0.06);
        }

        .cvb-icon-btn.btn-danger:hover {
            border-color: var(--accent-red);
            color: var(--accent-red);
            background: rgba(255, 71, 87, 0.06);
        }

        /* ── FORM SCROLL AREA ── */
        .cvb-form-scroll {
            overflow-y: auto;
            flex: 1;
            padding: 16px;
            scrollbar-width: thin;
            scrollbar-color: var(--border-main) transparent;
        }

        .cvb-form-scroll::-webkit-scrollbar {
            width: 4px;
        }

        .cvb-form-scroll::-webkit-scrollbar-thumb {
            background: var(--border-main);
            border-radius: 4px;
        }

        /* ── ACCORDION / SECTION TABS ── */
        .cvb-section {
            margin-bottom: 10px;
            border: 1px solid var(--border-main);
            border-radius: var(--radius-md);
            overflow: hidden;
        }

        .cvb-section-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 11px 14px;
            cursor: pointer;
            background: var(--bg-container);
            user-select: none;
            transition: var(--transition-base);
        }

        .cvb-section-header:hover {
            background: rgba(0, 229, 255, 0.04);
        }

        .cvb-section-header-left {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 13px;
            font-weight: 700;
            color: var(--text-main);
        }

        .cvb-section-header-left i {
            color: var(--accent-cyan);
            width: 16px;
            text-align: center;
        }

        .cvb-section-chevron {
            font-size: 11px;
            color: var(--text-muted);
            transition: transform 0.3s ease;
        }

        /* When section is open, rotate chevron */
        .cvb-section.is-open .cvb-section-chevron {
            transform: rotate(180deg);
        }

        .cvb-section-body {
            display: none;
            padding: 14px;
            border-top: 1px solid var(--border-main);
            background: var(--bg-card);
        }

        .cvb-section.is-open .cvb-section-body {
            display: block;
        }

        /* ── FORM FIELDS ── */
        .cvb-field-group {
            margin-bottom: 12px;
        }

        .cvb-label {
            display: block;
            font-size: 11px;
            font-weight: 700;
            color: var(--text-muted);
            margin-bottom: 5px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .cvb-input,
        .cvb-textarea {
            width: 100%;
            padding: 9px 12px;
            background: var(--bg-input);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-sm);
            color: var(--text-main);
            font-size: 13px;
            font-family: inherit;
            transition: var(--transition-base);
            outline: none;
        }

        .cvb-input:focus,
        .cvb-textarea:focus {
            border-color: var(--accent-cyan);
            box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.1);
        }

        .cvb-textarea {
            min-height: 80px;
            resize: vertical;
            line-height: 1.5;
        }

        /* Two-column field row */
        .cvb-field-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }

        /* ── REPEATABLE ITEMS (Experience, Education, etc.) ── */
        /* Each repeatable item is a card with a drag handle */
        .cvb-repeat-item {
            background: var(--bg-container);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-md);
            margin-bottom: 10px;
            overflow: hidden;
            cursor: default;
        }

        /* Drag handle bar at top of each item */
        .cvb-item-handle {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 9px 12px;
            background: rgba(0, 229, 255, 0.03);
            border-bottom: 1px solid var(--border-main);
            cursor: grab;
        }

        .cvb-item-handle:active {
            cursor: grabbing;
        }

        .cvb-drag-icon {
            color: var(--text-muted);
            font-size: 12px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .cvb-drag-icon span {
            font-size: 11px;
            font-weight: 600;
            color: var(--text-muted);
        }

        /* Delete button inside item handle */
        .cvb-delete-item-btn {
            background: none;
            border: none;
            color: var(--text-muted);
            cursor: pointer;
            padding: 3px 6px;
            border-radius: var(--radius-sm);
            font-size: 12px;
            transition: var(--transition-base);
        }

        .cvb-delete-item-btn:hover {
            color: var(--accent-red);
            background: rgba(255, 71, 87, 0.1);
        }

        .cvb-item-fields {
            padding: 12px;
        }

        /* Add new item button */
        .cvb-add-btn {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 7px;
            width: 100%;
            padding: 9px;
            border: 1.5px dashed var(--border-main);
            border-radius: var(--radius-md);
            background: none;
            color: var(--text-muted);
            font-size: 12px;
            font-weight: 700;
            cursor: pointer;
            transition: var(--transition-base);
            font-family: inherit;
            letter-spacing: 0.3px;
        }

        .cvb-add-btn:hover {
            border-color: var(--accent-cyan);
            color: var(--accent-cyan);
            background: rgba(0, 229, 255, 0.04);
        }

        /* ── SKILLS TAG INPUT ── */
        .cvb-tags-container {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
            padding: 8px;
            background: var(--bg-input);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-sm);
            min-height: 44px;
            cursor: text;
            transition: var(--transition-base);
        }

        .cvb-tags-container:focus-within {
            border-color: var(--accent-cyan);
            box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.1);
        }

        .cvb-tag {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            padding: 3px 10px;
            background: rgba(0, 229, 255, 0.1);
            border: 1px solid rgba(0, 229, 255, 0.3);
            border-radius: var(--radius-pill);
            font-size: 12px;
            color: var(--accent-cyan);
            font-weight: 600;
        }

        .cvb-tag-remove {
            cursor: pointer;
            opacity: 0.6;
            transition: opacity 0.2s;
            font-size: 10px;
        }

        .cvb-tag-remove:hover {
            opacity: 1;
            color: var(--accent-red);
        }

        .cvb-tag-input {
            border: none;
            outline: none;
            background: transparent;
            color: var(--text-main);
            font-size: 13px;
            min-width: 80px;
            flex: 1;
            font-family: inherit;
        }

        /* ── TEMPLATE SELECTOR ── */
        .cvb-templates {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
            margin-bottom: 14px;
        }

        .cvb-tpl-btn {
            padding: 8px 6px;
            border: 2px solid var(--border-main);
            border-radius: var(--radius-md);
            background: var(--bg-input);
            color: var(--text-muted);
            font-size: 11px;
            font-weight: 700;
            cursor: pointer;
            transition: var(--transition-base);
            text-align: center;
            font-family: inherit;
        }

        .cvb-tpl-btn:hover,
        .cvb-tpl-btn.active {
            border-color: var(--accent-cyan);
            color: var(--accent-cyan);
            background: rgba(0, 229, 255, 0.06);
        }

        .cvb-tpl-btn.active {
            box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.12);
        }

        /* ═════════════════════════════════════════════════════
           LIVE PREVIEW PANEL
           This renders the actual resume design.
           Each "template" class on #cvb-resume-doc changes layout.
           ═════════════════════════════════════════════════════ */

        .cvb-preview-scroll {
            padding: 16px;
            overflow-y: auto;
            max-height: calc(100vh - 60px);
            scrollbar-width: thin;
            scrollbar-color: var(--border-main) transparent;
        }

        .cvb-preview-scroll::-webkit-scrollbar { width: 4px; }
        .cvb-preview-scroll::-webkit-scrollbar-thumb {
            background: var(--border-main);
            border-radius: 4px;
        }

        /* The printable/exportable resume document */
        #cvb-resume-doc {
            background: #ffffff; /* Resume always white — it's a document */
            color: #1a1a2e;
            border-radius: var(--radius-md);
            min-height: 297mm; /* A4 height */
            width: 100%;
            box-shadow: 0 8px 40px rgba(0,0,0,0.35);
            font-family: 'Georgia', serif;
            line-height: 1.55;
            overflow: hidden;
            position: relative;
        }

        /* ── TEMPLATE: CLASSIC (Default) ── */
        #cvb-resume-doc.tpl-classic .resume-header {
            background: #1a1a2e;
            color: #ffffff;
            padding: 28px 32px 22px;
        }

        #cvb-resume-doc.tpl-classic .resume-name {
            font-size: 26px;
            font-weight: 700;
            letter-spacing: 0.5px;
            color: #fff;
            margin-bottom: 4px;
            font-family: 'Georgia', serif;
        }

        #cvb-resume-doc.tpl-classic .resume-title {
            font-size: 13px;
            color: rgba(255,255,255,0.75);
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin-bottom: 12px;
        }

        #cvb-resume-doc.tpl-classic .resume-contact-bar {
            display: flex;
            flex-wrap: wrap;
            gap: 14px;
            font-size: 11.5px;
            color: rgba(255,255,255,0.8);
        }

        #cvb-resume-doc.tpl-classic .resume-contact-bar span {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        #cvb-resume-doc.tpl-classic .resume-body {
            display: grid;
            grid-template-columns: 1fr 2fr;
            gap: 0;
        }

        #cvb-resume-doc.tpl-classic .resume-sidebar {
            background: #f8f9fa;
            padding: 20px 18px;
            border-right: 1px solid #e9ecef;
        }

        #cvb-resume-doc.tpl-classic .resume-main {
            padding: 20px 24px;
        }

        /* ── TEMPLATE: MODERN ── */
        #cvb-resume-doc.tpl-modern .resume-header {
            background: linear-gradient(135deg, #0f3460 0%, #16213e 100%);
            color: #ffffff;
            padding: 28px 32px 22px;
            position: relative;
        }

        #cvb-resume-doc.tpl-modern .resume-header::after {
            content: '';
            position: absolute;
            bottom: 0; left: 0; right: 0;
            height: 4px;
            background: linear-gradient(90deg, #e94560, #0f3460, #533483);
        }

        #cvb-resume-doc.tpl-modern .resume-name {
            font-size: 28px;
            font-weight: 700;
            color: #fff;
            margin-bottom: 4px;
            font-family: 'Arial', sans-serif;
            letter-spacing: -0.5px;
        }

        #cvb-resume-doc.tpl-modern .resume-title {
            font-size: 13px;
            color: #e94560;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 12px;
            font-family: 'Arial', sans-serif;
        }

        #cvb-resume-doc.tpl-modern .resume-contact-bar {
            display: flex;
            flex-wrap: wrap;
            gap: 16px;
            font-size: 11.5px;
            color: rgba(255,255,255,0.8);
        }

        #cvb-resume-doc.tpl-modern .resume-contact-bar span {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        #cvb-resume-doc.tpl-modern .resume-body {
            display: grid;
            grid-template-columns: 1fr 2.2fr;
            gap: 0;
        }

        #cvb-resume-doc.tpl-modern .resume-sidebar {
            background: #f0f4ff;
            padding: 20px 16px;
        }

        #cvb-resume-doc.tpl-modern .resume-main {
            padding: 20px 24px;
        }

        /* ── TEMPLATE: MINIMAL ── */
        #cvb-resume-doc.tpl-minimal .resume-header {
            background: #fff;
            border-bottom: 3px solid #2d3436;
            padding: 24px 32px 16px;
        }

        #cvb-resume-doc.tpl-minimal .resume-name {
            font-size: 32px;
            font-weight: 900;
            color: #2d3436;
            letter-spacing: -1px;
            margin-bottom: 2px;
            font-family: 'Arial', sans-serif;
        }

        #cvb-resume-doc.tpl-minimal .resume-title {
            font-size: 14px;
            color: #636e72;
            margin-bottom: 10px;
        }

        #cvb-resume-doc.tpl-minimal .resume-contact-bar {
            display: flex;
            flex-wrap: wrap;
            gap: 14px;
            font-size: 12px;
            color: #636e72;
        }

        #cvb-resume-doc.tpl-minimal .resume-contact-bar span {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        #cvb-resume-doc.tpl-minimal .resume-body {
            display: grid;
            grid-template-columns: 1fr 2.5fr;
            gap: 0;
        }

        #cvb-resume-doc.tpl-minimal .resume-sidebar {
            padding: 20px 16px;
            border-right: 1px solid #dfe6e9;
        }

        #cvb-resume-doc.tpl-minimal .resume-main {
            padding: 20px 24px;
        }

        /* ── SHARED RESUME SECTION STYLES ── */
        /* These apply to all templates */

        .res-section {
            margin-bottom: 18px;
        }

        .res-section-title {
            font-size: 10px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: #636e72;
            margin-bottom: 6px;
            padding-bottom: 4px;
            border-bottom: 1px solid #dfe6e9;
        }

        /* Template-specific accent colors for section titles */
        .tpl-classic .res-section-title { border-color: #1a1a2e; color: #1a1a2e; }
        .tpl-modern  .res-section-title { border-color: #e94560; color: #0f3460; }
        .tpl-minimal .res-section-title { border-color: #2d3436; color: #2d3436; }

        .res-entry {
            margin-bottom: 12px;
            position: relative;
        }

        .res-entry-title {
            font-size: 13.5px;
            font-weight: 700;
            color: #1a1a2e;
            margin-bottom: 1px;
        }

        .res-entry-sub {
            font-size: 12px;
            color: #0f3460;
            font-weight: 600;
            margin-bottom: 1px;
        }

        .tpl-modern  .res-entry-sub { color: #e94560; }
        .tpl-minimal .res-entry-sub { color: #636e72; font-weight: 700; }

        .res-entry-date {
            font-size: 11px;
            color: #b2bec3;
            margin-bottom: 4px;
        }

        .res-entry-desc {
            font-size: 12px;
            color: #4a4a6a;
            line-height: 1.55;
        }

        /* Bullet list in description */
        .res-entry-desc ul {
            margin: 3px 0 0 14px;
        }

        .res-entry-desc li {
            margin-bottom: 2px;
        }

        /* Summary paragraph */
        .res-summary {
            font-size: 12.5px;
            color: #4a4a6a;
            line-height: 1.6;
        }

        /* Skills tag cloud */
        .res-skill-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 5px;
        }

        .res-skill-tag {
            display: inline-block;
            padding: 3px 9px;
            border-radius: var(--radius-pill);
            font-size: 11px;
            font-weight: 700;
        }

        .tpl-classic .res-skill-tag {
            background: rgba(26,26,46,0.08);
            color: #1a1a2e;
        }

        .tpl-modern .res-skill-tag {
            background: #e8eaf6;
            color: #0f3460;
        }

        .tpl-minimal .res-skill-tag {
            background: #f5f5f5;
            color: #2d3436;
            border: 1px solid #dfe6e9;
        }

        /* Language bar */
        .res-lang-item {
            margin-bottom: 7px;
        }

        .res-lang-label {
            display: flex;
            justify-content: space-between;
            font-size: 12px;
            margin-bottom: 3px;
            color: #4a4a6a;
        }

        .res-lang-bar {
            height: 4px;
            background: #f0f0f0;
            border-radius: 2px;
            overflow: hidden;
        }

        .res-lang-fill {
            height: 100%;
            background: #1a1a2e;
            border-radius: 2px;
        }

        .tpl-modern  .res-lang-fill { background: #e94560; }
        .tpl-minimal .res-lang-fill { background: #2d3436; }

        /* QR Code in resume */
        #cvb-qr-canvas {
            display: block;
            margin: 8px 0;
        }

        /* Empty state placeholder in preview */
        .cvb-preview-empty {
            text-align: center;
            padding: 40px 20px;
            color: var(--text-muted);
        }

        .cvb-preview-empty i {
            font-size: 36px;
            opacity: 0.3;
            display: block;
            margin-bottom: 12px;
        }

        /* ═════════════════════════════════════════════════════
           ATS MATCHER SECTION
           Full-width section below the split screen.
           ═════════════════════════════════════════════════════ */

        .cvb-ats-wrapper {
            margin-top: 20px;
            background: var(--bg-card);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-lg);
            overflow: hidden;
        }

        .cvb-ats-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 14px 18px;
            background: var(--bg-container);
            border-bottom: 1px solid var(--border-main);
        }

        .cvb-ats-body {
            padding: 18px;
        }

        .cvb-ats-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;
            margin-bottom: 16px;
        }

        .cvb-ats-result {
            background: var(--bg-container);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-md);
            padding: 16px;
        }

        /* Score display */
        .cvb-score-display {
            text-align: center;
            margin-bottom: 14px;
        }

        .cvb-score-number {
            font-size: 52px;
            font-weight: 900;
            line-height: 1;
            background: var(--gradient-text);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .cvb-score-label {
            font-size: 11px;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-top: 4px;
        }

        /* Score gauge ring */
        .cvb-score-ring {
            position: relative;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 120px;
            height: 120px;
            margin: 0 auto 10px;
        }

        .cvb-score-ring svg {
            position: absolute;
            top: 0; left: 0;
            transform: rotate(-90deg);
        }

        .cvb-score-ring-track {
            fill: none;
            stroke: var(--border-main);
            stroke-width: 8;
        }

        .cvb-score-ring-fill {
            fill: none;
            stroke: url(#scoreGrad);
            stroke-width: 8;
            stroke-linecap: round;
            transition: stroke-dashoffset 1s ease;
        }

        /* Keyword lists */
        .cvb-kw-list {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        .cvb-kw-tag {
            padding: 3px 10px;
            border-radius: var(--radius-pill);
            font-size: 11.5px;
            font-weight: 600;
        }

        .cvb-kw-tag.found {
            background: var(--status-success-bg);
            color: var(--status-text-success);
            border: 1px solid var(--status-success-border);
        }

        .cvb-kw-tag.missing {
            background: var(--status-error-bg);
            color: var(--accent-red);
            border: 1px solid rgba(255, 71, 87, 0.3);
        }

        /* ═════════════════════════════════════════════════════
           TOOLBAR / ACTION BAR (below form panel)
           ═════════════════════════════════════════════════════ */

        .cvb-toolbar {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            padding: 12px 16px;
            background: var(--bg-container);
            border-top: 1px solid var(--border-main);
            flex-shrink: 0;
        }

        .cvb-toolbar .btn {
            flex: 1;
            min-width: 100px;
            padding: 10px 12px;
            font-size: 12px;
        }

        /* Autosave indicator */
        .cvb-autosave-indicator {
            display: flex;
            align-items: center;
            gap: 5px;
            font-size: 11px;
            color: var(--text-muted);
            padding: 6px 10px;
            border-radius: var(--radius-pill);
            background: var(--bg-card);
            border: 1px solid var(--border-main);
        }

        .cvb-autosave-indicator.saved {
            color: var(--status-text-success);
            border-color: var(--status-success-border);
            background: var(--status-success-bg);
        }

        .cvb-autosave-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: currentColor;
        }

        /* ═════════════════════════════════════════════════════
           PROGRESS BAR at top of page
           ═════════════════════════════════════════════════════ */

        .cvb-progress-bar {
            height: 3px;
            background: var(--border-main);
            border-radius: 2px;
            margin-bottom: 16px;
            overflow: hidden;
        }

        .cvb-progress-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
            border-radius: 2px;
            transition: width 0.4s ease;
            width: 0%;
        }

        /* ═════════════════════════════════════════════════════
           SECTION COMPLETION DOTS
           ═════════════════════════════════════════════════════ */

        .cvb-section-status {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--border-main);
            transition: background 0.3s ease;
            flex-shrink: 0;
        }

        .cvb-section-status.complete {
            background: var(--accent-green);
            box-shadow: 0 0 6px rgba(46, 204, 113, 0.5);
        }

        /* ═════════════════════════════════════════════════════
           MODAL for QR Code preview
           ═════════════════════════════════════════════════════ */

        .cvb-modal-overlay {
            display: none;
            position: fixed;
            inset: 0;
            z-index: 9999;
            background: var(--bg-overlay-heavy);
            align-items: center;
            justify-content: center;
            padding: 20px;
        }

        .cvb-modal-overlay.active {
            display: flex;
        }

        .cvb-modal-box {
            background: var(--bg-container);
            border: 1px solid var(--border-main);
            border-radius: var(--radius-lg);
            padding: 24px;
            max-width: 380px;
            width: 100%;
            text-align: center;
            box-shadow: var(--shadow-card);
        }

        .cvb-modal-title {
            font-size: 16px;
            font-weight: 700;
            color: var(--text-main);
            margin-bottom: 16px;
        }

        #cvb-qr-preview {
            display: flex;
            justify-content: center;
            margin: 12px 0 20px;
        }

        /* ── Drag-and-drop "ghost" / sortable styles ── */
        .sortable-ghost {
            opacity: 0.3;
            background: rgba(0, 229, 255, 0.05) !important;
            border: 2px dashed var(--accent-cyan) !important;
        }

        .sortable-chosen {
            box-shadow: 0 8px 24px rgba(0, 229, 255, 0.2);
        }

        /* ═════════════════════════════════════════════════════
           RESPONSIVE — MOBILE FIRST
           At ≤ 900px, split becomes single column (stacked)
           ═════════════════════════════════════════════════════ */

        @media (max-width: 900px) {
            .cvb-split {
                grid-template-columns: 1fr;
            }

            .cvb-form-panel {
                position: static;
                max-height: none;
            }

            .cvb-form-scroll {
                max-height: 500px;
            }

            .cvb-preview-scroll {
                max-height: none;
            }

            .cvb-ats-grid {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 600px) {
            .cvb-field-row {
                grid-template-columns: 1fr;
            }

            .cvb-templates {
                grid-template-columns: 1fr 1fr;
            }

            #cvb-resume-doc .resume-body {
                grid-template-columns: 1fr !important;
            }

            #cvb-resume-doc .resume-sidebar {
                border-right: none !important;
                border-bottom: 1px solid #e9ecef;
            }

            .cvb-toolbar {
                gap: 6px;
            }

            .cvb-toolbar .btn {
                font-size: 11px;
                padding: 9px 8px;
            }

            .cvb-panel-actions {
                gap: 4px;
            }

            .cvb-icon-btn {
                padding: 5px 9px;
                font-size: 10px;
            }
        }

        @media (max-width: 480px) {
            .cvb-score-number {
                font-size: 38px;
            }

            .cvb-templates {
                grid-template-columns: 1fr 1fr 1fr;
            }
        }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    /*
 * =============================================================================
 *  DATA VAULT ULTRA MAX — style.css
 *  Tool-Specific Stylesheet
 *  Author  : MD KAWSAR
 *  Version : 1.0 (CodeCanyon Release Build)
 *  Scope   : sec-file-encryptor page only — uses global CSS vars
 *  Path    : ../../assets/tools/sec/sec-file-encryptor/style.css
 * =============================================================================
 *
 *  TABLE OF CONTENTS
 *  ─────────────────────────────────────────────────────────────────────────
 *  SECTION 1  : Mode Tabs (Encrypt / Decrypt)
 *  SECTION 2  : Vault Panel (animated reveal)
 *  SECTION 3  : Decoy Vault Toggle Row
 *  SECTION 4  : Drop Zones
 *  SECTION 5  : Password Fields & Eye Toggle
 *  SECTION 6  : Password Strength Meter
 *  SECTION 7  : Progress Bar
 *  SECTION 8  : Action Buttons
 *  SECTION 9  : Vault Status Card
 *  SECTION 10 : How-To Quick Guide Strip
 *  SECTION 11 : Info Section & Info Cards
 *  SECTION 12 : Ad Slot Spacing
 *  SECTION 13 : Responsive Overrides (≤ 600px, ≤ 480px)
 *  SECTION 14 : Animations & Keyframes
 * =============================================================================
 */


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 1: MODE TABS
   ───────────────────────────────────────────────────────────────────────── */

.vault-tabs {
    display: flex;
    gap: 0;
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-pill);
    padding: 4px;
    margin: 0 auto 28px;
    max-width: 340px;
    position: relative;
}

.vault-tab {
    flex: 1;
    padding: 10px 18px;
    border: none;
    border-radius: var(--radius-pill);
    background: transparent;
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-base);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    white-space: nowrap;
}

.vault-tab:hover {
    color: var(--text-main);
    background: var(--border-subtle);
}

/* Active state — glowing pill */
.vault-tab.active {
    background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
    color: #fff;
    box-shadow: 0 4px 16px rgba(255, 0, 85, 0.35);
}

/* Decrypt tab active — cyan theme */
#tab-decrypt.active {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    color: #000;
    box-shadow: 0 4px 16px rgba(0, 229, 255, 0.35);
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 2: VAULT PANEL
   ───────────────────────────────────────────────────────────────────────── */

.vault-panel {
    display: none;
    animation: vaultPanelIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.vault-panel.active {
    display: block;
}

@keyframes vaultPanelIn {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 3: DECOY VAULT TOGGLE ROW
   ───────────────────────────────────────────────────────────────────────── */

.decoy-toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    padding: 14px 18px;
    margin-bottom: 8px;
    flex-wrap: wrap;
}

.decoy-toggle-label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    font-weight: 600;
    color: var(--text-main);
    cursor: pointer;
    user-select: none;
}

.badge-new {
    background: linear-gradient(90deg, var(--accent-purple), var(--brand-primary));
    color: #fff;
    font-size: 10px;
    font-weight: 800;
    padding: 2px 7px;
    border-radius: var(--radius-pill);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

/* Hint text below toggle */
.decoy-hint {
    font-size: 12.5px;
    color: var(--text-muted);
    background: var(--status-info-bg);
    border: 1px solid rgba(31, 111, 235, 0.2);
    border-radius: var(--radius-sm);
    padding: 10px 14px;
    margin-bottom: 20px;
    text-align: left;
    line-height: 1.6;
    display: flex;
    gap: 8px;
    align-items: flex-start;
}

.decoy-hint i {
    flex-shrink: 0;
    color: var(--accent-cyan);
    margin-top: 2px;
}

/* ─── Custom Toggle Switch ─── */
.toggle-switch {
    position: relative;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
    position: absolute;
}

.toggle-track {
    position: absolute;
    inset: 0;
    background: var(--border-main);
    border-radius: var(--radius-pill);
    cursor: pointer;
    transition: background 0.3s ease;
    display: flex;
    align-items: center;
}

.toggle-thumb {
    position: absolute;
    left: 3px;
    width: 20px;
    height: 20px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: 0 2px 6px rgba(0,0,0,0.3);
}

.toggle-switch input:checked ~ .toggle-track {
    background: linear-gradient(90deg, var(--accent-purple), var(--brand-primary));
}

.toggle-switch input:checked ~ .toggle-track .toggle-thumb {
    transform: translateX(22px);
}

.toggle-switch input:focus-visible ~ .toggle-track {
    outline: 2px solid var(--accent-cyan);
    outline-offset: 2px;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 4: DROP ZONES
   ───────────────────────────────────────────────────────────────────────── */

.dropzone-wrapper {
    margin-bottom: 20px;
    text-align: left;
}

.dropzone-label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.dropzone-label.decoy-label {
    color: var(--accent-purple);
}

.label-tag {
    font-size: 11px;
    font-weight: 500;
    color: var(--text-muted);
    background: var(--bg-input);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-pill);
    padding: 2px 8px;
    text-transform: none;
    letter-spacing: 0;
}

/* Main drop zone */
.dropzone {
    position: relative;
    border: 2px dashed var(--border-main);
    border-radius: var(--radius-lg);
    padding: 32px 20px;
    text-align: center;
    cursor: pointer;
    transition: var(--transition-base);
    background: var(--bg-card);
    overflow: hidden;
    min-height: 130px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;

    /* Glassmorphism shimmer overlay */
    background-image:
        radial-gradient(ellipse at 20% 50%, rgba(255, 0, 85, 0.04) 0%, transparent 60%),
        radial-gradient(ellipse at 80% 50%, rgba(0, 229, 255, 0.04) 0%, transparent 60%);
}

/* Glowing animated border on hover/focus */
.dropzone:hover,
.dropzone:focus {
    border-color: var(--accent-cyan);
    background-color: rgba(0, 229, 255, 0.04);
    box-shadow: 0 0 0 4px rgba(0, 229, 255, 0.08), inset 0 0 20px rgba(0, 229, 255, 0.04);
    outline: none;
}

/* Drag-over state */
.dropzone.drag-over {
    border-color: var(--brand-primary);
    background-color: rgba(255, 0, 85, 0.05);
    box-shadow: 0 0 0 4px rgba(255, 0, 85, 0.12), inset 0 0 30px rgba(255, 0, 85, 0.06);
    transform: scale(1.01);
}

/* File selected state */
.dropzone.has-file {
    border-color: var(--accent-green);
    border-style: solid;
    background-color: rgba(46, 204, 113, 0.04);
}

/* Decoy dropzone variant */
.dropzone--decoy:hover,
.dropzone--decoy:focus {
    border-color: var(--accent-purple);
    background-color: rgba(209, 36, 255, 0.04);
    box-shadow: 0 0 0 4px rgba(209, 36, 255, 0.08);
}

.dropzone--decoy.has-file {
    border-color: var(--accent-purple);
    border-style: solid;
}

/* Drop zone icon */
.dropzone-icon {
    font-size: 36px;
    color: var(--text-muted);
    transition: var(--transition-base);
    line-height: 1;
}

.dropzone:hover .dropzone-icon,
.dropzone:focus .dropzone-icon {
    color: var(--accent-cyan);
    transform: translateY(-3px) scale(1.1);
}

.dropzone.has-file .dropzone-icon {
    color: var(--accent-green);
}

.dropzone--decoy .dropzone-icon {
    color: var(--accent-purple);
    opacity: 0.6;
}

/* Drop zone text */
.dropzone-text {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 14px;
    color: var(--text-muted);
}

.dropzone-text strong {
    color: var(--text-main);
    font-size: 15px;
}

.dropzone-text u {
    color: var(--accent-cyan);
    text-decoration-color: rgba(0, 229, 255, 0.4);
}

/* File metadata (shown after selection) */
.dropzone-meta {
    font-size: 12px;
    color: var(--accent-green);
    font-weight: 600;
    margin-top: 4px;
    word-break: break-all;
    max-width: 90%;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 5: PASSWORD FIELDS & EYE TOGGLE
   ───────────────────────────────────────────────────────────────────────── */

.password-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 4px;
}

@media (max-width: 640px) {
    .password-grid {
        grid-template-columns: 1fr;
    }
}

.field-group {
    text-align: left;
}

.field-label {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 8px;
}

.field-label.decoy-label {
    color: var(--accent-purple);
}

.password-input-wrap {
    position: relative;
    display: flex;
    align-items: center;
}

/* Base input style */
.vault-input {
    width: 100%;
    padding: 12px 44px 12px 14px;
    background: var(--bg-input);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-md);
    color: var(--text-main);
    font-size: 14px;
    font-family: 'Courier New', monospace;
    transition: var(--transition-base);
    outline: none;
    color-scheme: var(--input-scheme);
}

.vault-input:focus {
    border-color: var(--accent-cyan);
    box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.1);
    background: var(--bg-card);
}

.vault-input::placeholder {
    font-family: 'Segoe UI', sans-serif;
    font-size: 13px;
    color: var(--text-muted);
    opacity: 0.7;
}

/* Decoy input variant */
.vault-input--decoy:focus {
    border-color: var(--accent-purple);
    box-shadow: 0 0 0 3px rgba(209, 36, 255, 0.1);
}

/* Eye toggle button */
.eye-btn {
    position: absolute;
    right: 12px;
    background: none;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    padding: 4px;
    font-size: 14px;
    transition: color 0.2s ease;
    line-height: 1;
}

.eye-btn:hover {
    color: var(--accent-cyan);
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 6: PASSWORD STRENGTH METER
   ───────────────────────────────────────────────────────────────────────── */

.strength-bar-wrap {
    height: 4px;
    background: var(--border-main);
    border-radius: 4px;
    margin-top: 8px;
    overflow: hidden;
}

.strength-bar {
    height: 100%;
    width: 0%;
    border-radius: 4px;
    transition: width 0.4s ease, background 0.4s ease;
}

/* Strength levels set via JS by adding data-level attribute */
.strength-bar[data-level="1"] { width: 25%; background: var(--accent-red); }
.strength-bar[data-level="2"] { width: 50%; background: var(--accent-orange); }
.strength-bar[data-level="3"] { width: 75%; background: var(--accent-yellow); }
.strength-bar[data-level="4"] { width: 100%; background: var(--accent-green); box-shadow: 0 0 8px rgba(46, 204, 113, 0.5); }

.strength-label {
    font-size: 11px;
    font-weight: 600;
    margin-top: 5px;
    display: block;
    letter-spacing: 0.3px;
}

.strength-label.weak   { color: var(--accent-red); }
.strength-label.fair   { color: var(--accent-orange); }
.strength-label.good   { color: var(--accent-yellow); }
.strength-label.strong { color: var(--accent-green); }


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 7: PROGRESS BAR
   ───────────────────────────────────────────────────────────────────────── */

.progress-wrapper {
    margin: 20px 0 8px;
    text-align: left;
}

.progress-track {
    height: 8px;
    background: var(--bg-input);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-pill);
    overflow: hidden;
    margin-bottom: 6px;
}

.progress-fill {
    height: 100%;
    width: 0%;
    background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
    border-radius: var(--radius-pill);
    transition: width 0.2s ease;
    position: relative;
    overflow: hidden;
}

/* Shimmer animation on the progress fill */
.progress-fill::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 60%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
    animation: shimmerSlide 1.2s infinite;
}

@keyframes shimmerSlide {
    0%   { left: -60%; }
    100% { left: 140%; }
}

/* Decrypt variant — cyan */
.progress-fill--cyan {
    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-blue));
}

.progress-label {
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 500;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 8: ACTION BUTTONS
   ───────────────────────────────────────────────────────────────────────── */

.btn-encrypt,
.btn-decrypt {
    width: 100%;
    padding: 15px 24px;
    border: none;
    border-radius: var(--radius-md);
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 22px;
    transition: var(--transition-base);
    letter-spacing: 0.3px;
    position: relative;
    overflow: hidden;
    min-height: 52px;
}

/* Encrypt — crimson/purple gradient */
.btn-encrypt {
    background: linear-gradient(135deg, var(--brand-primary) 0%, var(--accent-purple) 100%);
    color: #fff;
    box-shadow: 0 6px 24px rgba(255, 0, 85, 0.3);
}

.btn-encrypt:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 10px 32px rgba(255, 0, 85, 0.45);
    filter: brightness(1.08);
}

/* Decrypt — cyan/blue gradient */
.btn-decrypt {
    background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-blue) 100%);
    color: #000;
    box-shadow: 0 6px 24px rgba(0, 229, 255, 0.25);
}

.btn-decrypt:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 10px 32px rgba(0, 229, 255, 0.4);
    filter: brightness(1.08);
}

/* Disabled state during processing */
.btn-encrypt:disabled,
.btn-decrypt:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
}

/* Ripple effect on click (added via JS) */
.btn-encrypt::after,
.btn-decrypt::after {
    content: '';
    position: absolute;
    width: 0;
    height: 0;
    background: rgba(255,255,255,0.2);
    border-radius: 50%;
    transform: translate(-50%, -50%);
    transition: width 0.5s ease, height 0.5s ease, opacity 0.5s ease;
    opacity: 0;
    pointer-events: none;
}

.btn-encrypt.ripple::after,
.btn-decrypt.ripple::after {
    width: 300px;
    height: 300px;
    opacity: 0;
}

/* Active press */
.btn-encrypt:active:not(:disabled),
.btn-decrypt:active:not(:disabled) {
    transform: translateY(1px) scale(0.99);
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 9: VAULT STATUS CARD
   ───────────────────────────────────────────────────────────────────────── */

.vault-status-card {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 20px;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-main);
    margin-top: 18px;
    animation: statusSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    text-align: left;
    background: var(--bg-card);
}

@keyframes statusSlideIn {
    from { opacity: 0; transform: translateY(10px) scale(0.98); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}

.vault-status-card.success {
    border-color: var(--status-success-border);
    background: var(--status-success-bg);
}

.vault-status-card.error {
    border-color: rgba(255, 71, 87, 0.35);
    background: var(--status-error-bg);
}

.vault-status-icon {
    font-size: 28px;
    flex-shrink: 0;
    line-height: 1;
}

.vault-status-card.success .vault-status-icon { color: var(--status-text-success); }
.vault-status-card.error   .vault-status-icon { color: var(--accent-red); }

.vault-status-body {
    flex: 1;
    min-width: 0;
}

.vault-status-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--text-main);
    margin-bottom: 3px;
}

.vault-status-sub {
    font-size: 12.5px;
    color: var(--text-muted);
    word-break: break-all;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 10: HOW-TO QUICK GUIDE STRIP
   ───────────────────────────────────────────────────────────────────────── */

.how-to-strip {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 28px;
    padding: 18px;
    background: var(--bg-card);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-md);
}

.how-to-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    max-width: 140px;
    text-align: center;
}

.how-to-num {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--brand-primary), var(--accent-purple));
    color: #fff;
    font-size: 14px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: 0 3px 10px rgba(255, 0, 85, 0.3);
}

.how-to-step p {
    font-size: 12.5px;
    color: var(--text-muted);
    line-height: 1.5;
}

.how-to-step p strong {
    color: var(--text-main);
}

.how-to-arrow {
    color: var(--border-main);
    font-size: 14px;
    flex-shrink: 0;
}

@media (max-width: 500px) {
    .how-to-arrow {
        display: none;
    }

    .how-to-strip {
        flex-direction: column;
        gap: 16px;
    }

    .how-to-step {
        flex-direction: row;
        max-width: 100%;
        text-align: left;
        gap: 12px;
    }
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 11: INFO SECTION & INFO CARDS
   ───────────────────────────────────────────────────────────────────────── */

.info-section-wrapper {
    margin-top: 10px;
    text-align: left;
}

.info-hero-img {
    text-align: center;
    margin-bottom: 30px;
}

.info-hero-img img {
    border-radius: var(--radius-lg);
    max-width: 100%;
    border: 1px solid var(--border-subtle);
}

.info-card {
    background: var(--bg-card);
    border: 1px solid var(--border-main);
    border-radius: var(--radius-lg);
    padding: 24px 28px;
    margin-bottom: 20px;
    border-left: 4px solid var(--brand-primary);
    transition: var(--transition-base);
}

.info-card:hover {
    border-color: var(--accent-cyan);
    border-left-color: var(--accent-cyan);
    box-shadow: 0 4px 20px rgba(0, 229, 255, 0.08);
    transform: translateY(-2px);
}

.info-card h2 {
    font-size: 17px;
    font-weight: 700;
    color: var(--text-main);
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    border-left: none;
    padding-left: 0;
}

.info-card h2 i {
    color: var(--accent-cyan);
    font-size: 15px;
}

.info-card p {
    font-size: 14px;
    color: var(--text-muted);
    line-height: 1.75;
    margin-bottom: 12px;
}

.info-card p:last-child {
    margin-bottom: 0;
}

.info-card ul,
.info-card ol {
    padding-left: 20px;
    color: var(--text-muted);
    font-size: 14px;
    line-height: 1.75;
    margin-bottom: 12px;
}

.info-card li {
    margin-bottom: 8px;
}

.info-card li:last-child {
    margin-bottom: 0;
}

.info-card strong {
    color: var(--text-main);
    font-weight: 600;
}

.info-card code {
    background: var(--bg-input);
    border: 1px solid var(--border-main);
    padding: 1px 6px;
    border-radius: 4px;
    font-size: 12.5px;
    color: var(--accent-cyan);
}

.info-card sup {
    font-size: 10px;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 12: AD SLOT SPACING
   ───────────────────────────────────────────────────────────────────────── */

.ad-slot {
    width: 100%;
    max-width: 950px;
    text-align: center;
}

.ad-slot--top {
    margin-bottom: 16px;
}

.ad-slot--mid {
    margin: 20px 0;
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 13: RESPONSIVE OVERRIDES
   ───────────────────────────────────────────────────────────────────────── */

@media (max-width: 600px) {

    .vault-tabs {
        max-width: 100%;
    }

    .vault-tab {
        font-size: 13px;
        padding: 10px 12px;
    }

    .dropzone {
        padding: 24px 14px;
        min-height: 110px;
    }

    .dropzone-icon {
        font-size: 28px;
    }

    .dropzone-text strong {
        font-size: 14px;
    }

    .btn-encrypt,
    .btn-decrypt {
        font-size: 14px;
        padding: 14px 18px;
    }

    .decoy-toggle-row {
        flex-wrap: wrap;
        gap: 10px;
    }

    .info-card {
        padding: 18px 16px;
    }

    .info-card h2 {
        font-size: 15px;
    }
}

@media (max-width: 480px) {

    .vault-tab i {
        /* On very small screens keep icons for tab buttons */
        font-size: 12px;
    }

    .vault-tab {
        font-size: 12px;
        padding: 9px 8px;
    }

    .how-to-strip {
        padding: 14px;
    }

    .vault-status-card {
        flex-direction: column;
        text-align: center;
        gap: 10px;
    }

    .vault-status-body {
        text-align: center;
    }
}


/* ─────────────────────────────────────────────────────────────────────────
   SECTION 14: EXTRA ANIMATIONS & KEYFRAMES
   ───────────────────────────────────────────────────────────────────────── */

/* Used by the container animated-entry class (defined in global) */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(24px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Pulse for the vault icon on success */
@keyframes vaultPulse {
    0%, 100% { transform: scale(1); }
    50%       { transform: scale(1.12); }
}

.vault-status-card.success .vault-status-icon {
    animation: vaultPulse 1.2s ease infinite;
}

/* Scanning line animation used internally */
@keyframes scanLine {
    0%   { top: 0%; opacity: 0.8; }
    100% { top: 100%; opacity: 0; }
}
